class IntGraph(n: Int) {
    val size: Int = n + 1;
    val matrix: Array[Array[Int]] = Array.ofDim[Int](size, size);
    def add(src: Int, dst: Int): Unit = matrix(src)(dst) = 1;

    def dSearch(): Array[Array[Int]] = {
        val status = Array.ofDim[Int](size, 2);
        def _dSearch(curr: Int, time: Int): Int = {
            status(curr)(0) = time;
            val newTime = 1 + (1 until size).foldLeft(time) { (t, i) =>
                if (matrix(curr)(i) == 1 && status(i)(0) == 0) _dSearch(i, t + 1) else t;
            }
            status(curr)(1) = newTime;
            newTime;
        }
        (1 until size).foldLeft(0) { (time, i)=>
            if (status(i)(0) == 0) {
                _dSearch(i, time + 1);
            } else {
                time;
            }
        }
        status;
    }
}

import scala.io.StdIn._

object Main extends App {
  val n = readInt()
  val graph = collection.mutable.Seq.fill(n, n)(0)

  for (i <- 1 to n) {
    val input = readLine().split(" ").toList.map(_.toInt)
    val u = input.head - 1
    val k = input(1)
    for (j <- 1 to k) {
      graph(u)(input(1 + j) - 1) = 1
    }
  }

  var foundTime = List.fill(n)(-1)
  var finishedTime = List.fill(n)(-1)

  var time = 0

  def search(id: Int): Unit = {
    for (i <- graph(id).indices) {
      if (graph(id)(i) == 1 && foundTime(i) == -1) {
        time += 1
        foundTime = foundTime.updated(i, time)
        search(i)
      }
    }
    time += 1
    finishedTime = finishedTime.updated(id, time)
  }

  while (foundTime contains -1) {
    time += 1
    val index = foundTime indexOf -1
    foundTime = foundTime.updated(index, time)
    search(index)
  }

  for (i <- graph.indices) {
    println(s"${i + 1} ${foundTime(i)} ${finishedTime(i)}")
  }
}

