void dfs(vec<vec<int>> &G, int v, int &count, vec<pair<int,int>> &verts, vec<bool> &seen) {
    seen[v] = true;
    int enterCount = count;
    count++;

    // v から行ける各頂点 next_v について
    for (auto next_v : G[v]) {
        if (!seen[next_v]) {
            dfs(G, next_v, count, verts, seen); // 再帰的に探索
            count++;
        }
    }
    verts[v] = make_pair(enterCount, count);
}

