#include <iostream>
#include <stack>

using namespace std;

static const int MAX = 100;
static const int WHITE = 1;
static const int GRAY = 2;
static const int BLACK = 3;
static const int NIL = -1;

class DFS{
private:
    int color[MAX];
    int M[MAX][MAX];
    stack<int> S;
    int n;
    int discovery[MAX];
    int finish[MAX];
    int time = 0;
    int next_vertex[MAX];
public:
    DFS()
    {
        cin >> n;
        for(int i = 0; i < n; i++)
            for(int j = 0; j < n; j++)
                M[i][j] = 0;
        int vertex;
        int degree;
        for(int i = 0; i < n; i++)
        {
            color[i] = WHITE;
            next_vertex[i] = 0;
            cin >> vertex;
            cin >> degree;
            int to_v;
            for(int j = 0; j < degree; j++)
            {
                cin >> to_v;
                M[vertex - 1][to_v - 1] = 1;
            }
        }
    }

    int next(int u)
    {
        for(int v = next_vertex[u]; v < n; v++)
        {
            next_vertex[u] = v + 1;
            if(M[u][v]) return v;
        }
        return NIL;
    }

    void dfs_visit(int start)
    {
        for(int i = 0; i < n; i++)
            next_vertex[i] = 0;

        S.push(start);
        color[start] = GRAY;
        discovery[start] = ++time;

        while(S.size() != 0)
        {
            int u = S.top();
            int v = next(u);
            if(v != NIL)
            {
                if(color[v] == WHITE)
                {
                    color[v] = GRAY;
                    discovery[v] = ++time;
                    S.push(v);
                }
            }
            else
            {
                S.pop();
                color[u] = BLACK;
                finish[u] = ++time;
            }
        }
    }

    void dfs()
    {
        for(int u = 0; u < n; u++)
        {
            if(color[u] == WHITE)
                dfs_visit(u);
        }

        for(int i = 0; i < n; i++)
            cout << i + 1 << " " << discovery[i] << " " << finish[i] << endl;
    }
};

