int t = 0;

class Node{
  public:
  int _id, _findTime, _finishTime;
  vector<int> _edgeId;  // 隣接する頂点
  int _isFound;

  void init(){
    int dim;
    _findTime = _finishTime = 0;
    _isFound = false;
    cin >> _id >> dim;

    for(auto j = 0; j < dim; j++){
      int in;
      cin >> in;
      _edgeId.push_back(in);
    }
  }
};

void DepthFirstSearch(vector<Node>& vertices, int key){
  vertices[key]._isFound = true;
  vertices[key]._findTime = ++t;
  for(auto i = 1; i < vertices.size(); i++){
    auto result = find(vertices[key]._edgeId.begin(), vertices[key]._edgeId.end(), i);
    if(result == vertices[key]._edgeId.end()) continue;
    if(!vertices[i]._isFound){
      DepthFirstSearch(vertices, i);
    }
  }
  vertices[key]._isFound = true;
  vertices[key]._finishTime = ++t;
}

void PrintResult(vector<Node> vertices){
  for(auto i = 1; i < vertices.size(); i++){
    cout << vertices[i]._id << " " << vertices[i]._findTime << " " << vertices[i]._finishTime << '\n';
  }
}

int main(){
  int n;
  cin >> n;
  vector<Node> vertices(n + 1);

  for(auto i = 1; i <= n; i++){
    vertices[i].init();
  }

  for(auto i = 1; i <= n; i++) {
    if(!vertices[i]._isFound)
      DepthFirstSearch(vertices, i);
  }
  PrintResult(vertices);

  return 0;
}

