//ALDS1_11_B 深さ優先探索の問題
//再帰で解く

void dfs(vector<vector<int>> &G, int s, int &counter,vector<vector<int>> &res,vector<bool> &seen) {
	if (G[s].size() == 0) {
		counter++;
		res[s][1] = counter;
		counter++;
		res[s][2] = counter;
		return;
	}

	counter++;
	res[s][1] = counter;

	for (int i = 0; i < G[s].size(); i++) {
		if (seen[G[s][i]] == true) {
			continue;
		}
		seen[G[s][i]] = true;
		dfs(G, G[s][i],counter,res,seen);

	}
	counter++;
	res[s][2] = counter;
}

