	}

	int aa = 0;
	vector<bool> seen(n + 1,false);
	for (int i = 1; i<= n; i++) {
		if (seen[i]) { continue; }
		seen[i] = true;
		dfs(G, i, aa, res, seen);
	}

	for (int i = 1; i <= n; i++) {
		cout << res[i][0] << " " << res[i][1] << " " << res[i][2] << endl;
