// 素数判定
bool is_prime(ll n)
{
	bool flg = true;
	if (n <= 1)
		flg = false;
	else if (n == 2)
		flg = true;
	else if (n % 2 == 0)
		flg = false;
	else
	{
		for (ll i = 3; i * i <= n; i += 2)
		{
			if (n % i == 0)
				flg = false;
		}
	}
	return flg;
}

// 素因数分解
// iで割った回数をcnt_pf[i - 1]に格納している
// cnt_pf[0]に入力が素数だった場合にその素数が入る
vector<ll> prime_factorization(ll n)
{
	vector<ll> cnt_pf(sqrt(n), 0);
	FOR(i, 1, SZ(cnt_pf))
	{
		while (n % (i + 1) == 0)
		{
			cnt_pf[i]++;
			n /= (i + 1);
		}
		if (n == 1)
			break;
	}
	if (n != 1)
	{
		cnt_pf[0] = n;
	}
	return cnt_pf;
}

// 迷路のマップ情報をベクトル化する
// 通れるところを0に、壁を-1にする
// スタート地点からの距離を格納するときなどに使う
vector<vector<ll>> map_vec(vector<string>& str)
{
	// SZ(str[0] = SZ(str[distance(str.begin(), max_element(ALL(str)))])
	vector<vector<ll>> v(SZ(str), vector<ll>(SZ(str[distance(str.begin(), max_element(ALL(str)))]), (int)INF));
	REP(i, SZ(str))
	{
		REP(j, SZ(str[i]))
		{
			if (str[i][j] == WALL)
				v[i][j] = -1;
			//else	v[i][j] = INF;	// if (str[i][j] == '.')
		}
	}
	return v;
}
// str中のWALL='#'の数を数える
ll cnt_wall(vector<string> str)
{
	ll cnt = 0;
	REP(i, SZ(str))
	{
		REP(j, SZ(str[i]))
		{
			if (str[i][j] == WALL)
				cnt++;
		}
	}
	return cnt;
}

// 迷路用幅優先探索
// フィールドの広さと壁の位置を受け取り、ゴールへの最短距離を返す
ll bfs_maze(vector<string>& str, ll s_y, ll s_x, ll g_y, ll g_x)
{
	struct Corr
	{
		ll y;
		ll x;
		ll depth;
	};
	queue<Corr> que;
	// SZ(str[0] = SZ(str[distance(str.begin(), max_element(ALL(str)))])
	vector<vector<ll>> v(SZ(str), vector<ll>(SZ(str[distance(str.begin(), max_element(ALL(str)))])));
	v = map_vec(str);

	// スタート地点を含めるのか
	que.push({ s_y, s_x, 0 });
	while (!que.empty())
	{
		Corr now = que.front();
		que.pop();
		if (now.y == g_y && now.x == g_x)
			break;

		REP(i, 4)
		{
			Corr next = { now.y + dy[i], now.x + dx[i], now.depth + 1 };
			// SZ(v[0] = SZ(v[distance(v.begin(), max_element(ALL(v)))])
			if (0 <= (int)next.y && (int)next.y < SZ(v) && 0 <= (int)next.x && (int)next.x < SZ(v[distance(v.begin(), max_element(ALL(v)))]) && v[(int)next.y][(int)next.x] == INF)
			{
				v[(int)next.y][(int)next.x] = next.depth;
				que.push(next);
			}
		}
	}

	return v[(int)g_y][(int)g_x];
}

// 累積和
vector<ll> cumulative_sum(vector<ll> a)
{
	vector<ll> v(SZ(a) + 1);
	v[0] = 0;
	REP(i, SZ(a))
	{
		v[i + 1] = v[i] + a[i];
	}
	return v;
}

// 繰り返し二乗法 a^n
ll iterativePower(ll a, ll n)
{
	ll res = 1;
	while (n > 0)
	{
		if (n & 1)
			res = (res * a) % MOD;
		a = a * a % MOD;
		n >>= 1;
	}
	return res;
}

// MODの逆元
vector<ll> MODInverse(ll n, ll factN)
{
	vector<ll> res(n + 1);
	res[n] = iterativePower(factN, MOD - 2);
	REPR(i, n - 1)
	{
		res[i] = res[i + 1] * (i + 1) % MOD;
	}
	return res;
}

// 階乗
void factorialFunc(ll n)
{
	factorial.pb(1);
	FOR(i, 1, n + 1)
	{
		factorial.pb(factorial[i - 1] * i % MOD);
	}
	vector<ll> fact;
	fact = MODInverse(n, factorial[n]);

	REP(i, n + 1)
	{
		factorialInverse.pb(fact[i]);
	}
}

// 二項係数nCr
ll comb(ll n, ll r)
{
	if (n < r)
		return 0;
	//ll fact = factorial(n);
	//vector<ll> fact_inv;
	//fact_inv = MODInverse(n, fact);
	return (factorial[n] * factorialInverse[r]) % MOD * factorialInverse[n - r] % MOD;
}

