int main(){
    stack<int> st;
    int n;
    cin >> n;
    int d[n] = {};
    int f[n] = {};
    int vnum[n][2] = {};
    bool vflag[n] = {};
    int tmp2;
    int num;
    vector<vector<int>> vertex;
    vector<int> tmp;
    for(int i=0;i<n;i++){
        cin >> num;
        cin >> num;
        vnum[i][0] = num;
        for(int j=0;j<num;j++){
            cin >> tmp2;
            tmp.push_back(tmp2);
        }
        vertex.push_back(tmp);
        tmp.clear();
    }
    int cnt = 1;
    bool check;
    int s;
    st.push(0);
    do{
        s = st.top();

        if(f[s]==0){
            if(((vnum[s][0]==0) && d[s]==0) || (s==vertex[s][vnum[s][1]]-1)){
                vflag[s] = true;
                d[s] = cnt++;
                f[s] = cnt++;
                st.pop();
            }else if((vflag[vertex[s][vnum[s][1]]-1]) && (d[s]==0)){
                if(vnum[s][0]-vnum[s][1]==1){
                    vflag[s] = true;
                    d[s] = cnt++;
                    f[s] = cnt++;
                    st.pop();
                }else{
                    vnum[s][1]++;
                }
            }else if(vflag[vertex[s][vnum[s][1]]-1]){
                vflag[s] = true;
                f[s] = cnt++;
                st.pop();
            }else if(vflag[s]){
                vflag[s] = true;
                f[s] = cnt++;
                st.pop();
            }else{
                if(d[s]==0){
                    d[s] = cnt++;
                }
                st.push(vertex[s][vnum[s][1]++] - 1);
                if(vnum[s][0]==vnum[s][1]){
                    vflag[s] = true;
                }
                if(vflag[vertex[s][vnum[s][1]]-1]){
                    f[s] = cnt++;
                    st.pop();
                }
            }
        }else{
            st.pop();
        }
        check = !st.empty();
        if(!check){
            for(int i=0;i<n;i++){
                if(vflag[i]==false){
                    check = true;
                    st.push(i);
                    break;
                }
            }
        }
    }while(check);

    for(int i=0;i<n;i++){
        cout << i+1 << " " << d[i] << " " << f[i] << endl;
    }
}

