void dfs_visit(int r)
{
  for (int i = 0; i < n; i++)
  {
    nt[i] = 0;
  }

  stack<int> S;
  S.push(r);
  color[r] = GRAY;
  d[r] = ++tt;

  while (!S.empty())
  {
    int u = S.top();
    int v = next(u);
    if (v != -1)
    {
      if (color[v] == WHITE)
      {
        color[v] = GRAY;
        d[v] = ++tt;
        S.push(v);
      }
    }
    else
    {
      S.pop();
      color[u] = BLACK;
      f[u] = ++tt;
    }
  }
}

