    memo[now]=1;
    cnt++;
    ans[now][0]= cnt;
    // out(now,cnt);
    each(next, g[now]){
        if(pre==next) continue;
        if(memo[next]) continue;
        dfs(next,now);
    }

    cnt++;
    ans[now][1]= cnt;
    return;
}

