#include <iostream>
using namespace std;
#include <stack>
#include <queue>

struct Node{
    bool comp;
    int starttime, endtime;
};

int Time = 1;

void setTime(queue<int> q[], stack<int> t, Node l[]){
    if(Time == 1){
        t.push(1);
        l[0].starttime = Time++;
        setTime(q, t, l);
    }

    if(t.size() == 0){
        return;
    }

    int index = t.top() -1;

    // if(l[index].comp){
    //     cout << index << endl;
    //     t.pop();
    //     setTime(q, t, l);
    // }

    if(q[index].size() == 0){
        t.pop();
        l[index].endtime = Time++;
        l[index].comp = true;
        setTime(q, t, l);
    } else {
        int val = q[index].front();
        q[index].pop();

        if(l[val - 1].comp) setTime(q, t, l);
        else{
            t.push(val);
            l[val - 1].starttime = Time++;
            setTime(q, t, l);
        }
    }

}

