    queue<int> q[n];
    stack<int > timetable;
    Node timelist[n];
    for(int i=0; i<n; i++){
        cin >> v >> k;
        v--;
        timelist[i].comp = false;
        for(int j=0; j<k; j++){
            cin >> l;
            q[v].push(l);
        }
    }

    setTime(q, timetable, timelist);

    for(int i=0; i<n; i++){
        cout << i+1 << " " << timelist[i].starttime << " " << timelist[i].endtime << endl;
    }

    return 0;

}

