}

#include<bits/stdc++.h>
using namespace std;

#define MAX 100
#define FND -1
#define CMP -2

int n, G_list[MAX+1];
int G[MAX+1][MAX+1];
int d[MAX+1][3];

void make_graph(void){
  scanf("%d", &n);

  for(int i=0; i<n; i++){
    int cnt, num, m;

    scanf("%d %d", &num, &cnt);
    G_list[i]=num;

    for(int j=0; j<cnt; j++){
      scanf("%d", &m);
      G[num][m]=1;
    }
  }
}

void check_depth(int data){
  stack<int> S;
  static int tm=0;

  S.push(data);
  d[data][0]=++tm;
  d[data][2]=FND;

  while(!S.empty()){
    int top=S.top();
    int next=-5;

    for(int i=0; i<n; i++){
      if(G[top][G_list[i]] == 1 && d[G_list[i]][2] == 0){
	next=G_list[i];
	S.push(next);
	d[next][2]=FND;
	d[next][0]=++tm;
	break;
      }
    }

    if(next == -5){
      d[S.top()][2]=CMP;
      d[S.top()][1]=++tm;
      S.pop();
    }

  }
}

void set_depth(void){

  for(int i=0; i<n; i++){
    if(d[G_list[i]][2] == 0) check_depth(G_list[i]);
  }
}

void print(void){

  for(int i=0; i<n; i++){
    printf("%d %d %d\n", G_list[i], d[G_list[i]][0], d[G_list[i]][1]);
  }
}

int main(void){

  make_graph();
  set_depth();
  print();

  return 0;
}

