using namespace std;

map<int, vector<int>> V;
map<int, int> pre;
map<int, int> post;
int t = 1;

int _DFS(int v, vector<bool> &visited) {
  pre[v] = t;
  ++t;
  for (int out_nbr_id : V[v]) {
    if (!visited[out_nbr_id]) {
      visited[out_nbr_id] = true;
      _DFS(out_nbr_id, visited);
    }
  }
  post[v] = t;
  ++t;
}

int main() {
  int n;
  cin >> n;

  vector<bool> visited(n, false);

  cin.ignore();

  for (string line; getline(cin, line);) {
    istringstream is{line};
    int id, n_nbrs, nbr;
    is >> id >> n_nbrs;
    vector<int> out_nbrs;
    while (is >> nbr)
      out_nbrs.push_back(nbr);
    V[id] = out_nbrs;
  }

  for (auto vadj : V) {
    if (!visited[vadj.first]) {
      visited[vadj.first] = true;
      _DFS(vadj.first, visited);
    }
  }

  for (auto vadj : V) {
    int id = vadj.first;
    cout << id << " " << pre[id] << " " << post[id] << endl;
  }
}

