int times=1;

void dfs(int now,vector<int> &fvisit,vector<int> &fin, vector<vector<int>> &vs)
{
  if(fvisit[now]==-1)
  {
    fvisit[now]=times;
    times++;
  }
  else return;
  int i;
  rep(i,vs[now].size())
  {
    if(fvisit[vs[now][i]]==-1)
    {
      dfs(vs[now][i],fvisit,fin,vs);
    }
  }
  fin[now]=times;
  times++;
}

