#include <iostream>
#include <stack>
#define N 100
#define WHITE 0
#define GRAY  1
#define BLACK 2
#define NIL -1

int M[N][N];
int color[N], nt[N], d[N], f[N];
int tt;
int n;

// uの隣接点を番号順に取得する
// nt[N]には番号順での探索開始位置を保存する
// 隣接点がなければ-1を返す
int next(int u)
{
	for (int v = nt[u]; v < n; v++)
	{
		nt[u]++;
		if (M[u][v]) return v;
	}
	return NIL;
}

// rを開始地点として深さ優先探索を行う
void dfs_visit(int r)
{
	std::stack<int> S;
	S.push(r);
	color[r] = GRAY;
	d[r] = tt++;

	while (!S.empty())
	{
		int u = S.top();
		int v = next(u);
		if (v != NIL)
		{
			if (color[v] == WHITE)
			{
				S.push(v);
				color[v] = GRAY;
				d[v] = tt++;
			}
		}
		else
		{
			S.pop();
			color[u] = BLACK;
			f[u] = tt++;
		}
	}
}

//初期化処理、探索、結果出力を行う
void dfs()
{
	for (int i = 0; i < n; i++)
	{
		color[i] = WHITE;
		nt[i] = 0;
	}
	tt = 1;

	for (int i = 0; i < n; i++)
	{
		if (color[i] == WHITE) dfs_visit(i);
	}

	for (int i = 0; i < n; i++)
	{
		std::cout << i + 1 << " " << d[i] << " " << f[i] << std::endl;
	}
}

int main()
{
	std::cin >> n;
	for (int i = 0; i < n; i++)
	{
		for (int j = 0; j < n; j++)
		{
			M[i][j] = 0;
		}
	}

	int u, k, v;
	for (int i = 0; i < n; i++)
	{
		std::cin >> u >> k;
		u--;
		for (int j = 0; j < k; j++)
		{
			std::cin >> v;
			v--;
			M[u][v] = 1;
		}
	}

	dfs();
}

