class Graph{
public:
	std::vector< std::vector<int> > A;
	std::vector<int> d, f;
	int n;

	Graph(int n);

	void DepthFirstSearch();
	int DepthFirstSearch_Rec(int id, int time);

};

Graph::Graph(int n){
	A.resize(n);
	d.resize(n);
	f.resize(n);
	for (int i = 0; i < n; i++){
		A[i].resize(n);
		for (int j = 0; j < n; j++){
			A[i][j] = 0;
		}
		d[i] = 0;
		f[i] = 0;
	}
	this->n = n;
}

void Graph::DepthFirstSearch(){
	int time = 0;
	for (int i = 0; i < n; i++){
		if (d[i] == 0) time = DepthFirstSearch_Rec(i, time + 1);
	}
	return;
}

int Graph::DepthFirstSearch_Rec(int id, int time){
	d[id] = time;
	for (int i = 0; i < n; i++){
		if (A[id][i] == 1 && d[i] == 0){
			time = DepthFirstSearch_Rec(i, time + 1);
		}
	}
	time++;
	f[id] = time;
	return time;
}

