int main(void){
    int n;
    cin >> n;
    vector<queue<int> > a(n+1); 
    //入力
    for(int i = 1; i <= n; i++){
        int id, num;
        cin >> id >> num;
        for(int j = 0; j < num; j++){
            int temp;
            cin >> temp;
            a[i].push(temp);
        }
    }
    vector<int> d(n+1);
    vector<int> f(n+1);
    stack<int> place;
    place.push(1);
    int time = 0;
    while(place.size()){
        int now = place.top();
        //初めて来たらタイムスタンプ
        if(!f[now]){
            f[now] = ++time;
        }
        //次に行く場所を決める
        while(a[now].size()){
            //まずnowの隣接リストから探す
            if(!f[a[now].front()]){
                place.push(a[now].front());
                a[now].pop();
                break;
            }else{
                a[now].pop();
            }
        }
        //nowの隣接リストに見探索の頂点が無ければ一個前に戻る。
        //同時に終了のタイムスタンプを押す
        if(now == place.top()){
            place.pop();
            d[now] = ++time;
        }
        //たどり切ったときに、探索出来ない場所に見探索の頂点があれば次の目的地にする
        if(place.size() == 0){
            for(int i = 1; i <= n; i++){
                if(f[i] == 0){
                    place.push(i);
                    break;
                }
            }
        }
    }
    for(int i = 1; i <= n; i++){
        cout << i << " " << f[i] << " " << d[i] << endl;
    }
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

const int LEN = 100;
const int UNVISITED = 0;
const int FOUND = 1;
const int DONE = 2;

// 再帰関数による深さ優先探索
void dfs_visit(int n, int u, vector<vector<int> >& M, vector<int>& status, vector<int>& d, vector<int>& f, int& tt){
    // 頂点uの訪問状態を「発見」にし,その時刻を記録
    status[u] = FOUND;
    d[u] = ++tt; // ttをインクリメントしてからd[u]に代入

    int v;
    for(v = 0; v < n; v++){
        if(M[u][v] == 0) continue; // 0:隣接していない
        if(status[v] == UNVISITED){
            dfs_visit(n, v, M, status, d, f, tt);
        }
    }

    // 頂点uの訪問状態を「完了」にし,その時刻を記録
    status[u] = DONE;
    f[u] = ++tt; // ttをインクリメントしてからf[u]に代入
}

void dfs(int n, vector<vector<int> >& M){
    vector<int> status(LEN); // status:頂点の訪問状態
    vector<int> d(LEN); // d:頂点の発見時刻
    vector<int> f(LEN); // d:頂点の完了時刻
    int tt; // tt:時刻

    // 初期化 (頂点uの訪問状態を「未訪問」に,また時刻を0に)
    int u;
    for(u = 0; u < n; u++){
        status[u] = UNVISITED;
    }
    tt = 0;

    // 未訪問のuを始点として深さ優先探索
    for(u = 0; u < n; u++){
        if(status[u] == UNVISITED){
            dfs_visit(n, u, M, status, d, f, tt);
        }
    }

    // 結果を出力
    for(u = 0; u < n; u++){
        cout << u + 1 << " " << d[u] << " " << f[u] << endl;
    }
}

int main(){
    int n; // n:頂点数
    vector<vector<int> > M(LEN, vector<int> (LEN)); //  M:頂点同士の隣接を表す行列
    int u, v, k, i, j; // 入力受け取り用

    // 頂点数を受け取り,隣接行列を初期化
    cin >> n;
    int m;
    for(m = 0; m < n; m++){
        for (j = 0; j < n; j++){
            M[m][j] = 0;
        }
    }

    // 頂点番号,出次数,隣接する頂点番号を受け取り,隣接行列に反映
    for(i = 0; i < n; i++){
        cin >> u >> k;
        u--;
        for(j = 0; j < k; j++){
            cin >> v;
            v--;
            M[u][v] = 1;
        }
    }

    dfs(n, M);

    return 0;
}

