const int N = 101;
std::queue<int> Q[N];
void dfs(int root, int *tt, int d[], int f[]);
int main() {
    int n; scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int k;
        scanf("%d%d", &i, &k); //&i, so i--;
        for (int j = 0; j < k; j++) {
            int v; scanf("%d", &v);
            Q[i].push(v);//remember children
            //i starts from 1!. look scanf above
        }
        i--;
    }
    int d[N] = {0}, f[N] = {0}, tt = 0;
    for (int i = 1; i <= n; i++) if(!d[i]) dfs(i, &tt, d, f);//if cannot reach from 0
    for (int i = 1; i <= n; i++) printf("%d %d %d\n", i, d[i], f[i]);
    return 0;
}
void dfs(int root, int *tt, int d[], int f[]) {//from root search
    std::stack<int> S;
    S.push(root);
    d[root] = ++*tt;
    while (!S.empty() ) {
        int u = S.top();
        if (!Q[u].empty() ) {
            int v = Q[u].front();
            Q[u].pop();
            if (d[v] == 0) {
                d[v] = ++*tt;
                S.push(v);
            }
        } else {
            S.pop();
            f[u] = ++*tt;
        }

    }
}

