int DFS(vector<vector<int> >& G,
        vector<pair<int, int> >& rec, int i, int t) {
    rec[i].first = t;
    for (int j = 1; j <= G[i].size(); j++) {
        if (G[i][j] && rec[j].first == -1) {
            t = DFS(G, rec, j, t + 1);
        }
    }
    rec[i].second = t + 1;
    return rec[i].second;
}

