void dfs(int node, std::vector<std::vector<int>>& v, int& time, std::vector<std::vector<int>>& log) {
    log[node].push_back(++time);
    for (int i=0; i<v[node].size(); i++) {
        if (node != v[node][i] and log[v[node][i]].size() == 0) {
            dfs(v[node][i], v, time, log);
        }
    }
    log[node].push_back(++time);
} 

