template <typename T>
using V = vector<T>;
template <typename T, typename U>
using P = pair<T, U>;

int main() {
  int n;
  V<V<int>> graph;
  cin >> n;
  graph.resize(n);

  rep(i, n) {
    int u, k;
    cin >> u >> k;
    graph[u - 1].resize(k);

    rep(j, k) {
      cin >> graph[u - 1][j];
      graph[u - 1][j]--;
    }
  }

  stack<int> way;

  V<bool> visited(n, false);
  V<int> arrived_t(n, 0);
  V<int> finished_t(n, 0);

  int t = 0;
  rep(i, n) {
    if(visited[i]) {
      continue;
    }
    visited[i] = true;
    arrived_t[i] = ++t;
