#define NIL 0

struct Node{
    int d=0, f=0, ch=0;
    int child[100]={0};
};

Node nodes[101];

int search(int num, int time){
    if(nodes[num].d!=NIL){
        return time;
    }
    nodes[num].d = time;
    ++time;
    for(int i=0;i<nodes[num].ch;++i){
        time = search(nodes[num].child[i], time);
    }
    nodes[num].f = time;
    ++time;
    return time;
}

