using namespace std;
#define N 100
#define WHITE 0
#define GRAY 1
#define BLACK 2

int n,M[N][N];
int color[N],d[N],f[N],tt;
int nt[N];

int next(int u)
{
    for(int v=nt[u];v<n;v++)
    {
        nt[u]=v+1;
        if(M[u][v])return v;
    }
    return -1;
}

void dfs_visit(int r)
{
    for(int i=0;i<n;i++)
    {
        nt[i]=0;
    }

    stack<int> s;
    s.push(r);
    color[r]=GRAY;
    d[r]=++tt;

    while(!s.empty())
    {
        int u=s.top();
        //cout << "s.top=" << u << endl;
        int v=next(u);
        //cout << "u.next=" << v << endl;
        if(v!=-1)
        {
            if(color[v]==WHITE)
            {
                color[v]=GRAY;
                d[v]=++tt;
                s.push(v);
            }
        }
        else
        {
            s.pop();
            color[u]=BLACK;
            f[u]=++tt;
        }
    }
}

void dfs()
{
    for(int i=0;i<n;i++)
    {
        color[i]=WHITE;
        nt[i]=0;
    }


    tt=0;

    for(int u=0;u<n;u++)
    {
        if(color[u]==WHITE)
        {
            //cout << "visit " << u << endl;
            dfs_visit(u);
        }
    }

    for(int i=0;i<n;i++)
    {
        cout << i+1 << " " << d[i] << " " << f[i] << endl;
    }
}

