using namespace std;

struct node{
	int id;
	queue<node*> adjacentNodeList;
};

int d[100] = {0};
int f[100] = {0};

int bfs(node* nd,int time){
	//cout<<nd->id<<" is called"<<endl;
	if(f[nd->id] != 0){
		return time;
	}
	if(d[nd->id] != 0){
		return time;
	}
	time = time + 1;
	if(d[nd->id] ==0){
		d[nd->id] = time;
	}
	while( !nd->adjacentNodeList.empty() ){
		if(nd->id == nd->adjacentNodeList.front()->id){
			nd->adjacentNodeList.pop();
		}else{
			time = bfs(nd->adjacentNodeList.front(),time);
			nd->adjacentNodeList.pop();
		}
	}
	time++;
	if( f[nd->id] == 0) f[nd->id] = time;
	return time;
}

