int dfs(const int cur, const int par, int time, const vector<vi> &g, vi &d, vi &f) {
  if (d[cur] != 0)
    return time;
  d[cur] = time;
  time++;
  for (const auto u : g[cur]) {
    if (u == par)
      continue;
    time = dfs(u, cur, time, g, d, f);
  }
  f[cur] = time;
  time++;
  return time;
}

