int dfs(int u, int count) {
	if (flag[u] == 1) return -1;
	flag[u] = 1;

	in[u] = count;
	for (int i = 0; i < N; ++i) {
		if (flag[i] == 0 && G[u][i] == 1) {
			count = dfs(i, count + 1);
		}
	}
	out[u] = count + 1;
	return count + 1;
}

