		}
	}

	for (int i = 0; i < n; ++i)
		visited[i] = false;

	for (int i = 0; i < n; ++i) {
		int u, d;
		cin >> u >> d;
		for (int j = 0; j < d; ++j)	{
			int v; cin >> v;
			m[u - 1][v - 1] = 1;
		}
	}

	dfs();

	return 0;
}

#include <cstdint>
#include <vector>

using namespace std;

#define GRAPH_SIZE 101
#define START_INDEX 1

enum color_t {
  WHITE,
  GRAY,
  BLACK,
};

static uint32_t t = 0;
static color_t state[GRAPH_SIZE];
static vector<uint32_t> graph[GRAPH_SIZE];

void depth_first_search(void (*visited)(uint32_t), void (*invested)(uint32_t))
{
  for (uint32_t i = START_INDEX; i < GRAPH_SIZE; i++) {
    state[i] = WHITE;
  }

  static vector<pair<uint32_t, vector<uint32_t>>> stack;

  stack.push_back(make_pair(START_INDEX, graph[START_INDEX]));
  state[START_INDEX] = GRAY;
  t++;
  visited(START_INDEX);

  while (!stack.empty()) {
    pair<uint32_t, vector<uint32_t>> top = stack.back();
    bool found = false;
    for (uint32_t i = 0; i < top.second.size(); i++) {
      uint32_t next = top.second[i];
      if (state[next] == WHITE) {
        found = true;
        state[next] = GRAY;
        t++;
        visited(next);
        stack.push_back(make_pair(next, graph[next]));
        break;
      }
    }

    if (!found) {
      stack.pop_back();
      t++;
      state[top.first] = BLACK;
      invested(top.first);
    }
  }
}

