        for (int k = 1; k <= G[v][0]; ++k) {
            cin >> G[i][k];
        }
    }

    int time = 0;
    for (int n = 1; n <= N; ++n) {
        if (d[n] == 0) {
            stack<int> S;

            S.push(n);

            d[n] = ++time;
            while (!S.empty()) {
                int u = S.top();

                bool found = false;
                // 未探索の奴をスタックに積む
                for (int i = 0; i < G[u][0]; ++i) {
                    if (d[G[u][i + 1]] != 0) continue;
