                    found = true;
                    d[G[u][i + 1]] = ++time;
                    break;
                }

                if (!found) {
                    f[u] = ++time;
                    S.pop();
                } 
            }
        }
    }


    for (int i = 1; i <= N; ++i) {
        cout << i << ' ' << d[i]  << ' ' << f[i] << endl;
