using namespace std;

const int MAX = 100;

class DFS
{
    vector< vector<int> > adj;
    int num, d[MAX], f[MAX], parent[MAX], status[MAX], tt;

public:
    DFS()
    {
        cin >> num;
        for (int i = 0; i < num; i++)
        {
            d[i] = status[i] = 0;
            parent[i] = -1;
        }

        load(num);
        tt = 0;
    }

    void load(int n)
    {
        int r, c, n_c;
        adj.assign(n, vector<int>());
        for (int i = 0; i < n; i++)
        {
            cin >> r >> n_c;
            adj[r - 1].assign(n_c, int());
            for (int j = n_c - 1; j >= 0; j--)
            {
                cin >> c;
                adj[r - 1].at(j) = c-1;
            }
        }
    }

    int next(int node)
    {
        if (!adj[node].empty())
        {
            int v = adj[node].back();
            adj[node].pop_back();
            return v;
        }
        return -1;
    }

    void run(int node)
    {
        int next_node;
        while (node != -1)
        {
            if (status[node] == 0)
            {
                status[node] = 1;
                d[node] = ++tt;
            }
            next_node = next(node);
            if (next_node == -1)
            {
                status[node] = 2;
                f[node] = ++tt;
                node = parent[node];
                continue;
            }
            if (status[next_node] == 0)
            {
                parent[next_node] = node;
                node = next_node;
            }
        }
    }

    void dfs(){
        for(int node=0;node<num;node++){
            if(status[node] == 0) run(node);
        }
    }

    int dd(int n)
    {
        return d[n];
    }

    int ff(int n)
    {
        return f[n];
    }

    int number()
    {
        return num;
    }
};

int main()
{
    DFS dfs;

    dfs.dfs();
    for (int i = 0; i < dfs.number(); i++)
    {
        cout << i + 1 << " " << dfs.dd(i) << " " << dfs.ff(i) << endl;
    }
}

