//次の点へ移動とかする関数
int next_point(int point, int (&a)[100][100], int (&num)[100], int (&back)[100], int time[100][2]){
	int next = a[point][num[point]]-1;

	//行先が探索終了しているしている場合、pointを返す
	if(a[next][1] == 0 && time[next][1] != 0){
		a[point][1] -= 1;
		return point;
	}

	back[next] = point;
	a[point][1] -= 1;
	return next;
}

int main(void){
	int a[100][100];
	int back[100];				//back[]:現在いる点の始点
	int time[100][2];	//time[i][0]:発見時刻,time[i][1]:探索終了時間
	int bre=0, m, time_now=1, point=0;	//point:現在探索している点
	int num[100];

	cin >> m;

	for(int i=0; i<m;i++){
		cin >> a[i][0];
		cin >> a[i][1];

		for(int j=2; j<a[i][1]+2; j++){
			cin >> a[i][j];
		}
	}

	//ここまで入力
	//ここから↓

	//numを2に初期化,time[i][0]をINT_MAXに初期化
	for(int i=0; i<100; i++){
		num[i] = 2;
		time[i][0] = INT_MAX;
	}

	time[point][0] = time_now++;

	int k=0;

	for(int i=0; i<100; i++){
		if(time[point][1] == 0){
			while(time[i][1] == 0){

				//矢印が出ていない場合
				if(a[point][1] == 0){
					time[point][1] = time_now++;	//探索終了時刻を決定
					point = back[point];	//始点へ移動
				}

				//矢印が出ている場合
				if(a[point][1] != 0){
					point = next_point(point, a, num, back, time);
					num[back[point]] += 1;
					if(time[point][0] > time_now) time[point][0] = time_now++;	//探索開始時刻を決定
				}
			}

		}
	}

	//出力
	for(int i=0; i<m; i++){
		cout << i+1 << " " << time[i][0] << " " << time[i][1] << "\n";
	}

	return 0;
}

