	vector<pair<int, int>> timeStamp(n,make_pair(0,0));//pair<初回訪問時刻, 完了時刻>
	timeStamp.at(0).first = 1;
	while (!visitedNodeIDs.empty()) {
		++time;
		const int nodeID = visitedNodeIDs.top();
		vector<int>& neighbourNodeList = graphMatrix.at(nodeID - 1);
		vector<int>::iterator result = find(neighbourNodeList.begin(), neighbourNodeList.end(), 1);
		if (result != neighbourNodeList.end()) {
			const int nextVisitID = distance(neighbourNodeList.begin(), result) + 1;
			timeStamp.at(nextVisitID - 1).first = time + 1;
			*result = 0;
			visitedNodeIDs.push(nextVisitID);
		}
		else {
			//隣接リストに検索対象なし
			timeStamp.at(nodeID - 1).second = time+1;
			visitedNodeIDs.pop();
		}
	}
	for (int i = 0; i != n; ++i) {
		cout << i + 1 << " " << timeStamp.at(i).first << " " << timeStamp.at(i).second << endl;
	}
}

