ll now; //時刻

void DFS(ll node) {
	//nodeを起点とした探索
	for (auto next : g[node]) {
		if (d[next] > 0) {
			// 発見済み
			continue;
		}
		else {
			// 新発見
			now++;
			d[next] = now;
			DFS(next);
		}
	}

	//nodeを起点とした探索が完了
	now++;
	f[node] = now;
}

