		visit.resize(n);
		stamp.resize(n);
	}

	void addEdge(int from, int to, T cost = 0) {
		int v = max(from, to);
		if (v >= V)
			resize(v + 1);
		G[from].push_back(Edge(to, cost));
	}

	int t = 1;
	void dfs(int s) {
		if (stamp[s].first == 0)
			stamp[s].first = t++;
		else
			return;

		for (int i = 0; i < G[s].size(); ++i) {
			dfs(G[s][i].to);
		}
		stamp[s].second = t++;
	}

