static const ll N_MAX = 110;

// グローバル変数（入力）
ll n, t, A[N_MAX][N_MAX], d[N_MAX], f[N_MAX], state[N_MAX];

// 入力
void input() { cin >> n; }

// 深さ優先探索
void dfs(ll u) {
  d[u] = ++t;
  state[u] = 1; // 発見
  rep(i, n) {
    ll v = i + 1;
    if (A[u][v] == 1 && state[v] == 0) { // 辺が存在かつ未発見なら
      dfs(v);
    }
  }
  f[u] = ++t;
  state[u] = 2; // 完了
}

void solve() {
  // 隣接リストを隣接行列に変換して二次元配列Aに格納
  rep(i, n) {
    ll v, k;
    cin >> v >> k;
    rep(j, k) {
      ll v2;
      cin >> v2;
      A[v][v2] = 1;
    }
  }

  t = 0;
  rep(i,n){
    if (state[i+1]==0){
      dfs(i+1);
    }
  }

  // 出力
  rep(i, n) { cout << i + 1 << " " << d[i + 1] << " " << f[i + 1] << endl; }
}

