    void dfsVisit(int u) {
        //cout << "visited: " << u << endl;
        color[u] = GREY;
        dt[u] = ct++; //first assign ct to dt[u], then ++
        for (int v : g[u]) {
            if (color[v] == WHITE) {
                dfsVisit(v);
            }
        }
        color[u] = BLACK;
        ft[u] = ct++;
    }

    void printGraph() {
        for (int i = 0; i < n; i++) {
            cout << i << ": ";
            for (int j : g[i]) {
                cout << j << " ";
            }
            cout << endl;
        }
    }

    void printResults() {
        for (int i = 0; i < n; i++) {
            cout << i + 1 << " " << dt[i] << " " << ft[i] << endl;
        }
    }
};

