void search(int i,int *table, int n, int *d, int *f, int *cnt){

	++(*cnt);
	d[i] = *cnt;

	for(int j=0;j<n;++j){
		if(table[i*n+j]){
			for(int k=0;k<n;++k){
				table[k*n+j] = 0;
			}
			search(j,table,n,d,f,cnt);
		}
	}

	++(*cnt);
	f[i] = *cnt;
}

