class dfs {
public:
    vector<set<int>> g;
    vector<int> d, f;

    int rec(int u, int cnt){
        d[u] = cnt;

        for(auto& to : g[u]){
            if(d[to]) continue;
            cnt = rec(to, cnt+1);
        }

        f[u] = ++cnt;
        return cnt;
    }

	void solve(std::istream& in, std::ostream& out) {
	    int n;
	    in >> n;
	    int u, k;
	    g.assign(n, set<int>());
	    for(int i=0; i<n; i++){
            in >> u >> k;
            int v;
            --u;
            for(int j=0; j<k; j++){
                in >> v;
                --v;
                g[u].insert(v);
            }
	    }

        d.assign(n, 0);
        f.assign(n, 0);

        bool flg = false;
        int start = 0;
        int cnt = 0;
        while(!flg) {
            cnt = rec(start, cnt+1);
            start = -1;
            for(int i=0; i<n; i++){
                if(!d[i]){
                    start = i;
                    break;
                }
            }
            if(start == -1) flg = true;
        }

        for(int i=0; i<n; i++){
            out << i+1 sp d[i] sp f[i] << enl;
        }
	}
};


