void stamp(int id, int t) {
	if (t > 2 * n)
		return;

	if (d[id - 1] == 0) {
		d[id - 1] = t;
		int i = 0;
		while (v[id - 1][i] == 0)
			i++;
		if (i < n && d[i] == 0)
			stamp(i + 1, t + 1);
		else
			stamp(id, t + 1);
	}
	else if (f[id - 1] == 0) {
		int i;
		for(i = 0; i < n; i++)
			if (v[id - 1][i] == 1 && d[i] == 0) {
				stamp(i + 1, t);
				break;
			}
		if (i > n - 1) {
			f[id - 1] = t;
			int j1 = 0, ct = 0;
			for (int j = 0; j < n; j++){
				if (v[j][id - 1] == 1 && f[j] == 0 && d[j] != 0) {
					ct++;
					if(ct == 1 || d[j] == d[id - 1] - 1)
						j1 = j;
				}
			}
			if(j1 < n)
				stamp(j1 + 1, t + 1);

			int k = 0;
			while (d[k] != 0)
				k++;
			if (k < n)
				stamp(k + 1, t + 1);
		}
	}	
	return;
}

