vector<bool> seen;
vec first;
vec last;
void dfs(const Graph &G, ll v, ll &time)
{
  if (!(seen[v]))
  {
    seen[v] = true;
    first[v] = time++;
    for (auto next_v : G[v])
    {
      if (seen[next_v])
        continue;
      dfs(G, next_v, time);
    }
    last[v] = time++;
  }
}
