      Gput(u - 1, x - 1);
    }
  }
  vec id(n);
  loop(i, n) id[i] = i + 1;
  seen.assign(n, false); // 全頂点を「未訪問」に初期化
  first.resize(n);
  last.resize(n);
  ll time = 1;
  loop(i, n) dfs(G, i, time);
  loop(i, n)
  {
    cout << id[i] << " " << first[i] << " " << last[i] << endl;
  }
  return 0;
}

