typedef vector<ll> vec;
typedef vector<vec> mat;

mat mul(mat &A, mat &B)
{
  mat C(A.size(), vec((int)B[0].size()));
  for (int i = 0; i < A.size(); ++i)
  {
    for (int k = 0; k < B.size(); ++k)
    {
      for (int j = 0; j < B[0].size(); ++j)
      {
        C[i][j] = (C[i][j] + A[i][k] % MOD * B[k][j] % MOD) % MOD;
      }
    }
  }
  return C;
}
mat matPow(mat A, ll n)
{
  mat B(A.size(), vec((int)A.size()));

  for (int i = 0; i < A.size(); ++i)
  {
    B[i][i] = 1;
  }

  while (n > 0)
  {
    if (n & 1)
      B = mul(B, A);
    A = mul(A, A);
    n >>= 1;
  }
  return B;
}

template <class TYPE>
struct Fenwick
{
  int N;
  vector<ll> bit;

  Fenwick() : N(0) {}
  Fenwick(int n) : N(n), bit(N + 1, 0) {}

  void add(int i, ll x)
  {
    ++i; //0-indexedを避けるために加算
    while (i <= N)
    {
      bit[i] += x;
      i += (i & -i);
    }
  }

  ll sum(int i)
  {
    ll res = 0;
    while (i > 0)
    {
      res += bit[i];
      i -= (i & -i);
    }
    return res;
  }

  ll range(int i, int j)
  {
    return sum(j) - sum(i);
  }

  ll get(int i)
  {
    return sum(i) - sum(i - 1);
  }
};
