	for (int vertex_i = 0; vertex_i < n; ++vertex_i){
		if(has_not_been_discovered_yet[vertex_i])
			Dfs(vertex_i, n);
	}
	for (int id = 0; id < n; ++id)
		printf("%d %d %d\n", id+1, discoveredtime[id], finishedtime[id]);
	return 0;
}

