	Graph(int n) : adjl(n){}
	void PushAdjl(int pl, int val) { adjl[pl].push_back(val); }
};

class DFGraph : public Graph {
private:
	int t;
	vector<int> d, f;
public:
	DFGraph(int n) : Graph(n), d(n), f(n) {}
	void DepthFirstSearch(int);
	void DFSSub(int);
	void Showdf();
};

void DFGraph::DepthFirstSearch(int begin = 0) {
	t = 1;
	DFSSub(begin);
	for (int i = 0; i < d.size(); i++)
		if (d[i] == 0)
			DFSSub(i);
}

void DFGraph::DFSSub(int v) {
	d[v] = t;
	t++;
	for (auto&& i : adjl[v])
		if (d[i] == 0)
			DFSSub(i);
	f[v] = t;
	t++;
}

void DFGraph::Showdf() {
	for (int i = 0; i < d.size(); i++)
		cout << i + 1 << " " << d[i] << " " << f[i] << endl;
}

