int N;
const int maxn = 105;
const int WHITE = 0;
const int BLACK = 2;
int G[maxn][maxn];
vector<int> color;
vector<int> startTime;
vector<int> endTime;
vector<int> nt;

int getNext(int u){
    int res = -1;
    for(int i = nt[u];i<N;i++){
        if(G[u][i] && color[i]==WHITE){
            res = i;
            nt[u] = i;
            break;
        }
    }
    return res;
}

void DFS(int u,int &time){
    if(color[u]!=WHITE) return;
    stack<int> nodeStack;
    nodeStack.push(u);
    startTime[u] = time++;
    while(!nodeStack.empty()){
        int u = nodeStack.top();
        //if(color[u]!=WHITE) continue;
        color[u] = BLACK;

        int v = getNext(u);
        if(v!=-1){
            startTime[v] = time++;
            nodeStack.push(v);
            continue;
        }
        else{
            endTime[u] = time++;
            nodeStack.pop();
        }
    }
}

int main(){
    //freopen("data.txt","r",stdin);
    memset(G,0,sizeof(G));
    cin >> N;
    color.resize(N,WHITE);
    startTime.resize(N,0);
    endTime.resize(N,0);
    nt.resize(N,0);
    int u,k;
    for(int i = 0;i<N;i++){
        scanf("%d %d",&u,&k);
        u--;
        for(int j = 0;j<k;j++){
            int v;
            scanf("%d",&v);
            v--;
            G[u][v] = 1;
        }
    }
    int time = 1;
    for(int i = 0;i<N;i++) if(color[i]==WHITE) DFS(i,time);
    for(int u = 0;u<N;u++){
        printf("%d %d %d\n",u+1,startTime[u],endTime[u]);
    }
    return 0;
}

