    stack<int> s;
    int count = 0;
    bool check;
    rep(p, 1, G.size())
    {
        if (d[p] == 0)
        {
            do
            {
                // cout << p << endl;
                check = true;
                if (d[p] == 0)
                {
                    s.push(p);
                    d[p] = ++count;
                }
                rep(i, 0, G[p].size())
                {
                    if (d[G[p][i]] == 0)
                    {
                        check = false;
                        p = G[p][i];
                        break;
                    }
                }
                if (check)
                {
                    c[p] = ++count;
                    s.pop();
                    if (s.size())
                        p = s.top();
