            cin >> v;
            a[u].push_back(v);
        }
    }

    int time = 0;
    map<int, node> nodes;
    for (int i=0; i<n; i++) {
        node nd; 
        nodes[i] = nd;
    }
    for (int i=1; i<=n; i++) {
        if ( nodes[i].start == 0 ) {
            depth_search(a, nodes, time, i);
        }
    }

    for (int i=1; i<=n; i++) {
        cout << i << " " << nodes[i].start << " " << nodes[i].end << endl;
    }
}

