#include <iostream>
#include <vector>

int search(int idx, std::vector<std::vector<int>> vec, std::vector<int>& s, std::vector<int>& d, int t) {
	if (d[idx] != 0 || s[idx] != 0) return t - 1;
	if (s[idx] == 0) s[idx] = t;
	for (int i = 0; i < vec[idx].size(); i++) {
		if (idx == vec[idx][i] - 1) continue;
		t = search(vec[idx][i] - 1, vec, s, d, t + 1);
	}
	d[idx] = ++t;
	return t;
}

int main() {
	int n;
	std::cin >> n;
	std::vector<std::vector<int>> vec(n);
	std::vector<int> s(n, 0);
	std::vector<int> d(n, 0);
	for (int i = 0; i < n; i++) {
		int u, k;
		std::cin >> u >> k;
		for (int j = 0; j < k; j++) {
			int a;
			std::cin >> a;
			vec[u - 1].push_back(a);
		}
	}

	int t = 0;
	for (int i = 0; i < n; i++) {
		t = search(i, vec, s, d, t + 1);
	}
	// output
	for (int i = 0; i < n; i++) {
		std::cout << i + 1 << " " << s[i] << " " << d[i] << std::endl;
	}
}

#include <iostream>
