using namespace std;

int d[101];
int f[101];
int nowTime;

stack<int> st;

void dfsRec(vector<int>* a, int v) {
	if(d[v] > 0) return;
	nowTime++;
	d[v] = nowTime;
	for(int &x:a[v]) {
		dfsRec(a, x);
	}
	nowTime++;
	f[v] = nowTime;
}

void dfsStack(vector<int>* a, int rt) {
	st.push(rt);
	while(!st.empty()) {
		int v = st.top();
		if(d[v] == 0) d[v] = ++nowTime;
		bool found = false;
		for(int &x:a[v]) {
			if(d[x] == 0) {
				st.push(x); found = true; break;
			}
		}
		if(!found) {
			st.pop();
			f[v] = ++nowTime;
		}
	}
}

