int dfs(int start, int t, deque<bool>& visited, vector<int>& t_st, vector<int>& t_ed)
{
    stack<pair<int,int>> stk;

    visited[start] = true;
    stk.emplace(start, 0);
    t_st[start] = t++;

    while(!stk.empty()) {
#ifdef DEBUG
        DBG(stk);
#endif
        auto p = stk.top();
        int  v    = p.first;
        int& to_i = p.second;
        int n = SIZE(G[v]);

        for(; to_i < n; ++to_i) {
            int to = G[v][to_i];
            if(!visited[to]) break;
        }

        if(to_i < n) {
            int to = G[v][to_i];
            visited[to] = true;
            stk.emplace(to, 0);
            t_st[to] = t++;
        }
        else {
            stk.pop();
            t_ed[v] = t++;
        }
    }

    return t;
}

