class Node{
public:
    Node(vector<int> adjacency)
        : adjacency(adjacency) 
    {
        // constructer
    }
    int found = 0;
    int finished = 0;
    vector<int> adjacency;
};

class List{
public:
    List(){
        // 0 番目はダミー
        list.push_back(Node({}));
    }
    void Add(Node&& node){
        this->list.push_back(node);
    }
    void Traverse(){
        for(int i = 1; i < list.size(); i++){
            this->_traverse(i);
        }
    }
    void Print() {
        for (int i = 1; i < list.size(); i++) {
            printf("%d %d %d\n", i, list[i].found, list[i].finished);
        }
    }
private:
    vector<Node> list;
    void _traverse(int index)
    {
        auto current = list[index];
        static int count = 1;

        if (current.found){
            return;
        }

        this->list[index].found = count++;

        for(int i = 0; i < current.adjacency.size(); i++) {
            _traverse(current.adjacency[i]);
        }

        this->list[index].finished = count++;
    }
};

void solve() {
    List list;
    int n;
    scanf("%d", &n);
    for(int i = 0; i < n; i++){
        int value;
        scanf("%d", &value);
        int k;
        scanf("%d", &k);
        vector<int> adjacency(k);
        for(int j = 0; j < k; j++){
            int link;
            scanf("%d", &link);
            adjacency[j] = link;
        }
        list.Add(Node(adjacency));
    }
    list.Traverse();
    list.Print();
}


