using namespace std;

static int count = 0;

class Vtx {
public:
	int id;
	int c = 0;
	int v = 0;
	vector<int> vtxs;
};

int getNext(int id,Vtx vtxs[]){
	vector<int> v=vtxs[id].vtxs;
	for(int i=0;i<v.size();i++){
		if(vtxs[v[i]-1].v == 0){
			return v[i];
		}
	}
	return -1;
}

void dfs_(int id,Vtx vtxs[]){

	stack<int> stack;
	stack.push(vtxs[id].id);
	int i=0;
	while(!stack.empty()){
		id=stack.top();
		id--;
		if(vtxs[id].v==0){
			vtxs[id].v=++count;
		}
		int nId=getNext(id,vtxs);
		if(nId==-1){
			vtxs[id].c=++count;
			stack.pop();
		}else{
			stack.push(nId);
		}
	}
}

void dfs(int n, Vtx vtxs[]){
	for(int i=0;i<n;i++){
		if(vtxs[i].v==0){
			dfs_(i,vtxs);
		}
	}
}

int main(){
	int n;
	cin >> n;
	Vtx vtxs[n];
	for (int i=0;i<n;i++){
		int id, k;
		cin >> id >> k;
		vtxs[i].id = id;
		for(int j=0;j<k;j++){
			int v;
			cin >> v;
			vtxs[i].vtxs.push_back(v);
		}
	}

	dfs(n,vtxs);

	for(int i=0;i<n;i++){
		Vtx v = vtxs[i];
		cout << v.id << " " << v.v;
		cout << " " << v.c << endl;
	}
	return 0;
}

