namespace NyaGadget {}

namespace NyaGadget
{
	/***** DFSライブラリ *****/

	struct GT_NyaaDFS
	{
		/**
		@brief DFS処理関数
		@param r 頂点vの根
		@param v 現在の頂点
		@param g 隣接リストか隣接行列
		@param res 処理結果
		**/
		void Run(long long r, long long v, const std::vector<std::vector<long long>>& g, ll& count, std::vector<pll>& res)
		{
			if (res[v].first != 0) return;
			count++;
			res[v].first = count;
			for (auto&& e : g[v])
			{	// 後戻りしないようにする
				if (e == r) continue;
				Run(v, e, g, count, res);
			}
			if (res[v].second != 0) return;
			count++;
			res[v].second = count;
		}
	};
}


