struct Tree
{
    int p, start, end;
    bool isSearched;
    vector<int> v;
};

void DFS( Tree* t, int a, int& cnt )
{
    if( t[a].isSearched )
        return;

    t[a].isSearched = true;

    cnt++;
    t[a].start = cnt;

    for( int i = 0; i < t[a].v.size(); i++ )
        DFS( t, t[a].v[i], cnt );

    cnt++;
    t[a].end = cnt;
}


