//uに隣接するvを小さい方から取得
int next(int u){
    for(int v=nt[u]; v<=n; v++){
        nt[u] = v+1;
        if(M[u][v]) return v;
    }
    return -1;
}

void dfs_visit(int r){
    for(int u=1; u<=n; u++) nt[u] = 1;

    stack<int> S;
    S.push(r);
    color[r] = GRAY;
    timer++;
    d[r] = timer;

    while(!(S.empty())){
        int u = S.top();
        int v = next(u);
        if(v != -1){
            //隣接してて行けるところがある
            if(color[v] == WHITE){
                color[v] = GRAY;
                timer++;
                d[v] = timer;
                S.push(v);
            }
        }else{
            //もう隣接してて行けるところがない
            S.pop();
            color[u] == BLACK;
            timer++;
            f[u] = timer;
        }
    }
}

