int N;

vector<vector<int>> G;

deque<bool> visited;
int t = 1;
vector<int> t_st;
vector<int> t_ed;

void dfs(int v)
{
    visited[v] = true;

    t_st[v] = t++;

    for(int to : G[v]) {
        if(visited[to]) continue;
        dfs(to);
    }

    t_ed[v] = t++;
}

void solve()
{
    visited.assign(N, false);
    t_st.assign(N, -1);
    t_ed.assign(N, -1);

    REP(i, N) {
        if(!visited[i])
            dfs(i);
    }

    REP(i, N) {
        PRINTLN(i+1, t_st[i], t_ed[i]);
    }
}

signed main(signed /*argc*/, char** /*argv*/)
{
    RD(N);
    G.resize(N);

    REP(_, N) {
        int u; RD(u); --u; // 0-based
        int k; RD(k);
        G[u].resize(k);
        REP(i, k) {
            int v; RD(v); --v; // 0-based
            G[u][i] = v;
        }
    }
#ifdef DEBUG
    DBG(G);
#endif

    solve();

    EXIT();
}

