using namespace std;

using ll = long long;
using vi = vector<int>;
using vvi = vector<vi>;
using vll = vector<ll>;

void dfs(const vvi& g, vector<bool>& seen, vi& d, vi& f, int& t, int v) {
    stack<int> st;
    st.push(v);
    d[v] = t++;
    seen[v] = true;

    while (!st.empty()) {
        int v = st.top();

        bool finished = true;
        for (auto itr = g[v].begin(); itr != g[v].end(); ++itr) {
            if (!seen[*itr]) {
                seen[*itr] = true;
                d[*itr] = t++;
                st.push(*itr);
                finished = false;
                break;
            }
        }

        if (finished) {
            st.pop();
            f[v] = t++;
        }
    }
}

