using Graph = vector<vector<ll> >;

vector<bool> seen;
vector<ll> first_order;
vector<ll> last_order;

void dfs(const Graph &G, ll v, ll& ptr) {
    // 行きがけ順をインクリメントしながらメモ
    first_order[v] = ptr++;

    seen[v] = true;
    for (auto next_v : G[v]) {
        if (seen[next_v]) continue;
        dfs(G, next_v, ptr);
    }

    // 帰りがけ順をインクリメントしながらメモ
    last_order[v] = ptr++;
}

