  first_order.resize(N);
  last_order.resize(N);

  ll ptr = 1;

  rep(i, N){
    if(!seen[i]) dfs(G, i, ptr);
  }

  rep(i , N){
    cout << i + 1 << " " << first_order[i] << " " << last_order[i] << endl;
  }
}

