void dfs(int& time,
    int start,
    const vector<vector<int>>& graph,
    vector<int>& arraialTimes,
    vector<int>& leftTimes,
    vector<bool>& checkList)
{
    stack<int> stack;
    stack.push(start);
    checkList[start] = true;
    arraialTimes[start] = ++time;

    while (!stack.empty())
    {
        int v = stack.top();
        int vSize = 0;
        for (int w : graph[v]) {
            if (!checkList[w]) {
                ++vSize;
                stack.push(w);
                checkList[w] = true;
                arraialTimes[w] = ++time;
                break;
            }
        }
        if (vSize == 0) {
            stack.pop();
            leftTimes[v] = ++time;
        }
    }
}

