	void dfs(int s) {
		if (stamp[s].first == 0)
			stamp[s].first = t++;
		else
			return;

		for (int i = 0; i < G[s].size(); ++i) {
			dfs(G[s][i].to);
		}
		stamp[s].second = t++;
	}

