int n;
int curr_time;

void dfs(int u) {
    curr_time++;
    color[u] = color_type::gray;
    find_time[u] = curr_time;

    // search adj nodes
    for (int v = 0; v < n; ++v) {
        if (adj[u][v] != 0 && color[v] == color_type::white) dfs(v);
    }
    curr_time++;
    color[u] = color_type::black;
    complete_time[u] = curr_time;
}

