    for (int v = 0; v < n; ++v) {
        color[v] = color_type::white;
        find_time[v] = 0;
        complete_time[v] = 0;
    }

    curr_time = 0;
    for (int v = 0; v < n; ++v) {
        if (color[v] == color_type::white) dfs(v);
    }
}

