int Next(vector<Vertex> &L,vector<int> &d, vector<int> &f, int cur, int count){
	int next,i,v;
	if(L[cur].deg==0){
		next=L[cur].parent;
		f[cur]=count;
		return next;
	}

	for (i=0;i<L[cur].deg;i++){
		v=L[cur].adj[i];
		if(L[v].checked==0){
			break;
			}
		}
		if(i==L[cur].deg){
			next=L[cur].parent;
			f[cur]=count;
		}else{
			next=v;
			L[next].parent=cur;
			L[next].checked=1;
			d[next]=count;
		}
	return next;
}

