	for (i=0;i<n;i++){
		cin >> id >> de;
		L[id-1].deg=de;
		for (j=0;j<de;j++){
			cin >> v;
			L[id-1].adj.push_back(v-1);
		}
		L[id-1].checked=0;
		L[id-1].parent=-1;
	}

	int cur=0;
	int next,count=0;

	while(1){
		count++;
		for (i=0;i<n;i++){
			if(L[i].checked==0){
				break;
			}
		}
		if (i==n){
			break;
		}
		L[i].checked=1;
		d[i]=count;
		cur=i;
		while(1){
			count++;
			next=Next(L,d,f,cur,count);
			if (next==-1){
				break;
			}
			cur=next;
		}
		}
	for (i=1;i<n+1;i++){
		cout << i << " " << d[i-1] << " " << f[i-1] <<endl;
	}
	return 0;
}

