struct node
{long long v; struct node *next;};

struct node *z;

void visit(long long k,  struct node **adj, long long &time, long long d[], long long f[]){
    struct node *t;
    d[k] = ++time;
    for(t = adj[k]; t != z; t = t -> next){
        if(d[t -> v] == 0) visit(t -> v, adj, time, d, f);
    }
    f[k] = ++time;
}
void search(long long V, struct node **adj, long long &time, long long d[], long long f[]){
    long long k;
    for(k = 1; k <= V; k++) d[k] = 0;
    for(k = 1; k <= V; k++){
        if(d[k] == 0) visit(k, adj, time, d, f);
    }
}

