            found.push_back(i);
        }
    }

    vector<vector<int>> res(n, vector<int>(2, -1));
    rep(i, n){
        rep(j, found.size()){
            if(found[j]==i && res[i][0]==-1) res[i][0] = j+1;
            if(found[j]==i && res[i][0]!=-1) res[i][1] = j+1;
        }
    }

    rep(i, n) cout << i+1 << " " << res[i][0] << " " << res[i][1] << endl;

    return 0;
}

