using Graph = vector<vector<int>>;

typedef int64_t Int;
const double pi = M_PI;

vector<bool> seen;
vector<vector<int>> timestamp; // タイムスタンプ

void dfs(const Graph &G, int v, int &time_ptr) {
    // 発見時刻
    timestamp[v][0] = time_ptr++;

    seen[v] = true; // v を探索済みにする

    // v から行ける各頂点について
    for (auto next_v : G[v]) {
        if (seen[next_v])
            continue; // 探索済みなら飛ばす

        dfs(G, next_v, time_ptr); // 再帰探索
    }

    // 完了時刻
    timestamp[v][1] = time_ptr++;
}

int main() {
    // 入力
