    for (int u = 0; u < N; u++) {
        int ig, k, v;
        cin >> ig >> k;
        for (; k >= 1; k--) {
            cin >> v;
            v--;
            G[u].push_back(v);
        }
    }

    // 初期化
    seen.assign(N, false);
    timestamp.assign(N, vector<int>(2, 0));
    int time_ptr = 1;
    // 探索開始
    for (int v = 0; v < N; v++) {
        if (seen[v])
            continue;

        dfs(G, v, time_ptr);
    }

    // 出力
    for (int v = 0; v < N; v++) {
        cout << v + 1 << ' ' << timestamp[v][0] << ' ' << timestamp[v][1] << endl;
    }
}

