// ALDS1_11_B: Depth First Search

#include <algorithm>
#include <cstdio>
#include <stack>
#include <utility>

using uint = unsigned int;

class Graph {
  const uint n_;
  uint* const g_;
  std::pair<uint, uint>* const visited_;

public:
  Graph(uint n) : n_(n),
                  g_(new uint[n_*n_]),
                  visited_(new std::pair<uint, uint>[n_])
  {
    init_graph();
  }

  ~Graph()
  {
    delete[] g_;
    delete[] visited_;
  }

  uint* operator [](uint i) const { return g_+(n_*i); }

  std::pair<uint, uint>* visited() const { return visited_; }

  void dfs()
  {
    std::stack<uint> s;
    auto time = 0u;
    init_visited();
    auto last_visited = 0u;
    s.push(0);
    visited_[0].first = time;
  outer_loop:
    while (!s.empty()) {
      auto i = s.top();
      for (auto j = last_visited+1; j < n_; ++j) {
        if ((*this)[i][j] && !visited_[j].first) {
          s.push(j);
          visited_[j].first = ++time;
          goto outer_loop;
        }
      }
      s.pop();
      visited_[i].second = ++time;
      last_visited = i;
    }
  }

private:
  void init_graph() { std::fill(g_, g_+(n_*n_), 0u); }

  void init_visited()
  {
    for (auto i = 0u; i < n_; ++i) {
      visited_[i].first = 0u;
    }
  }
};

int main()
{
  uint n;
  std::scanf("%u", &n);

  Graph g(n);

  uint u, k, v;
  for (auto i = 0u; i < n; ++i) {
    std::scanf("%u %u", &u, &k);
    for (auto j = 0u; j < k; ++j) {
      std::scanf("%u", &v);
      g[u-1][v-1] = 1;
    }
  }

  g.dfs();
  auto visited = g.visited();
  for (auto i = 0u; i < n; ++i) {
    std::printf("%u %u %u\n", i+1, visited[i].first+1, visited[i].second+1);
  }
}

