#include <iostream>
#include <stack>
using namespace std;

const long N = 100;
const long WHITE = 0;
const long GRAY = 1;
const long BLACK = 2;

long n, M[N + 1][N + 1];
long color[N + 1], d[N + 1], f[N + 1], tt;
long nt[N + 1];

long next(long u){
	for (long v = nt[u]; v < n; v++){
		nt[u] = v + 1;
		if (M[u][v]) return v;
	}
	return -1;
}

void dfs_visit(long r){
	for (long i = 1; i <= n; i++) nt[i] = 0;

	stack<long> S;
	S.push(r);
	color[r] = GRAY;
	d[r] = ++tt;

	while (!S.empty()){
		long u = S.top();
		long v = next(u);
		if (v != -1){
			if (color[v] == WHITE){
				color[v] = GRAY;
				d[v] = ++tt;
				S.push(v);
			}
			else {
				S.pop();
				color[u] = BLACK;
				f[u] = ++tt;
			}
		}
	}
}

void dfs(){
	for (long i = 1; i <= n; i++){
		color[i] = WHITE;
		nt[i] = 0;
	}
	tt = 0;

	for (long u = 1; u <= n; u++){
		if (color[u] == WHITE) dfs_visit(u);
	}
	for (long i = 1; i <= n; i++){
		cout << i + 1 << " " << d[i] << " " << f[i] << endl;
	}
}

int main(){
	long u, k, v;
	cin >> n;
	for (long i = 1; i <= n; i++){
		for (long j = 1; j <= n; j++){
			M[i][j] = 0;
		}
	}

	for (long i = 1; i <= n; i++){
		cin >> u >> k;
		for (long j = 1; j <= n; j++){
			cin >> v;
			M[u][v] = 1;
		}
	}

	dfs();

	return 0;
}

#include<iostream>
#include<vector>

using namespace std;
using Graph=vector<vector<int>>;

void depth_firstsearch(const Graph& graph, int vertex, vector<bool>& seen, vector<int>& first_order, vector<int>& last_order, int& time) {

	first_order.at(vertex) = time++;
	seen.at(vertex) = true;

	for (int v : graph.at(vertex)) {
		if (seen.at(v)) continue;
		depth_firstsearch(graph, v, seen, first_order, last_order, time);
	}
	last_order.at(vertex) = time++;
}

int main(void) {
	int size, vnum, adjnum, temp, time;
	cin >> size;
	Graph graph(size);
	vector<bool> seen(size, false);
	vector<int> first_order(size);
	vector<int> last_order(size);

	for (int i = 0; i < size; i++) {
		cin >> vnum >> adjnum;
		for (int j = 0; j < adjnum; j++) {
			cin >> temp;
			graph.at(vnum - 1).push_back(temp - 1);
		}
	}
	time = 1;
	for (int i = 0; i < size; i++) {
		if(seen.at(i)==false) depth_firstsearch(graph, i, seen, first_order, last_order, time);
	}

	for (int i = 0; i < size; i++) {
		cout << i + 1 << " " << first_order.at(i) << " " << last_order.at(i) << endl;
	}
	return 0;
}

