#define MAX 101

typedef struct cell{
 int id;
 struct cell *next;
}cell;

typedef struct card{
 int visited;
 int t_d;
 int t_f;
}card;


cell* makecell(int x){
cell *new=malloc(sizeof(cell));

new->id=x;
new->next=NULL;

return new;
}

void stamp(card A[],int x,char c,int time){

 A[x].visited=1;
 if(c=='d')A[x].t_d=time;
 else if(c=='f')A[x].t_f=time;

return;
}

void push(int A[],int *top,int x){

 A[*top]=x;
 (*top)++;

return;
}

int pop(int A[],int *top){

 (*top)--;
 return A[*top];

}


int main(){
 int n,i,j;
 int top1=0;
 int top2=0;
 int time=1;
 int x,y,z;
 char d='d';
 char f='f';
 int Stack1[MAX];
 int Stack2[MAX];
 card C[MAX];
 cell *S[MAX];
 cell **p;
 cell *q;
 cell *new;

 scanf("%d",&n);
 for(i=1;i<=n;i++){
  C[i].visited=0;
  S[i]=NULL;
 }

/*隣接リスト作成*/
 for(i=1;i<=n;i++){
     scanf("%d %d",&x,&y);
     p=&S[x];
     for(j=0;j<y;j++){
         scanf("%d",&z);
         new=makecell(z);
         (*p)=new;
         p=&((*p)->next);
     }
  }


 push(Stack1,&top1,1);
 stamp(C,1,d,time);

 while(top1 > 0){
       x=pop(Stack1,&top1);
       y=top1;
       if(x!=1)push(Stack2,&top2,x);
       q=S[x];
       if(q!=NULL){
          while(q!=NULL){
                if(C[q->id].visited==0){/*はじめて*/
                   time++;
                   stamp(C,q->id,d,time);
                   push(Stack1,&top1,q->id);
                }
                q=q->next;
          }
          if(y==top1){
             while(top2 > 0){
                   time++;
                   x=pop(Stack2,&top2);
                   stamp(C,x,f,time);
             }
          }
       }
       else {/*行き止まり*/
          while(top2 > 0){
                time++;
                x=pop(Stack2,&top2);
                stamp(C,x,f,time);
          }
       }
 }



 time++;
 stamp(C,1,f,time);

 for(i=1;i<=n;i++)
     printf("%d %d %d\n",i,C[i].t_d,C[i].t_f);


return 0;
}

