int top = 0;

void initialise();
int isEmpty();
int isFull();
void push(int x);
int pop();
int isTop();

void initialise() {
	top = 0;
	return;
}

int isEmpty() {
	return top == 0;
}

int isFull() {
	return top >= MAX - 1;
}

void push(int x) {
	if (isFull()) {
		printf("over flow\n");
		exit(1);
	}
	top++;
	S[top] = x;
}

int pop() {
	if (isEmpty()) {
		printf("under flow\n");
		exit(1);
	}
