int n,adj[N][N],color[N],d[N],f[N],S[N],time;

int Stacktop(){
  int i;
  for (i=1;i<=n+1;i++){
    if (S[i]==-1){
      return i;
    }
  }
}

int Stackempty(){
  int i;
  for (i=1;i<=n+1;i++){
    if (S[i]!=-1){
      return 0;
    }
  }
  return 1;
}

void Push(int r){
  S[Stacktop()] = r;
}

void DFS_Visit(int r){
  int i,u,v;
  Push(r);
  color[r] = GRAY;
  d[r] = ++time;
  while(Stackempty()==0){
    u = S[Stacktop()-1];
    v = Nextvertex(u);
    if (v != NULL){
      if (color[v] == WHITE){
	Push(v);
	color[v] = GRAY;
	d[v] = ++time;
      }
    } else {
      Pop();
      color[u] = BLACK;
      f[u] = ++time;
    }
  }
}

void DFS(){
  int u;
  for (u=1;u<=n;u++){
    color[u] = WHITE;
    time = 0;
  }
  for (u=1;u<=n;u++){
    if (color[u] == WHITE){
      DFS_Visit(u);
    }
  }
}

int Pop(){
  int i;
  S[Stacktop()-1]= -1;
  return Stacktop()-1;
}

int Nextvertex(int v){
  int i;
  for (i=1;i<=n;i++){
    if (adj[v][i]==1 && color[i]==WHITE){
      return i;
    }
  }
  return NULL;
}

