void dfs(int i){
    d[i] = ++time;

    for(int j = 1; j <= n; j++){
        //終了値が0でない時つまり、これ以上進めない時再帰せずに終了できる
        //頂点Gに点が隣接する時かつその点がまだ未発見の時再帰
        if(G[i][j] != 0 && d[j] == 0)dfs(j);
    }

    //終了前に1増える
    time += 1;
    f[i] = time;
}

