void Make_list(void){
	int edg,ver,num;
	int i;
	struct Data *new,*work;

	scanf("%d",&ver);
	scanf("%d",&edg);

	data[ver].num=ver;
	data[ver].next=NULL;

	work=&data[ver];

	for(i=0;i<edg;i++){
		work->next=New_list();
		work=work->next;
	}
}


