void DFS(void){
	int i;

	time=0;
	top=0;

	for(i=0;i<n;i++) stack[i]=-1;

	for(i=1;i<=n;i++) color[i]='w';

	for(i=1;i<=n;i++){
		if(color[i]=='w') DFS_visit(i);
	}

}


void DFS_visit(int u){
	int v;

	Push(u);

	color[u]='g';

	d[u]=++time;

	while(top!=0){
		u=stack[top-1];
		v=Next(u);

		if(v!=-1){
			Push(v);
			color[v]='g';
			d[v]=++time;
		}
		else{
			Pop();
			color[u]='b';
			f[u]=++time;
		}
	}

}


void Push(int u){
	stack[top]=u;
	top++;
}


void Pop(void){
	top--;
	stack[top]=NON;
}


int Next(int u){
	struct Data *work;

	work=&data[u];

	while(work->next != NULL){
		if(color[work->next->num]=='w') return work->next->num;

		work=work->next;	
	}

	return -1;	
}

