void visit(int r){
  int u,v,i;
  int j;
  push(r);
  color[r]=G;
  d[r]=++time;
  while(top>0){
    //printf("DEBUG2\n");
    u=stack[top-1];
    v=next(u);
    //printf("u=%d,v=%d\n",u,v);
    //printf("top=%d, ",top);
    //for(j=0; j<=top; j++) printf("%d ",stack[j]);
