#include <stdio.h>

// I/O
int get_uint() {
    int n = 0;
    int c = getchar_unlocked();
    if(c < 48 || 57 < c) return c;
    while(47 < c && c < 58) n = 10 * n + (c & 0xf), c = getchar_unlocked();
    return n;
}
void put_uint(int n) {
    if(!n) {
        putchar_unlocked('0');
        return;
    }
    char buf[11];
    int i = 0;
    while(n) buf[i++] = (char)(n % 10 + '0'), n /= 10;
    while(i--)putchar_unlocked(buf[i]);
}
//


// Solve
void dfs(int G[100][100], int n, int *d, int *f, int u) {
    static int t = 0;
    d[u] = ++t;
    for(int i = 0; i < n; ++i) {
        if(!G[u][i] || d[i]) continue;
        dfs(G, n, d, f, i);
    }
    f[u] = ++t;
}

int main(int argc, char **argv) {
    int n = get_uint();
    int G[100][100] = {};
    for(int i = 0; i < n; ++i) {
        int u = get_uint() - 1;
        int k = get_uint();
        for(int j = 0; j < k; ++j) G[u][get_uint() - 1] = 1;
    }
    int d[100], f[100] = {};
    for(int i = 0; i < n; ++i)
        if(!f[i]) dfs(G, n, d, f, i);
    for(int i = 0; i < n; ++i) {
        put_uint(i + 1), putchar_unlocked(' ');
        put_uint(d[i]), putchar_unlocked(' ');
        put_uint(f[i]), putchar_unlocked('\n');
    }
    return 0;
}

#include<stdio.h>
#define N 100
#define White 0
#define Gray 1
#define Black 2
void dfs_init(void);
void dfs(void);
int tops(void);
void push(int);
void pop(void);
int next(int);

int n, M[N][N];
int color[N],d[N],f[N],co,rem[N];
int S[N*N],top=-1;

int main(){
  int i,j,u,k,v;
  for(i = 0; i < N; i++){
    for(j = 0; j < N; j++){
      M[i][j] = 0; 
    }
  }

  scanf("%d",&n);
  for(i = 0; i < n; i++){
    scanf("%d %d",&u,&k);
    for(j = 0; j < k; j++){
      scanf("%d",&v);
      M[u-1][v-1] = 1;
    }
  }
  dfs();

  for(i = 0; i < n; i++){
    printf("%d %d %d\n",i+1,d[i],f[i]);
  }
  return 0;
}

void dfs_init(){
  int i;
  for(i = 0; i < n; i++){
    color[i] = White;
  }
}

void dfs(){
  int u = 0;
  int v;
  dfs_init();

  push(u);
  color[u] = Gray;
  d[u] = ++co;

  while(top != -1){
    u = tops();
    v = next(u);
    if(v != -1){
      if(color[v] == White){
	color[v] = Gray;
	d[v] = ++co;
	push(v);
      }
    }
    else {
      pop();
      color[u] = Black;
      f[u] = ++co;
    }
  }
}

int tops(){
  return S[top];
}

void push(int u){
  S[++top] = u;
}

void pop(){
  top--;
}

int next(int u){
  int v;
  for(v = rem[u]; v < n; v++){
    rem[u] = v + 1;
    if(M[u][v]) return v;
  }
  return -1;
