  while( top != 1 ){ //Stack is not empty
    u = stack[top-1];
    v = next(u);
    if( v != DISCONNECT ){
      if( color[v] == WHITE ){
	push(v);
	color[v] = GRAY;
	d[v] = ++time;
      }
    }
    else{
      pop();
      color[u] = BLACK;
      f[u] = ++time;
    }
  } 
}

