/* 有向グラフに対して深さ優先探索を行う関数 */
void dfs(int n)
{
  int i;

  /* colorをWHITEで初期化 */
  for( i = 1 ; i<=n; i++ )
    color[i] = WHITE;

  /* まだ訪れていない頂点を訪れる */
  for( i = 1; i<=n; i++ )
    {
      if( color[i] == WHITE )
	visit(i);
    }
}


/* 頂点uとそれに隣接する頂点を再帰的に訪れ、タイムスタンプを押す関数 */
void visit(int u)
{
  int i;

  color[u] = GLAY;     /* 頂点uを訪れたと設定 */
  d[u] = ++t;       /* 発見時刻スタンプを押す */

  for( i = 0; i<k[u]; i++ )
    {
      if( color[ *(Adj[u]+i) ] == WHITE )
	visit( *(Adj[u]+i) );
    }

  color[u] = BLACK;       /* 頂点uを調べ終わったと設定 */
  f[u] = ++t;          /* 終了時刻スタンプを押す */
}

