#include <stdio.h>
#include <stdlib.h>

#define SIZE 100
#define FORWARD 0
#define BACKWORD 1
#define WHITE 0
#define GRAY 1
#define BLACK 2
#define NIL -1


int graph[SIZE][SIZE];
int color[SIZE];
int nextnum[SIZE];
int timestamp[2][SIZE];
int time;

typedef struct _node {
	int val;
	struct _node *next;
} node;

node *allocNode(int val) {
	node *p = (node *)malloc(sizeof(node));
	p->val = val;
	p->next = NULL;
	return p;
}

void push(node **top, node *p) {
	if (p == NULL) return;
	p->next = *top;
	*top = p;
}

void pop(node **top) {
	if (*top == NULL) return;
	node *tmp = *top;
	*top = (*top)->next;
	free(tmp);
}

int nextVertex(int u, int n) {
	int i, nv = NIL;
	for (i = nextnum[u]; i < n; i++) {
		if (graph[u][i] == 1 && color[i] == WHITE) {
			nv = i;
			break;
		}
	}

	if (nv != NIL) nextnum[u] = nv + 1;
	else nextnum[u] = n;

	return nv;

}

void dfs(int u, node **top, int n) {
	int i, v;
	node *p;
	for (i = 0; i < n; i++) nextnum[i] = 0;

	p = allocNode(u);
	push(top, p);
	color[u] = GRAY;
	timestamp[FORWARD][u] = ++time;

	while (*top != NULL) {
		u = (*top)->val;
		v = nextVertex(u, n);
		if (v != NIL) {
			p = allocNode(v);
			push(top, p);
			color[v] = GRAY;
			timestamp[FORWARD][v] = ++time;
		}
		else {
			pop(top);
			color[u] = BLACK;
			timestamp[BACKWORD][u] = ++time;
		}
	}
}

