{
	int i, j, n, u, k, v;
	node *top;

	scanf("%d", &n);
	for (i = 0; i < n; i++)
		for (j = 0; j < n; j++)
			graph[i][j] = 0;

	for (i = 0; i < n; i++) {
		scanf("%d %d", &u, &k);
		for (j = 0; j < k; j++) {
			scanf("%d", &v);
			graph[u - 1][v - 1] = 1;
		}
	}

	for (i = 0; i < n; i++)	color[i] = WHITE;

	time = 0;
	top = NULL;
	for (i = 0; i < n; i++) {
		if (color[i] == WHITE) dfs(i,&top,n);
	}

	for (i = 0; i < n; i++) {
		printf("%d %d %d\n", i + 1, timestamp[FORWARD][i], timestamp[BACKWORD][i]);
	}
	return 0;
}

