void dfs(void)
{
  int i;

  for(i = 0; i < n; i++) color[i] = 1; //1 = white
  time = 0;
}

void visit(int r)
{
  int u, v;

  push(r); // Stack S
  color[r] = 2; //2 = GRAY
  d[r] = 1 + time;
  time++;

  while(top != -1){
    u = S[top];
    v = next(u);

    if(v != 0){
      if(color[v] == 1){
	push(v);
        color[v] = 2;
	d[v] = 1 + time;
	time++;
      }
    }
    else{
      pop();
      color[u] = 3; //3 = BLACK
      f[u] = 1 + time;
      time++;
    }
  }
}

void push(int x)
{
    top++;
    S[top] = x;
}

void pop(void)
{
  top--;
}

int next(int u)
{
  int i;

  for(i = temp[u]; i <= n; i++){
    temp[u] = i + 1;
    if(G[u][i]) return i;
  }
  return 0;
}

