#include <stdio.h>
#include <stdlib.h>

typedef struct _node {
	int value;
	int forward;
	int backward;
	struct _node ***child;
	int chldNum;
} node;

void terminate(node **p, int n) {
	int i;
	for (i = 0; i < n; i++) {
		if (p[i]->child != NULL) free(p[i]->child);
		free(p[i]);
	}
	free(p);
}

void dfs(node **pp, int *time) {
	int i;
	node *p = *pp;
	node **next;
	if (p->forward > 0) return;
	p->forward = ++(*time);
	for (i = 0; i < p->chldNum; i++) {
		next = p->child[i];
		dfs(next, time);
	}
	p->backward = ++(*time);
}

int main() {
	int i, j, k, n, u, v, time;
	node **top;

	scanf("%d", &n);
	top = (node **)malloc(sizeof(node*) * n);
	for (i = 0; i < n; i++) {
		scanf("%d %d", &u, &k);
		node *p = (node *)malloc(sizeof(node));
		p->value = u;
		p->forward = 0;
		p->backward = 0;
		p->chldNum = k;
		if (k > 0) {
			p->child = (node ***)malloc(sizeof(node **) * k);
			for (j = 0; j < k; j++) {
				scanf("%d", &v);
				p->child[j] = &top[v - 1];
			}
		}
		else p->child = NULL;		

		top[i] = p;
	}

	time = 0;
	dfs(top, &time);

	for (i = 0; i < n; i++)
		printf("%d %d %d\n", top[i]->value, top[i]->forward, top[i]->backward);

	terminate(top, n);

	return 0;
}

