void dfs_init(int n, int maxval, int *color, int *d, int *f){
  int i;
  for(i = 0; i < n; i++){
    color[i] = WHITE;
  }
  for(i = 0; i < n; i++){
    d[i] = f[i] = 0;
  }

  time = 0;

  for(i = 0; i < n; i++){
    if(color[i] == WHITE) dfs(i,maxval,color,d,f);
  }
}

void dfs(int u, int maxval, int *color, int *d, int *f){
  int i,v;

  color[u] = GRAY;
  d[u] = ++time;
  for(v = 0; v <= maxval; v++){
    if(M[u][v] && color[v] == WHITE){
      dfs(v,maxval,color,d,f);
    }
  }
  color[u] = BLACK;
  f[u] = ++time;
}

