void dfs (int i)
{
  int j = 1;

  if (k[i] != 0){
    d[i] = count;
    count++;
    dfs (v[i][j]);
    if (j < k[i] && d[v[i][j+1]] == 0)
      dfs (v[i][++j]);
  }
  if (d[i] == 0 && k[i] == 0){
    d[i] = count;
    count++;
    f[i] = count;
    count++;
  }
  if (d[i] != 0 && k[i] != 0){
    f[i] = count;
    count++;
  }

  return;
}

