void find(int temp){
  static int count=0;
  static int x=1,y;

  if(a[temp][1]!=0){  
    if(d[temp]==0) d[temp] = ++count;
    else {
      f[temp] = ++count;
      return;
    }

    if(temp!=1){
      pre[temp] = x;
      x = temp;
    }

    y=a[temp][2];
    push(a[temp]);
    find(y);
  }

  else{
    if(temp!=1 && d[temp]==0){
      pre[temp] = x;
      x = temp;
    }
    if(d[temp]==0){
      d[temp] = ++count;
      f[temp] = ++count;
      find(pre[temp]);
    }
    else if(f[temp]==0){
      f[temp] = ++count;

      find(pre[temp]);
    }
    else if(temp != 1)find(pre[temp]);
    else return;
  }
}


