int  hi[MAX_V], *to[MAX_V];
int  que[MAX_V]; int top;
char mk[MAX_V];

int main()
{
	int n, i, j, k, u, tm;

	n = in();
	for (i = 0; i < n; i++) {
		u = in()-1;
		hi[u] = k = in();
		to[u] = malloc(k<<2);
		for (j = 0; j < k; j++) to[u][j] = in()-1;
