int walk(int in, int time, int way[100][100], int *d, int *f) {
    int *p;

    d[in] = ++time;
    for (p = way[in]; *p != 0; p++) {
        if (!d[*p]) {
            time = walk(*p, time, way, d, f);
        }
    }
    f[in] = ++time;
    return time;
}

