  int i;
  S[Stacktop()-1]= -1;
  return Stacktop()-1;
}

int Nextvertex(int v){
  int i;
  for (i=1;i<=n;i++){
    if (adj[v][i]==1 && color[i]==WHITE){
      return i;
    }
  }
  return NULL;
}

