#define MAX_SIZE 101
typedef struct { int seq, o[MAX_SIZE][2]; } dfs_t;

static dfs_t *dfs(int g[MAX_SIZE][MAX_SIZE], int size, int i, dfs_t *dt) {
  int j;

  if (dt->o[i][0] > 0) return dt;

  dt->o[i][0] = dt->seq++;
  for (j = 1; j <= size; ++j) {
    if (g[i][j] == 0) continue;
    if (i != j) dt = dfs(g, size, j, dt);
  }
  if (dt->o[i][1] == 0) dt->o[i][1] = dt->seq++;
  return dt;
}

