    dt.o[i][0] = dt.o[i][1] = 0;
    for (j = 0; j < MAX_SIZE; ++j) g[i][j] = 0;
  }

  scanf("%d", &n);
  for (i = 0; i < n; ++i) {
    scanf("%d %d", &k, &l);
