    printf("%d %d %d\n",u+1,d[u],f[u]);
}

void visit(int u,int n)
{
  int i,v;

  color[u] = GRAY; //訪問したらグレーにする
  d[u] = ++t; //訪問の時間を記録

  for(v=0;v<n;v++){
    if(G[u][v] == 0) continue; //行列にない部分は飛ばす
    if(color[v] == WHITE) visit(v,n); //白なら再起的に訪問
  }
  color[u] = BLACK; //訪問が終わったら黒にする
  f[u] = ++t; //訪問完了の時間を記録
}

