int walk(int i, int time, int w[101][101], int *d, int *f)
{
  int *p;

  d[i] = ++time;
  for (p = w[i]; *p != 0; p++)
    if (!d[*p])
      time = walk(*p, time, w, d, f);
  f[i] = ++time;

  return time;
}

