void dfs(int id)
{
  int current = id;

  t++;
  if (adj[id].d == 0) adj[id].d = t;

  while (adj[id].visited != adj[id].k) {
    current = adj[id].vlist[adj[id].visited++];
    if (adj[current].d == 0) dfs(current);
  }

  t++;
  if (adj[id].f == 0) adj[id].f = t;
}

#include <stdio.h>

int walk(int index, int time, int wayto[101][101], int *d, int *f) {
	int *p;

	d[index] = ++time;
	for (p = wayto[index]; *p != 0; p++) {
		if (!d[*p]) {
			time = walk(*p, time, wayto, d, f);
		}
	}
	f[index] = ++time;
	return time;
}

