      G[i][j] = 0;
    }
  }

  /* 発見時刻の初期化 */
  for(i = 0;i < n;i++){
    d[i] = 0;
  }

  /* stackの初期化 */
  initialize();

  /* グラフG */
  scanf("%d",&n);

  for(i = 0;i < n;i++){
    scanf("%d",&u);
    scanf("%d",&k);

    U = (int *)malloc(sizeof(int) * k);
    if(U == NULL) exit(0);

    for(j = 0;j < k;j++){
      scanf("%d",&U[j]);
      G[u][U[j]] = 1;
    }
  }

