int n;

int dfs(int curTime, int node) {
  int i, j;

  times[node][0] = curTime;
  neighbors[node][0] = 0;

  for (i = 1; i < n + 1; i++) {
    if (neighbors[node][i] && neighbors[i][0]) {
      curTime = dfs(curTime + 1, i);
    }
  }

  times[node][1] = ++curTime;
  return curTime;
}


