int get_idx(int set_dt,int *idx_p,int *wk_p)
{
	if (set_dt <= 0) {
		printf("ERROR\n");
		return -1;
	}


	*idx_p = (set_dt-1) / 32;
	*wk_p  = set_dt % 32;
//	*wk_p  = set_dt - (*idx_p * 32) - 1;
	if (*wk_p < 0) {
		printf("ERROR1\n");
		return -1;
	}
	if (*idx_p > 3) {
		printf("ERROR2\n");
		return -2;
	}
	return 0;
}
int bit_set(unsigned long *bitmap_p , int bit_idx,int setdt)
{
	int idx;
	int wk;
	int rtn;
	int bit;

	if ((rtn=get_idx(bit_idx,&idx,&wk)) != 0) {
		printf("ERROR 3\n");
		return rtn;
	}
	if (setdt == 0) {
		bitmap_p[idx] &= ~(1 << (wk-1));
	}
	else {
		bitmap_p[idx] |= 1 << (wk-1);
	}
	return 0;
}

int bit_cmp(unsigned long *bitmap_p , int cmpdt)
{
	int idx;
	int wk;
	int rtn;

	if ((rtn=get_idx(cmpdt,&idx,&wk)) != 0) {
		printf("ERROR 4\n");
		return rtn;
	}
	if (((bitmap_p[idx] >> (wk-1)) & 1) != 0) {
		return 1;
	}
	else {
		return 0;
	}
}
int sch_idx(int loop,int max)
{
	int i,wk;

	for (i=0 ; i<max ; i++) {
		wk = bit_cmp(graph[loop].bitmap,i+1);
		if (wk != 0) {
			return i+1;
		}
	}
	return -1;
}

int pop(void)
{
	int rtn;
	if (stack_num == -1) {
		return -1;
	}
	stack_num--;
	rtn = stack[stack_num];

	return rtn;
}

int push(int deg_num)
{
	if (stack_num >= MAX_DEG) {
		return -1;
	}
	stack[stack_num] = deg_num;
	stack_num++;

	return stack_num;
}

