void scanData(int M[][MAXN], int n)
{
  int i, j, u, k, v;

  for(i = 1; i <= n; i++) {
    for(j = 1; j <= n; j++) {
      M[i][j] = 0;
    }
  }

  for(i = 1; i <= n; i++) {
    scanf("%d%d",&u,&k);

    for(j = 1; j <= k; j++) {
      scanf("%d",&v);
      M[i][v] = 1;
    }
  }
}

