{
  int i, time = 0;

  for(i = 1; i <= n; i++) {
    Node[i].color = WHITE;
  }
  for(i = 1; i <= n; i++) {
    if(Node[i].color == WHITE) time = visit(M, Node, n, time, i);
  }
}

int visit(int M[][MAXN], NODE *Node, int n, int time, int u)
{
  int i, v;
  Node[u].color = GRAY;
  Node[u].d = ++time;
  for(v = 1; v <= n; v++) {
    if(M[u][v] == 1 && Node[v].color == WHITE) time = visit(M, Node, n, time, v);
  }
  Node[u].color = BLACK; /*finished*/
  Node[u].f = ++time;

  return time;
}

