    if (S[i]==-1){
      return i;
    }
  }
}

int Stackempty(){
  int i;
  for (i=1;i<=n+1;i++){
    if (S[i]!=-1){
      return 0;
    }
  }
  return 1;
}

void Push(int r){
  S[Stacktop()] = r;
}

void DFS_Visit(int r){
  int i,u,v;
  Push(r);
  color[r] = GRAY;
  d[r] = ++time;
  while(Stackempty()==0){
    u = S[Stacktop()-1];
    v = Nextvertex(u);
    if (v != NULL){
      if (color[v] == WHITE){
	Push(v);
	color[v] = GRAY;
	d[v] = ++time;
      }
    } else {
      Pop();
      color[u] = BLACK;
      f[u] = ++time;
    }
  }
}

