int main(int argc, char *argv[]) {
    int n, i, j, u, k, tm = 0;
    int d[101] = {},f[101] = {};
    int way[101][101] = {};

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d %d", &u, &k);
        for (j = 0; j < k; j++) {
            scanf("%d", &way[u][j]);
        }
    }
    for (i = 1; i <= n; i++) {
        if (!d[i]) {
            tm = walk(i, tm, way, d, f);
        }
    }
    for (i = 1; i <= n; i++) {
        printf("%d %d %d\n", i, d[i], f[i]);
    }
    return 0;
}
int walk(int in, int time, int way[100][100], int *d, int *f) {
    int *p;

    d[in] = ++time;
    for (p = way[in]; *p != 0; p++) {
        if (!d[*p]) {
            time = walk(*p, time, way, d, f);
        }
    }
    f[in] = ++time;
    return time;
}

