typedef struct
{
	int k, v[100];
	int d, f;
	int visited;
} Node;

int dfs(Node *node, int u, int t)
{
	if(node[u].visited == 0)
	{
		node[u].visited = 1;

		node[u].d = ++t;
		for(int i = 0; i < node[u].k; ++i)
		{
			t = dfs(node, node[u].v[i], t);
		}
		node[u].f = ++t;
	}
	return t;
}

