    u = top();
    v = next(u,V);
    if(v != 0) {
      if(color[v] == WHITE) {
	push(v);
	color[v] = GRAY;
	d[v] = ++time;
      }
    }
    else {
      pop();
      color[u] = BLACK;
      f[u] = ++time;
    }
  }

}

void push(int r)
{
  S[count] = r;
  count++;
}

void pop(void)
{
  count--;
}

int top(void)
{
  return S[count-1];
}

int next(int u,int V)
{
  int i,flag=0;
for(i = 1; i <= V; i++) {
  if(G[u][i] == 1) {
    G[u][i] = 0;
    flag++;
    break; 
}
 }
 if(flag == 0)
   return 0;
 else
   return i;
}

