void dfp(int id, int n) {
  // 0-origin
  int i;
  if (finish[id] != 0) {
    return;
  }
  else if (discover[id] == 0){
    discover[id] = (++time);
  }

  for (i = 0; i < n; i++) {
    if (adj[id][i] == 1 && discover[i] == 0) {
      discover[i] = (++time);
      dfp(i, n);
    }
  }
  finish[id] = (++time);
}

