//スタック
void dfs(void)
{
  int i;

  for(i = 1; i <= n; i++) G[i].color = 1; //1 = white
  time = 0;
  if(G[1].color == 1) visit(1);
}

void visit(int r)
{
   int u, v=r;

  push(r); // Stack S
  G[r].color = 2; //2 = GRAY
  G[r].d = 1 + time;
  time++;

  while(isEmpty() == 1){
    u = S[top];
      v = G[G[u].v[2]].u; // the next vertex of u
    else v = G[G[u].v[1]].u;

    if(v >= 0){
      if(G[v].color == 1){
	push(v);
	if(G[v].v[2] > 0) G[v].color = 4;
	else G[v].color = 2;
	G[v].d = 1 + time;
	time++;
      }
      else{
	u = pop();
	G[u].color = 3; //3 = BLACK
	G[u].f = 1 + time;
	time++;
      }
    }
  }
}

void push(int x)
{
  if(isFull() == 1){
    top++;
    S[top] = x;
  }
}

int isFull(void)
{
  if(top > N - 1) return 0;
  else return 1;
}

int isEmpty(void)
{
  if(top == 0) return 0;
  if(top != 0) return 1;
}

int pop(void)
{
  if(isEmpty() == 1){
  top--;
  return S[top+1];
  }
}

