data class Node(val id: Int, val edges: List<Int>, var discoveredTime: Int = 0, var finishedTime: Int = 0, var visited: Boolean = false)

fun main(args: Array<String>) {
    val nodeList = List(readLine()?.toInt() ?: 0) {
        val input = readLine()?.split(" ".toRegex())?.map(String::toInt) ?: listOf()
        Node(input[0], input.subList(2, 2 + input[1]))
    }
    val dfs = Dfs(nodeList)
