}
class Dfs(private val nodes: List<Node>) {
    init {
        dfs()
    }

    private var time = 0

    fun print() {
        println(
            nodes.joinToString("\n") { node ->
                "${node.id} ${node.discoveredTime} ${node.finishedTime}"
            }
        )
    }

    private fun dfs() {
        nodes.forEach { edgeNode ->
                if (!edgeNode.visited) {
                    visit(edgeNode)
                }
            }
    }

    private fun visit(node: Node) {
        node.visited = true
        node.discoveredTime = ++time
        nodes.filter { node.edges.contains(it.id) }
            .forEach { edgeNode ->
                if (!edgeNode.visited) {
                    visit(edgeNode)
                }
            }
        node.finishedTime = ++time
    }
}

