data class Timestamp(var findedAt: Int? = null, var endedAt: Int? = null)

class Main {

    companion object {
        private val graphMatrix = arrayListOf<ArrayList<Boolean>>()

        private val timestampList = arrayListOf<Timestamp>()

        private var currentTime = 0

        fun init() {
            val num = readLine()!!.toInt()

            initgraph(num)

            for (index in 1..num) {
                val inputs = readLine()!!.split(" ")
                val nodeIndex = inputs[0].toInt()
                for (inputIndex in 2 until inputs.size) {

                    val touchedNode = inputs[inputIndex].toInt()
                    graphMatrix[nodeIndex - 1][touchedNode - 1] = true
                }
            }
        }

        fun display() {
            println(timestampList.mapIndexed { index, timestamp ->
                "${index + 1} ${timestamp.findedAt} ${timestamp.endedAt}"
            }.joinToString("\n"))
        }

        /**
         * 深さ優先
         */
        fun execute() {

            // 全て探索するため永久に
            while (true) {
                var index: Int? = null
                for (i in 1..timestampList.size) {
                    if (timestampList[i - 1].findedAt == null) {
                        index = i
                        break
                    }
                }

                if (index == null) break

                dig(index)
            }
        }

        /**
         * 下に掘る
         */
        fun dig(index: Int) {
            // 時間経過
            currentTime++

            // 発見を記録
            timestampList[index - 1].findedAt = currentTime

            graphMatrix[index - 1].forEachIndexed { touchedIndex, b ->
                // エッジがあるなおかつ未探索
                if (b && timestampList[touchedIndex].findedAt == null) {
                    dig(touchedIndex + 1)
                }
            }

            // 時間経過
            currentTime++

            // 発見を記録
            timestampList[index - 1].endedAt = currentTime
        }


        fun initgraph(num: Int) {
            for (i in 0 until num) {
                graphMatrix.add(arrayListOf())
                for (j in 0 until num) {
                    graphMatrix[i].add(false)
                }
                timestampList.add(Timestamp())
            }
        }
    }
}

