	public static void dfs(int i) {
		// already visited
		if (time[i][0] > 0)
			return;

		time[i][0] = ++t;

		for (int j = 0; j < matrix[i].length; j++) {
			// linked
			if (matrix[i][j] == 1) {
				dfs(j);		
			}
		}

		// all search
		time[i][1] = ++t;
	}
