				a[u - 1][sc.nextInt() - 1] = 1;
			}
		}

		int clock = 0;
		for (int i = 0; i < n; i++) {
			if (f[i] == 0) {
				clock = dfs(i + 1, clock + 1);
			}
		}

		for (int i = 0; i < n; i++) {
			pr.print(i + 1);
			pr.print(" ");
			pr.print(d[i]);
			pr.print(" ");
			pr.print(f[i]);
			pr.println("");
		}

		pr.close();
		sc.close();
	}

	private static int dfs(int v, int clock) {
		if (d[v - 1] == 0) {
			d[v - 1] = clock;
			for (int i = 0; i < n; i++) {
				if (a[v - 1][i] != 0) {
					if (f[i] != 0) {
						continue;
					} else if (i + 1 == v) {
						continue;
					} else {
						clock = dfs(i + 1, clock + 1);
					}
				}
			}
			clock++;
			f[v - 1] = clock;
			return clock;
		} else {
			if (f[v - 1] == 0) {
				clock++;
				f[v - 1] = clock;
				return clock;
			} else {
				return clock;
			}
		}
	}

