public class Main {

	static int ns[],res[][],L[][];
	static int time=1;

	public static void main(String[] args) {
		Scanner in=new Scanner(System.in);

		int n=in.nextInt(); L=new int[n+1][n+1];
		ns=new int[n+1]; res=new int[n+1][2];

		 for(int i=0;i<n;i++) {
			 int u=Integer.parseInt(in.next()), k=Integer.parseInt(in.next());

			 for(int j=0;j<k;j++) {
				 int v=Integer.parseInt(in.next());
				 L[u][v]=1;
			 }
		 }

		 Stack<Integer> stk=new Stack<>();
		 stk.push(1);

		 DFS(stk);

		 PrintWriter out=new PrintWriter(System.out);
		 for(int i=1;i<=n;i++)out.printf("%d %d %d\n", i, res[i][0], res[i][1]);
		 out.flush();
	}

	static void DFS(Stack<Integer> stk) {
		int v=stk.peek();
		ns[v]=1; res[v][0]=time; time++;

		for(int i=1;i<=ns.length-1;i++) {
			if(L[v][i]==1 && ns[i]!=1) {
				stk.push(i);
				DFS(stk);
			}
		}

		res[v][1]=time; time++;
		stk.pop();
		return;
	}
}

import java.util.Scanner;

class Node {
	public int id;
	public int startTime = -1;
	public int finishTime = -1;
	int[] childrenIds;
	public Node[] children;

	public Node(int id, int[] children) {
		this.id = id;
		this.childrenIds = children;
		this.children = new Node[children.length];
	}

	public void getChildrenNodes(Node[] list) {
		for (int i = 0; i < this.childrenIds.length; i++) {
			for (int j = 0; j < list.length; j++) {
				if (this.childrenIds[i] == list[j].id) {
					this.children[i] = list[j];
				}
			}
		}
	}
}

public class Main {
	public static int currTime = 0;

	public static void traverseNode(Node node) {
		if (node.startTime != -1) return;

		node.startTime = currTime;

		for (int i = 0; i < node.children.length; i++) {
			if (node.children[i].startTime == -1) {
				currTime += 1;
				traverseNode(node.children[i]);
			}
		}

		currTime += 1;
		node.finishTime = currTime;
	}

	public static void main(String[] args) {
		Scanner scanner = new Scanner(System.in);
		int numNodes = scanner.nextInt();
		Node[] nodes = new Node[numNodes];

		//create our graph
		for (int i = 0; i < numNodes; i++) {
			int id = scanner.nextInt();
			int numChildren = scanner.nextInt();
			int[] children = new int[numChildren];

			for (int j = 0; j < numChildren; j++) {
				children[j] = scanner.nextInt();
			}
			nodes[i] = new Node(id, children);
		}
		scanner.close();

		//first get children nodes of each node
		for (int i = 0; i < nodes.length; i++) {
			nodes[i].getChildrenNodes(nodes);
		}

		//traverse the nodes
//		traverseNode(nodes[0]);
		for (int i = 0; i < nodes.length; i++) {
			if (nodes[i].startTime == -1) currTime += 1;
			traverseNode(nodes[i]);
		}

		//say that we're done
		for (int i = 0; i < nodes.length; i++) {
			System.out.println(nodes[i].id + " " + nodes[i].startTime + " " + nodes[i].finishTime);
		}
	}
}

import java.util.Scanner;

public class Main {

    static Scanner sc = new Scanner(System.in);
    static final int N = 100;
    static int n, c;
    static int[][] Mat = new int[N][N];
    static int[] dp = new int[N];
    static int[] visited = new int[N];
    static int[] done = new int[N];

    static final int NOT_FOUND_YET = 0;
    static final int VISITED = 1;
    static final int DONE = 2;

    public static void main(String[] args) {
        read();
        dfs(0);
        out();
    }

    static void read() {
        n = sc.nextInt();
        int u, k, v;
        for (int i = 0; i < n; i++) {
            u = sc.nextInt();
            k = sc.nextInt();
            for (int j = 0; j < k; j++) {
                v = sc.nextInt();
                Mat[u - 1][v - 1] = 1;
            }
        }
    }

    static void out() {
        for (int i = 0; i < n; i++) {
            System.out.println(String.format("%d %d %d", i + 1, visited[i], done[i]));
        }
    }

    static void dfs(int i) {
        if (dp[i] != NOT_FOUND_YET) {
            return;
        }

        c++;
        dp[i] = VISITED;
        visited[i] = c;

        for (int j = 0; j < n; j++) {
            if (Mat[i][j] == 1) {
                dfs(j);
            }
        }

        c++;
        dp[i] = DONE;
        done[i] = c;
    }
}

