public class Main {

  public static void main(String[] args) {

    new Main().run();
  }

  public void run() {

    try(BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {

      int n = Integer.parseInt(br.readLine());
      Graph graph = new Graph(n);
      int[] ajacent;
      String[] vInfo;
      int id,degree;

      for(int i=0,v=0; i<n; i++) {
        vInfo  = br.readLine().split(" ");
        id     = Integer.parseInt(vInfo[0]);
        degree = Integer.parseInt(vInfo[1]);
        ajacent = new int[degree];
        for(int j=0; j<degree; j++) {
          ajacent[j] = graph.convIdToIndex( Integer.parseInt(vInfo[j+2]) );
        }
        graph.setVertex(id, ajacent);
      }

      graph.vertexSearch(1);

      graph.dispReport();
    }
    catch (IOException e) {
      System.err.println(e);
    }
  }

  class Graph {

    Vertex[] vertices;
    int time;

    public Graph(int size ) {
      vertices  = new Vertex[size];
      time = 0;
    }

    public void setVertex(int id) {
      vertices[id-1] = new Vertex(id);
    }
    public void setVertex(int id, int[] ajacent) {
      setVertex(id);
      setAjacent(id, ajacent);
    }
    public void setAjacent(int id, int[] ajacent) {
      vertices[id-1].ajacent = ajacent;
    }
    public void vertexSearch(int id) {
      depthFirstSearch(id-1);
    }
    public void dispReport() {
      StringBuilder buf = new StringBuilder();

      for (Vertex v : vertices) {
          buf.append(v.id).append(" ")
             .append(v.findTime).append(" ")
             .append(v.doneTime).append("\n");
      }

      System.out.print(buf);
    }
    public int convIdToIndex(int id) {
      return id-1;
    }

    private void depthFirstSearch(int index) {
      vertices[index].state = Vertex.GRAY;
      vertices[index].findTime = ++time;

      for(int ajcIndex: vertices[index].ajacent) {
        if(vertices[ajcIndex].state == Vertex.WHITE)
          depthFirstSearch(ajcIndex);
      }
      vertices[index].state = Vertex.BLACK;
      vertices[index].doneTime = ++time;
    }

    class Vertex {

      static final int WHITE = 0;
      static final int GRAY  = 1;
      static final int BLACK = 2;
      int id;
      int index;
      int state;
      int[] ajacent;
      int findTime;
      int doneTime;

      public Vertex(int id) {
        this.id = id;
        index = id-1;
        state = WHITE;
      }
    }
  }
}

import java.util.Scanner;
import java.util.Stack;

public class Main {
	public static void main(String[] args) {
		try (Scanner scan = new Scanner(System.in)) {
			int n = scan.nextInt();
			int[][] map = new int[n][n];
			int[] state = new int[n];
			int[] discovery = new int[n];
			int[] finish = new int[n];
			for(int i=0; i<n; i++) {
				int from = scan.nextInt()-1;
				int m = scan.nextInt();
				for(int j=0; j<m; j++) {
					int to = scan.nextInt()-1;
					map[from][to] = 1;
				}
			}
			Stack<Integer> stack = new Stack<>();
			stack.push(0);
			state[0] = 1;
			int time = 1;
			discovery[0] = time;
			while(!stack.isEmpty()) {
				int now = stack.peek();
				time++;
				boolean findConnect = false;
				for(int i=0; i<n; i++) {
					if(now == i) continue;
					if(map[now][i] == 1 && state[i] == 0) {
						stack.push(i);
						state[i] = 1;
						discovery[i] = time;
						findConnect = true;
						break;
					}
				}
				if(!findConnect) {
					stack.pop();
					state[now] = 2;
					finish[now] = time;
				}
			}
			for(int i=0; i<n; i++) {
				System.out.println((i+1) + " " + discovery[i] + " " + finish[i]);
			}
		}
	}
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;


public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();
		boolean[][] a = new boolean[n][n];

		for (int i = 0; i < n; i++) {
			int u = sc.nextInt() - 1;
			int k = sc.nextInt();
			for (int j = 0; j < k; j++) {
				a[u][sc.nextInt() - 1] = true;
			}
		}

		int[] d = new int[n];
		int[] f = new int[n];
		boolean[] used = new boolean[n];
		Deque<Integer> st = new ArrayDeque<Integer>();
		st.push(0);
		int clock = 1;

		while (!st.isEmpty()) {
			int e = st.peek();

			if (!used[e]) {
				used[e] = true;
				d[e] = clock;

				for (int i = n - 1; i >= 0; i--) {
					if (used[i]) {
						continue;
					}
					if (a[e][i]) {
						st.push(i);
					}
				}
			} else {
				st.pop();
				if (f[e] != 0) {
					continue;
				}
				f[e] = clock;
			}

			clock++;
		}

		for (int i = 0; i < n; i++) {
			System.out.printf("%d %d %d\n", i + 1, d[i], f[i]);
		}

		sc.close();
	}
}

