          ajacent[j] = graph.convIdToIndex( Integer.parseInt(vInfo[j+2]) );
        }
        graph.setVertex(id, ajacent);
      }

      graph.vertexSearch();

      graph.dispReport();
    }
    catch (IOException e) {
      System.err.println(e);
    }
  }

  class Graph {

    Vertex[] vertices;
    int time;

    public Graph(int size ) {
      vertices  = new Vertex[size];
      time = 0;
    }

    public void setVertex(int id) {
      vertices[id-1] = new Vertex(id);
    }
    public void setVertex(int id, int[] ajacent) {
      setVertex(id);
      setAjacent(id, ajacent);
    }
    public void setAjacent(int id, int[] ajacent) {
      vertices[id-1].ajacent = ajacent;
    }
    public void vertexSearch() {
      for (Vertex v : vertices) {
        if(v.state == Vertex.WHITE)
          depthFirstSearch(v.index);
      }
    }
    public void dispReport() {
      StringBuilder buf = new StringBuilder();

      for (Vertex v : vertices) {
          buf.append(v.id).append(" ")
             .append(v.findTime).append(" ")
             .append(v.doneTime).append("\n");
      }

      System.out.print(buf);
    }
    public int convIdToIndex(int id) {
      return id-1;
    }

    private void depthFirstSearch(int index) {
      vertices[index].state = Vertex.GRAY;
      vertices[index].findTime = ++time;

      for(int ajcIndex: vertices[index].ajacent) {
        if(vertices[ajcIndex].state == Vertex.WHITE)
          depthFirstSearch(ajcIndex);
      }
      vertices[index].state = Vertex.BLACK;
      vertices[index].doneTime = ++time;
    }

    class Vertex {

      static final int WHITE = 0;
      static final int GRAY  = 1;
      static final int BLACK = 2;
      int id;
      int index;
      int state;
      int[] ajacent;
      int findTime;
      int doneTime;

      public Vertex(int id) {
        this.id = id;
        index = id-1;
        state = WHITE;
      }
    }
  }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

	public static void main(String[] args) throws NumberFormatException, IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(br.readLine());
		int[][] a = new int[n+1][n+2];
		for(int i = 0; i < n; i++) {
			String[] str = br.readLine().split(" ");
			int u = Integer.parseInt(str[0]);
			for(int j = 1; j < str.length; j++){
				a[u][j-1] = Integer.parseInt(str[j]);
			}
		}

		int[] d = new int[n+1];
		int[] f = new int[n+1];
		int t = 0; // time
		int[] st = new int [n*n]; // stack
		int p = 0; // stack pointer

		for(int i = 1; i <= n; i++){
			if(d[i] != 0){
				continue;
			}
			p = 0;
			st[p] = i; // first node

			while(p >= 0){
				int pn = st[p]; // present node
				if(d[pn] == 0){
					t += 1;
					d[pn] = t;
				}

				for(int j = a[pn][0]; j > 0; --j){
					if(d[a[pn][j]] == 0){
						// push the adjacent nodes
						p += 1;
						st[p] = a[pn][j];
					}
				}

				if(st[p] == pn){
					if(f[pn] == 0){
						// write finish time
						t += 1;
						f[pn] = t;
					}
					// pop 
					p -= 1;
				}
			}
		}

		StringBuilder sb = new StringBuilder();
		for(int i = 1; i <= n; i++){
			sb.append(i + " " + d[i] + " " + f[i] + "\n");
		}
		System.out.print(sb);
	}

}

import java.util.LinkedList;
import java.util.List;
import java.util.Scanner;

class Graph {
	private int totalVertex;
	private LinkedList<LinkedList<Integer>> adjList;
	private LinkedList<Boolean> visited;
	private LinkedList<Integer> vertexEnum, preNum, postNum;
	//adjacency list of edges
	public Graph() {
		totalVertex = 0;
		visited = new LinkedList<Boolean>();
		vertexEnum = new LinkedList<Integer>();
		preNum = new LinkedList<Integer>();
		postNum = new LinkedList<Integer>();
	}
	public void loadAdjList() {
		Scanner in = new Scanner(System.in);
		totalVertex = in.nextInt();
		adjList = new LinkedList<LinkedList<Integer>>();
		for(int i = 0; i < totalVertex; i ++) {
			LinkedList<Integer> tmp = new LinkedList<Integer>();
			int idx1 = in.nextInt() - 1;
			int degree = in.nextInt();
			//System.out.println("mark idx1 = " + idx1 + " degree = " + degree);
			for(int j = 0; j < degree; j ++) {
				int idx2 = in.nextInt() - 1;
				tmp.add(idx2);
			}	
			adjList.add(tmp);
		}
		in.close();
	}
	public int nextUnvisited() {
        for(int i = 0; i < visited.size(); i ++)
            if(visited.get(i) == false) return i;
        return -1;
    }
	public void preWalk() {
        visited.clear();
        for(int i = 0; i < totalVertex; i ++) {
        	visited.add(false);
        	preNum.add(0);
        	postNum.add(0);
        }
        vertexEnum.clear();
    }
	public void walk() {
        //method can be "DFS" or "BFS"
        preWalk();
        time = 1;
        int s;
        while((s = nextUnvisited()) != -1) {
        	DFS(s);
        }
    }
	public boolean ifVisited(int v) { return visited.get(v); }
	public void setVisited(int v) { 
        //set vertex v to be visited
        visited.set(v, true); 
        vertexEnum.add(v);
    }
	private int time;
	public void DFS(int v) {
	    preNum.set(v, time);
	    time++;
	    //e.g., preNum.add(v) for preVisit enumeration of the nodes
	    setVisited(v);
	    List<Integer> neighbors = adjList.get(v);
	    for(int i = 0; i < neighbors.size(); i ++) {
	        int v1 = neighbors.get(i);
	        if(ifVisited(v1) == false) DFS(v1); //use recursion!
	    }
	    postNum.set(v, time);
	    time++;
	}
	public void displayEnum() {
        //display enumeration of the vertices
        for(int i = 0; i < totalVertex; i ++) {
            System.out.println((i + 1) + " " + preNum.get(i) + " " + postNum.get(i));
        }
    }
}

public class Main {
	public static void main(String[] args) {
		Graph g = new Graph();
		g.loadAdjList();
		g.walk();
		g.displayEnum();
	}
}

