    static void dfs(int id){
        d[id] = time++;
        for(int i = 0;i < graph[id].length;i++){
            if(fin[graph[id][i]] == 0)
               dfs(graph[id][i]);
        }
        f[id] = time++;
        fin[id] = 1;
    }

