public class Main {
	static int n;
	static int[][] a;
	static int[] d;
	static int[] f;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		Printer pr = new Printer(System.out);

		n = sc.nextInt();
		a = new int[n][n];
		d = new int[n];
		f = new int[n];

		for (int i = 0; i < n; i++) {
			int u = sc.nextInt();
			int k = sc.nextInt();
			for (int j = 0; j < k; j++) {
				a[u - 1][sc.nextInt() - 1] = 1;
			}
		}

		dfs(1, 1);

		for (int i = 0; i < n; i++) {
			pr.print(i + 1);
			pr.print(" ");
			pr.print(d[i]);
			pr.print(" ");
			pr.print(f[i]);
			pr.println("");
		}

		pr.close();
		sc.close();
	}

	private static int dfs(int v, int clock) {
		if (d[v - 1] == 0) {
			d[v - 1] = clock;
			for (int i = 0; i < n; i++) {
				if (a[v - 1][i] != 0) {
					clock = dfs(i + 1, clock + 1);
				}
			}
			clock++;
			f[v - 1] = clock;
			return clock;
		} else {
			if (f[v - 1] == 0) {
				clock++;
				f[v - 1] = clock;
				return clock;
			} else {
				return clock - 1;
			}
		}
	}

	private static class Scanner {
		InputStreamReader isr;
		BufferedReader br;
		StreamTokenizer st;

		Scanner (InputStream in) {
			isr = new InputStreamReader(in);
			br = new BufferedReader(isr);
			st = new StreamTokenizer(br);
		}

		String next() throws RuntimeException  {
			try {
				if (st.nextToken() != StreamTokenizer.TT_WORD) {
				}
			} catch (IOException e) {
				throw new IllegalStateException();
			}

			return st.sval;
		}

		int nextInt() throws RuntimeException {
			try {
				if (st.nextToken() != StreamTokenizer.TT_NUMBER) {
					throw new InputMismatchException();
				}
			} catch (IOException e) {
				throw new IllegalStateException();
			}

			return (int)st.nval;
		}

		void close() {
		}
	}

	private static class Printer {
		PrintStream out;
		StringBuffer strbuf;
		int bufSize;
		final String CR;

		Printer(PrintStream out) {
			this.out = out;
			strbuf = new StringBuffer();
			bufSize = 64 * 1024;
			CR = System.getProperty("line.separator");
		}

		void println(String str) {
			strbuf.append(str);
			strbuf.append(CR);
			checkStringBuffer();
		}

		void print(String str) {
			strbuf.append(str);
			checkStringBuffer();
		}

		void println(int n) {
			strbuf.append(n);
			strbuf.append(CR);
			checkStringBuffer();
		}

		void print(int n) {
			strbuf.append(n);
			checkStringBuffer();
		}

		void print(char c) {
			strbuf.append(c);
			checkStringBuffer();
		}

		void printArray(int[] array) {
			for (int i = 0; i < array.length; i++) {
				checkStringBuffer();
				strbuf.append(array[i]);
				strbuf.append(" ");
			}
			strbuf.delete(strbuf.length() - 1, strbuf.length());
			strbuf.append(CR);
		}

		void close() {
			flashStringBuffer();
		}

		private void flashStringBuffer() {
			if (strbuf.length() > 0) {
				out.print(strbuf);
				strbuf.setLength(0);
			}
		}

		private void checkStringBuffer() {
			if (strbuf.length() > bufSize) {
				out.print(strbuf);
				strbuf.setLength(0);
			}
		}
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Stack;
import java.util.StringTokenizer;

public class Main {

	class Vertex {
		int id;
		int[] vertices;
	}

	public static void main(String[] args) throws IOException {
		new Main().run();
	}

	private void run() throws IOException {

		BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(reader.readLine());

		int discovered[] = new int[n];
		int completed[] = new int[n];
		Vertex[] vertices = new Vertex[n];

		for (int i = 0; i < n; i++) {

			StringTokenizer st = new StringTokenizer(reader.readLine());
			int id = Integer.parseInt(st.nextToken());
			int cnt = Integer.parseInt(st.nextToken());

			vertices[i] = new Vertex();
			vertices[i].id = id;
			vertices[i].vertices = new int[cnt];
			for (int j = 0; j < cnt; j++) {
				vertices[i].vertices[j] = Integer.parseInt(st.nextToken());
			}

			discovered[i] = completed[i] = -1;
		}
		reader.close();

		DFS(n, vertices, completed, discovered);

		for (int i = 0; i < n; i++) {
			Vertex vertex = vertices[i];
			System.out.println(vertex.id + " " + completed[i] + " " + discovered[i]);
		}
	}

	private void DFS(int n, Vertex[] vertices, int[] discovered, int[] completed) {
		int time = 0;
		for (int i = 0; i < n; i++) {
			Vertex vertex = vertices[i];
			Stack<Integer> stack = new Stack<Integer>();
			if (discovered[vertex.id - 1] == -1) {
				stack.push(vertex.id);
			}
			while (!stack.isEmpty()) {
				vertex = vertices[stack.peek()-1];
				if (discovered[vertex.id - 1] == -1) {
					discovered[vertex.id - 1] = ++time;
				}
				int id = findNextVertex(vertices, discovered, vertex);
				if (id != -1) {
					discovered[id - 1] = ++time;
					stack.push(id);
				} else {
					completed[vertex.id - 1] = ++time;
					stack.pop();
				}
			}
		}
	}

	private int findNextVertex(Vertex[] vertices, int[] discovered, Vertex vertex) {
		for (int i = 0; i < vertex.vertices.length; i++) {
			int id = vertex.vertices[i];
			if (discovered[id - 1] == -1) return id;
		}
		return -1;
	}
}

import java.io.BufferedReader;
import java.io.IOException;
