import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Scanner;

public class Main{
	void run() {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int[][] graph = new int[n][n];
		int[][] arr = new int[n][2];
		Deque<Integer> s = new ArrayDeque<>();

		for(int i = 1; i <= n; i++) {
			int u = sc.nextInt();
			int k = sc.nextInt();
			for(int j = 1; j<=k; j++) {
				int index = sc.nextInt();
				graph[u-1][index-1] = 1;
			}
		}

		int count = n;
		int index = 1;
		while(count > 0) {
			for (int i = 0; i < n; i++) {
				if (arr[i][0] == 0) { //startしていないとき
					s.push(i+1);
					arr[i][0] = index;
					index++;
					count--;
					break;
				}
			}
			while(s.size() > 0) {
				int num = s.peek();
				boolean val = false;
				for(int i = 0; i < n; i++) {
					if(graph[num-1][i] == 1 && arr[i][0] == 0) {
						s.push(i+1);
						arr[i][0] = index;
						index++;
						count--;
						val = true;
						break;
					}
				}
				if(!val) {
					int number = s.pop();
					arr[number-1][1] = index;
					index++;
				}
			}
		}

		for(int i = 0; i < n; i++) {
			System.out.println((i+1) + " " + arr[i][0] + " " + arr[i][1]);
		}

		sc.close();
	}

	void debug(Object... o) {
		System.out.println(Arrays.deepToString(o));
	}

	public static void main(String[] args) {
		new Main().run();
	}
}

