    public static void print_answer() {
        for (int i = 0; i < n; i++) {
            System.out.print((i+1) + " ");
            System.out.print(Start[i] + " ");
            System.out.print(Finish[i] + "\n");
        }
    }

    public static void dfs(int u) {
        Stack<Integer> stack = new Stack<Integer>();
        int time = 1;
        int v;

        stack.push(u);
        Start[u] = time++;

        while (!stack.empty()){
            u = stack.peek();
            v = next_vertex(u);

            if (v != 0){
                if (Start[v] == 0){
                    Start[v] = time++;
                    stack.push(v);
                }
            }
            else {
                stack.pop();
                Finish[u] = time++;
            }
        }
    }

    public static int next_vertex(int u) {
        for (int i = 0; i < n; i++) {
            if (Mat[u][i] != 0){
                Mat[u][i] = 0;
                return i;
            }
        }
        return 0;
    }

