			int u = sc.nextInt();
			u--;
			int k = sc.nextInt();

			for (int j = 0; j < k; j++) {
				int v = sc.nextInt();
				v--;
				if (v >= 0) g[u][v] = 1;
			}
		}
		sc.close();

		dfs();

		for (int i = 0; i < n; i++) {
			System.out.print(i + 1);
			System.out.print(" " + d[i] + " " + f[i]);
			System.out.print("\n");
		}
	}

	static void dfs() {
		color = new int[n];
		for (int i = 0; i < n; i++) {
			color[i] = WHITE;
		}
		time = 0;
		d = new int[n];
		f = new int[n];
		for (int i = 0; i < n; i++) {
			if (color[i] == WHITE) dfsVisit(i);
		}
	}

	static void dfsVisit(int i) {
		color[i] = GRAY;
		time++;
		d[i] = time;
		for (int j = 0; j < n; j++) {
			if (color[j] == WHITE && g[i][j] == 1) dfsVisit(j);
		}
		color[i] = BLACK;
		time++;
		f[i] = time;
	}


}

