	private static void solve() {
		int n = sc.nextInt();

		List<Set<Integer>> edges = new ArrayList<>();
		for (int i = 0; i < n; i++) {
			edges.add(new TreeSet<>(Collections.reverseOrder()));

			int u = sc.nextInt() - 1;
			int k = sc.nextInt();
			for (int j = 0; j < k; j++) {
				int v = sc.nextInt() - 1;
				edges.get(u).add(v);
