		}

		boolean[] used = new boolean[n];
		boolean[] used2 = new boolean[n];
		int[] d = new int[n];
		int[] f = new int[n];
		int clock = 1;

		for (int i = 0; i < n; i++) {
			Deque<Integer> st = new ArrayDeque<>();
			st.push(i);
			while (!st.isEmpty()) {
				int e = st.peek();

				if (used[e]) {
					st.pop();
					continue;
				}

				if (used2[e]) {
					st.pop();
					used[e] = true;
					f[e] = clock++;
				} else {
					used2[e] = true;
					d[e] = clock++;
					for (int next : edges.get(e)) {
						if (used[next]) {
							continue;
						}
						if (used2[next]) {
							// ?????????
							continue;
						}

						st.push(next);
					}
				}
			}
		}

		for (int i = 0; i < n; i++) {
			pr.printf("%d %d %d\n", i + 1, d[i], f[i]);
		}
	}

