            for (int j = 0; j < k; j++) {
                int v = sc.nextInt();
                g[u][v] = 1;
            }
        }

        Deque<Integer> deq = new ArrayDeque<Integer>();
        int time = 1;
        deq.push(1);
        find[1] = time;

        while(!deq.isEmpty()) {
            int top = deq.peek();
            int j;
            for (j = 1; j <= n; j++) {
                if (g[top][j] == 1 && find[j] == 0) {
                    deq.push(j);
                    find[j] = ++time;
                    break;
                }
            }
            if (j == n + 1) {
                deq.pop();
                finish[top] = ++time;
            }

            if (deq.isEmpty()) {
                for (int i = 1; i <= n; i++) {
                    if (find[i] == 0) {
                        deq.push(i);
                        find[i] = ++time;
                    }
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            System.out.println(i + " " + find[i] + " " + finish[i]);
        }
    }
}

