public class Main {
    static List<PriorityQueue<Integer>> list;
    static int[] start;
    static int[] finish;
    static int time;

    private static void dfs(int i) {
        if(start[i] > 0) return;
        time++;
        start[i] = time;
        while(!list.get(i).isEmpty()) {
            dfs(list.get(i).poll());
        }
        time++;
        finish[i] = time;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
