public class Main {
	static class DepthFirstSearch {
		public void dfs (InputReader ir) {

			// 頂点の数
			int n = ir.nextInt();
			Graph[] graph  = new Graph[n + 1];

			// 入力
			for (int i = 1; i <= n; i++) {
				graph[i] = new Graph (ir.nextInt());
				int m = ir.nextInt();
				for (int j = 0; j < m; j++) {
					graph[i].u.add(ir.nextInt());
				}
			}

			int k = 1;
			int count = 1;
			graph[1].d = count;

		Outer:		
			while (true) {

				while (!graph[k].u.isEmpty()) {
					int x = graph[k].u.poll();
					if (graph[x].d == null) {
						graph[x].d = ++count;
						graph[x].pre = k;
						k = x;
						continue Outer;
					}
				}

				graph[k].f = ++count; 
				if (k == 1) break;
				k = graph[k].pre;

			}

			StringBuilder sb = new StringBuilder ();
			for (int i = 1; i <= n; i++) {
				sb.append(i).append(" ")
				.append(graph[i].d).append(" ")
				.append(graph[i].f).append("\n");
			}

			System.out.print(sb);

		}
	}

	static class Graph {
		int id;
		Queue<Integer> u = new PriorityQueue<> ();
		Integer d;
		Integer f;
		Integer pre;
		Graph (int i) {
			id = i;
			d = null;
			f = null;
			pre = null;
		}
	}

