public class Main {

    public static void main(String[] args) {
        Main main = new Main();
        main.solv();
    }

    int n = 0;
    private void solv() {
        Scanner input = new Scanner(System.in);
        n = input.nextInt();
        int[][] us = new int[n+1][n+1];
        for (int i = 0; i < n; i++) {
            int u = input.nextInt();
            int k = input.nextInt();
            while (k-- > 0) {
                int v = input.nextInt();
                us[u][v] = 1;
            }
        }
        d = new int[n+1];
        f = new int[n+1];
        int id = 1;
        for (int i = 1; i <= n; i++) {
            boolean flag = true;
            for (int j = 1; j <= n; j++) {
                if (us[j][i] != 0) {
                    flag = false;
                    break;
                }
            }
            if (flag) {
                id = i;
                break;
            }
        }
        calc(us, id, 0);

        for (int i = 1; i <= n; i++) {
            System.out.println(String.format("%d %d %d", i, d[i], f[i]));
        }
    }
    int[] d;
    int[] f;
    int calc(int[][] us, int id, int t ) {
        if (d[id] != 0) return t;
        d[id] = ++t;
        for (int i = 1; i <= n; i++) {
            if (us[id][i] != 0) {
                t = calc(us, i, t);
            }
        }
        f[id] = ++t;
        return t;
    }

    void swap(int[] A, int x, int y) {
        int temp = A[x];
        A[x] = A[y];

        A[y] = temp;
    }

}

