class Main {
    static int n,time = 1;

    static int[][] graph;

    static int[] d,f,fin;

    static void dfs(int id){
        d[id] = time++;
        fin[id] = 1;
        for(int i = 0;i < graph[id].length;i++){
            if(fin[graph[id][i]] == 0){
                dfs(graph[id][i]);
            }
        }
        f[id] = time++;
    }

    public static void main(String args[]) {
        Scanner input = new Scanner(System.in);
        n = input.nextInt();

        graph = new int[n][];
        d = new int[n];
