import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;

class Main{
	public static void main(String[] args)throws NumberFormatException, IOException{
	    InputStreamReader input = new InputStreamReader (System. in);
	    BufferedReader buffer = new BufferedReader(input);
	    String read = buffer.readLine();
	    int amount = Integer.parseInt(read);
	    Deque<Integer> stack = new ArrayDeque<Integer>();
	    stack.add(0);
	    int[][] scanInt = new int[amount][100];
	    for(int i=0; i<amount; i++){
	    	read = buffer.readLine();
	    	String[] scan = read.split(" ");
	    	for(int j=0; j<scan.length; j++){
	    		scanInt[i][j] = Integer.parseInt(scan[j]);
	    	}
	    }
	    int[] foundTime = new int[amount];
	    int[] compTime = new int[amount];
	    int time = 1;

	    while(true){
	    	int process = stack.peek();
	    	boolean branchIsRemain = false;
	    	if(foundTime[process] == 0){
	    		foundTime[process] = time;
	    	}
	    	compTime[process]= time+1;

	    	for(int i=2; i<2+scanInt[process][1]; i++){

	    		if(foundTime[-1 + scanInt[process][i]] == 0){
	    			stack.addFirst(-1 + scanInt[process][i]);
	    			branchIsRemain = true;
	    			break;
	    		}
	    	}
	    	if(branchIsRemain == false){
	    		stack.pop();
	    	}
	    	if(stack.isEmpty()){
	    		break;
	    	}

	    	time++;
	    }
	    for (int i=0; i<amount; i++){
	    	System.out.println((i+1)+" "+foundTime[i]+" "+compTime[i]);
	    }

	}
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Scanner;

public class Main{
	static int n;
	static int[][]M;	// 隣接行列
	static int[]color;	// 頂点の訪問状況
	static int[]d;		// d[v]: vを最初に訪問した発見時刻
	static int[]f;		// f[v]: vの隣接リストを調べ終えた完了時刻
	static int tt = 0;		// 時刻
	static int nt[];	// nt[u]: uに隣接する頂点
	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		n = scan.nextInt();
		M = new int[n][n];
		color = new int[n];
		d = new int[n];
		f = new int[n];
		nt = new int[n];
		for(int i = 0; i < n; i++) {
			int u = scan.nextInt() - 1;
			int k = scan.nextInt();
			for(int j = 0; j < k; j++) {
				M[u][scan.nextInt() - 1] = 1;
			}
		}
		scan.close();

		dfs();
	}
	// uに隣接するvを番号順に取得
	static int next(int u) {
		for(int v = nt[u]; v < n; v++) {
			nt[u] = v + 1;
			if(M[u][v] == 1) return v;
		}
		return -1;
	}
	// スタックを用いた深さ優先探索
	static void dfsVisit(int r) {
		Arrays.fill(nt, 0);
		Deque<Integer> stack = new ArrayDeque<Integer>();
		stack.push(r);
		color[r] = 1;
		d[r] = ++tt;

		while(!stack.isEmpty()) {
			int u = stack.peek();
			int v = next(u);
			if(v != -1) {
				if(color[v] == 0) {
					color[v] = 1;
					d[v] = ++tt;
					stack.push(v);
				}
			}else {
				stack.pop();
				color[u] = 2;
				f[u] = ++tt;
			}
		}
	}
	static void dfs() {
		// 未訪問のuを始点として深さ優先探索
		for(int u = 0; u < n; u++) {
			if(color[u] == 0) {
				dfsVisit(u);
			}
		}
		for(int i = 0; i < n; i++) {
			int u = i + 1;
			System.out.println(u + " " + d[i] + " " + f[i]);
		}
	}
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

	// a graph structure based on adjacent graph
	public static class graph{
		public int v_num; // the number of vertices
		public List<List<Integer>> adj_table;

		public graph(int _v_num) {
			v_num = _v_num;
			adj_table = new ArrayList<List<Integer>>();
			for(int i = 0; i < v_num; i++) {
				adj_table.add(new ArrayList<Integer>());
			}
		}


		//src and dst is always 1-kara
		public void insert_edge(int src, int dst) {
			adj_table.get(src-1).add(dst);
		}

		// 1-kara
		public List<Integer> get_adj_nodes(int i){
			return adj_table.get(i-1); 
		}
	}

	public static int clock = 0;


	public static void _dfs(graph g, int current, int[] b, int []f) {
		clock++;
		b[current] = clock;
		List<Integer> adj_list = g.get_adj_nodes(current);
		for(int i = 0; i < adj_list.size(); i++) {
			if(b[adj_list.get(i)] == 0)
				_dfs(g, adj_list.get(i), b, f);
		}
		clock++;
		f[current] = clock;

	}

	public static void dfs(graph g) {
		int [] b = new int[g.v_num+1];
		int [] f = new int[g.v_num+1];

		_dfs(g, 1, b, f);
		for(int i = 1; i <= g.v_num; i++) {
			System.out.println(i + " "+ b[i]+" "+f[i]);
		}
	}

	public static void main(String [] args) {
		Scanner cin = new Scanner(System.in);
		int n = cin.nextInt();
		graph g = new graph(n);

		int src_id,  list_len; 
		for(int i = 0; i< n; i++) {
			src_id = cin.nextInt();
			list_len = cin.nextInt();
			while(list_len > 0) {
				g.insert_edge(src_id, cin.nextInt());
				list_len--;
			}
		}

		dfs(g);


		cin.close();


	}
}

