    private static int dfs(int v, int t, int[][] a, int[][] g) {
        if(0 < a[v][0])return t-1;
        a[v][0] = t;
        for(int nex : g[v]){
            t = dfs(nex, t+1, a, g);
        }
        a[v][1] = ++t;
        return t;
    }

}

