			adjList.add(tmp);
		}
		in.close();
		return adjList;
	}

	public void recurse(LinkedList<LinkedList<Integer>> G, int v) {
		if(!explore[v]) {
			explore[v] = true;
			count++;
			firstDisc[v] = count;
			for(int e : G.get(v-1)) {
				recurse(G, e);
			}
			count++;
			endTime[v] = count;
		}

	}

	void print() {
		for(int i = 1; i <= totalVertex; i++) {
			System.out.println(i +" "+ firstDisc[i] + " " + endTime[i]) ;
		}
	}
}
