public class Main {
	public static void main(String args[]) {
		Scanner scr = new Scanner(System.in);
		int dotcount =Integer.parseInt(scr.nextLine());
		dots = new int[dotcount][];
		for(int i=0; i<dotcount; i++){
			String[] str = scr.nextLine().split(" ", 0);
			dots[i] = new int[Integer.parseInt(str[1])];
			for(int j=2; j<str.length; j++){
				dots[i][j-2] = Integer.parseInt(str[j])-1;
			}
		}
		step=1;
		//index=0;
		start = new int[dotcount];
		finish = new int[dotcount];
		visited = new boolean[dotcount];
		for(int i=0; i<dotcount; i++){
			visited[i] = false;
		}
		Visit(0);
		for(int i=0; i<dotcount; i++){
			System.out.println(String.valueOf(i+1) +" "+ start[i] +" "+ finish[i]);
		}
		scr.close();
	}
	static int[][] dots;
	static int step;
	//static int index;
	static boolean[] visited;
	static int[] start;
	static int[] finish;
	static void Visit(int i){
		visited[i] = true;
		start[i] = step;
		step++;
		//System.out.println(step);
		for(int j=0; j < dots[i].length; j++){
			if(!visited[dots[i][j]]) Visit(dots[i][j]);
		}
		finish[i] = step;
		step++;
	}
}

import java.util.Scanner;
import java.util.HashMap;
import java.util.Stack;
import java.util.HashSet;
public class Main {

  int n;
  HashMap<Integer, Integer[]> graph;
  HashSet<Integer> visited = new HashSet<Integer>();
  int timestamp;
  int[] d;
  int[] f;

  public Main(HashMap<Integer, Integer[]> graph, int n) {
    this.n = n;
    this.graph = graph;
    this.timestamp = 1;
    this.d = new int[n];
    this.f = new int[n];
  }

  public void dfs() {
    for (int i = 1; i <= this.n; i++) {
      if (!this.visited.contains(i))
        dfsHelper(i);
    }
  }

  public void dfsHelper(Integer elem) {
    visited.add(elem);
    this.d[elem-1] = this.timestamp;
    this.timestamp++;
    for (Integer neighbor : this.graph.get(elem)) {
      if (!this.visited.contains(neighbor)) {
        dfsHelper(neighbor);
      }
    }
    this.f[elem-1] = this.timestamp;
    this.timestamp++;
  }

  public void displayResults() {
    for (int i = 0; i < n; i++) {
      System.out.println((i+1) + " " + this.d[i] + " " + this.f[i]);
    }
  }

  public static void main(String[] args) {
    Scanner s = new Scanner(System.in);
    int n = s.nextInt();
    HashMap<Integer, Integer[]> graph = new HashMap<Integer, Integer[]>();
    for (int i = 0; i < n; i++) {
      int id = s.nextInt();
      int degree = s.nextInt();
      Integer[] edges = new Integer[degree];
      for (int j = 0; j < degree; j++) {
        int val = s.nextInt();
        edges[j] = val;
      }
      graph.put(id, edges);
    }
    s.close();
    Main main = new Main(graph, n);
    main.dfs();
    main.displayResults();
  }
}

