class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble() { return Double.parseDouble(next());}
}

import java.io.File;
import java.io.IOException;
import java.util.Arrays;
import java.util.Scanner;
import java.util.Stack;

public class Main {

	public static final int N = 100;
	public static final int WHITE = 0;
	public static final int GRAY = 1;
	public static final int BLACK = 2;

	static int n;
	static int tt;

	// グラフを示す二次元行列
	static int[][] M = new int[N][N];
	static int[] color = new int[N], d = new int[N], f = new int[N], nt = new int[N];

	public static void main(String[] args) throws IOException {

		int u,k,v;
		Scanner sc = new Scanner(System.in);
		n = sc.nextInt();

		for (int i = 0; i < n; i++) {
			u = sc.nextInt();
			k = sc.nextInt();
			u--;
			for (int j = 0; j < k; j++) {
				v = sc.nextInt();
				v--;
				M[u][v] = 1;
			}
		}
		dfs();
	}

	// uに隣接するvを番号順に取得
	private static int next (int u) {
		for (int v = nt[u]; v < n; v++) {
			nt[u] = v + 1;
			if (M[u][v] == 1) {
				return v;
			}
		}
		return -1;
	}

	// スタックを用いた深さ優先探索
	private static void dfsVisit(int r) {

		Stack<Integer> S = new Stack<Integer>();
		S.push(r);
		color[r] = GRAY;
		d[r] = ++tt;

		while (!S.empty()) {
			int u = S.peek();
			int v = next(u);
			if (v != -1) {
				if (color[v] == WHITE) {
					color[v] = GRAY;
					d[v] = ++tt;
					S.push(v);
				}
			} else {
				S.pop();
				color[u] = BLACK;
				f[u] = ++tt;
			}
		}
	}

	private static void dfs() {
		Arrays.fill(color, WHITE);

		// 未訪問のuを始点として深さ優先探索
		for (int u = 0; u < n; u++) {
			if (color[u] == WHITE) dfsVisit(u);
		}
		for (int i = 0; i < n; i++) {
			System.out.println(i+1 +" "+ d[i] + " " + f[i]);
		}
	}


}

import java.util.ArrayList;
