	static int dfs(int now,int t) {
		if (f[now] != 0)
			return t;
		d[now] = t++;
		for (int i=0; i<n; i++) {
			if (adj[now][i] == 1 && i != now) {
				t = dfs(i,t);
			}
		}
		f[now] = t++;
		return t;
	}
}

