	private void putTime(int id) {
		time++;

		flag[id] = false;
		D[id] = time;

		for(Integer i : L[id].child) {
			if(flag[i]) {
				flag[i] = false;
				putTime(i);
			}
		}
		time++;
		F[id] = time;
	}
