		for(int i = 0; i < totalVertex; i++) {
			for(int x = 0; x < totalVertex; x++) {
				if(x != totalVertex - 1) System.out.print(graph[i][x] + " ");
					else System.out.print(graph[i][x]);
			}
			System.out.println();
		}
	}
	public void dfs(int u) {
		if (d[u] > 0 || f[u] > 0)
			return;

		d[u] = ++time;
		for (int i = 0; i < totalVertex; i++)
			if (g[u][i])
				dfs(i);
		f[u] = ++time;
	}
}
