import IntStack.EmptyIntStackException;
import IntStack.OverflowIntStackException;
public class Ex3_2 {
	public class IntStack {
		private int max;
		private int ptr;
		private int[] stk;

		public class EmptyIntStackException extends RuntimeException{
			public EmptyIntStackException(){ }
		}
		public class OverflowIntStackException extends RuntimeException{
			public OverflowIntStackException(){ }
		}
		public IntStack(int capacity){
			ptr=0;
			max=capacity;
			try{
				stk=new int[max];

			}catch(OutOfMemoryError e){
				max=0;
			}
		}
		public int push(int x) throws OverflowIntStackException{
			if(ptr>=max){
				throw new OverflowIntStackException();
			}
			return stk[ptr++]=x;
		}

		public int pop() throws EmptyIntStackException{
			if(ptr<=0){
				throw new EmptyIntStackException();
			}
			return stk[--ptr];
		}

		public int peek() throws EmptyIntStackException{
			if(ptr<=0){
				throw new EmptyIntStackException();
			}
			return stk[ptr-1];
		}

		public int indexOf(int x){
			for(int i=ptr-1;i>=0;i--){
				if(stk[i]==x)
					return i;

			}
			return -1;
		}

		public void clear(){
			ptr=0;
		}

		public int capacity(){
			return max;
		}
		public int size(){
			return ptr;
		}

		public boolean isEmpty(){
			return ptr<=0;
		}

		public boolean isFull(){
			return ptr>=max;
		}

		public void dump(){
			if(ptr<=0)
				System.out.println("Stack is empty");
			else{
				for(int i=0;i<ptr;i++){
					System.out.print(stk[i]+" ");
				}
				System.out.println();
			}

		}

	}


	public static void main(String args[]){

		Scanner stdin = new Scanner(System.in);

		int count=1;
		int[] fs,es,before;
		int[][] next;
		int n=stdin.nextInt();
		fs=new int[n+1];es=new int[n+1];before=new int[n+1];
		next=new int[n+1][];
		IntStack stack=new IntStack(n);


		fs[0]=es[0]=before[0]=-1;

		for(int i=1;i<=n;i++){
			stdin.nextInt();
			int size=stdin.nextInt();

			if(size==0) next[i]=null;
			else{
				next[i] =new int[size];
				for(int j=0;j<size;j++){
					next[i][j]=stdin.nextInt();
				}
			}
			fs[i]=es[i]=before[i]=0;
		}


		function(1,fs,es,next,count,stack);
		System.out.println(es[3]);
		print(fs,es);



	}

	public static boolean isEmp(int id,int[] a,int[] es){
		if(a==null) return true;
		for(int i=0;i<a.length;i++){
			if(es[a[i]]==0) return false;
		}
		return true;
	}

	public static void function(int id,int[] fs,int[] es,int[][] next,int count,IntStack stack){

		System.out.println(id);
		if(id==1&&isEmp(1,next[1],es)){
			es[1]=++count;
