    static int[] Start = new int[N];
    static int[] Finish = new int[N];
    static int[] Next = new int[N];
    static int[] Color = new int[N];

    static int n;
    static int time = 1;



    public static void main(String[] argss){

        graph_input();
        for (int i = 0; i < n; i++) {
            if (Color[i] == 0)
                dfs(i);
        }
        print_answer();
