    public static void print_answer() {
        for (int i = 0; i < n; i++) {
            System.out.print((i+1) + " ");
            System.out.print(Start[i] + " ");
            System.out.print(Finish[i] + "\n");
        }
    }

    public static void dfs(int u) {
        for (int i = 0; i < n; i++) {
            Next[i] = 0;
        }
        Stack<Integer> stack = new Stack<>();
        int v;

        stack.push(u);
        Start[u] = time++;
        Color[u] = 1;

        while (!stack.empty()){
            u = stack.peek();
            v = next_vertex(u);

            if (v != -1){
                if (Color[v] == 0){
                    Color[v] = 1;
                    Start[v] = time++;
                    stack.push(v);
                }
            }
            else {
                Color[u] = 2;
                stack.pop();
                Finish[u] = time++;
            }
        }
    }

    public static int next_vertex(int u) {
        for (int v = Next[u]; v < n; v++) {
            Next[u] = v + 1;
            if (Mat[u][v] == 1)
                return v;
        }
        return -1;
    }

