		for (int i = 0; i < n; i++) {
			u = sc.nextInt();
			k = sc.nextInt();
			u--;
			for (int j = 0; j < k; j++) {
				v = sc.nextInt();
				v--;
				M[u][v] = 1;
			}
		}
		dfs();
	}

	// uに隣接するvを番号順に取得
	private static int next (int u) {
		for (int v = nt[u]; v < n; v++) {
			nt[u] = v + 1;
			if (M[u][v] == 1) {
				return v;
			}
		}
		return -1;
	}

	// スタックを用いた深さ優先探索
	private static void dfsVisit(int r) {

		Stack<Integer> S = new Stack<Integer>();
		S.push(r);
		color[r] = GRAY;
		d[r] = ++tt;

		while (!S.empty()) {
			int u = S.peek();
			int v = next(u);
			if (v != -1) {
				if (color[v] == WHITE) {
					color[v] = GRAY;
					d[v] = ++tt;
					S.push(v);
				}
			} else {
				S.pop();
				color[u] = BLACK;
				f[u] = ++tt;
			}
		}
	}

	private static void dfs() {
		Arrays.fill(color, WHITE);

		// 未訪問のuを始点として深さ優先探索
		for (int u = 0; u < n; u++) {
			if (color[u] == WHITE) dfsVisit(u);
		}
		for (int i = 0; i < n; i++) {
			System.out.println(i+1 +" "+ d[i] + " " + f[i]);
		}
	}


}

