        for(int j=0; j<degree; j++) {
          ajacent[j] = graph.convIdToIndex( Integer.parseInt(vInfo[j+2]) );
        }
        graph.setVertex(id, ajacent);
      }

      graph.vertexSearch();

      graph.dispReport();
    }
    catch (IOException e) {
      System.err.println(e);
    }
  }

  class Graph {

    Vertex[] vertices;
    int time;

    public Graph(int size ) {
      vertices  = new Vertex[size];
      time = 0;
    }

    public void setVertex(int id) {
      vertices[convIdToIndex(id)] = new Vertex(id);
    }
    public void setVertex(int id, int[] ajacent) {
      setVertex(id);
      setAjacent(id, ajacent);
    }
    public void setAjacent(int id, int[] ajacent) {
      vertices[convIdToIndex(id)].ajacent = ajacent;
    }
    public void vertexSearch() {
      for (Vertex v : vertices) {
        if(v.state == Vertex.WHITE)
          depthFirstSearch(v.index);
      }
    }
    public void dispReport() {
      StringBuilder buf = new StringBuilder();

      for (Vertex v : vertices) {
          buf.append(v.id).append(" ")
             .append(v.findTime).append(" ")
             .append(v.doneTime).append("\n");
      }

      System.out.print(buf);
    }
    public int convIdToIndex(int id) {
      return id-1;
    }

    private void depthFirstSearch(int index) {
      vertices[index].state = Vertex.GRAY;
      vertices[index].findTime = ++time;

      for(int ajcIndex: vertices[index].ajacent) {
        if(vertices[ajcIndex].state == Vertex.WHITE)
          depthFirstSearch(ajcIndex);
      }
      vertices[index].state = Vertex.BLACK;
      vertices[index].doneTime = ++time;
    }

    class Vertex {

      static final int WHITE = 0;
      static final int GRAY  = 1;
      static final int BLACK = 2;
      int id;
      int index;
      int state;
      int[] ajacent;
      int findTime;
      int doneTime;

      public Vertex(int id) {
        this.id = id;
        index = id-1;
        state = WHITE;
      }
    }
  }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;

class Graph {
    static int NIL = -1;
    static int WHITE = 0;
    static int GRAY = 1;
    static int BLACK = 2;

    int n;
    int[][] G;
    int[] d;
    int[] f;

    Graph(int[][] g) {
        n = g.length;
        G = g;
        d = new int[n];
        f = new int[n];
    }

    private int depthFirstVisit(int u, int[] state, int time) {
        Deque<Integer> stack = new ArrayDeque<>();

        stack.addFirst(u);
        state[u] = GRAY;
        d[u] = ++time;

        while (!stack.isEmpty()) {
            u = stack.peekFirst();
            int v = next(u, state);
            if (v != NIL) {
                state[v] = GRAY;
                d[v] = ++time;
                stack.addFirst(v);
            } else {
                stack.removeFirst();
                state[u] = BLACK;
                f[u] = ++time;
            }
        }

        return time;
    }

    void depthFirstSearch() {
        int[] state = new int[n];
        int time = 0;
        for (int i = 0; i < n; i++) {
            if (state[i] == WHITE)
                time = depthFirstVisit(i, state, time);
        }
    }

    private int recurciveDepthFirstVisit(int u, int[] state, int time) {
        state[u] = GRAY;
        d[u] = ++time;
        for (int i = 0; i < n; i++) {
            if (G[u][i] == 1 && state[i] == WHITE)
                time = recurciveDepthFirstVisit(i, state, time);
        }
        state[u] = BLACK;
        f[u] = ++time;
        return time;
    }

    void recursiveDepthFirstSearch() {
        int[] state = new int[n];
        int time = 0;
        for (int i = 0; i < n; i++) {
            if (state[i] == WHITE)
                time = recurciveDepthFirstVisit(i, state, time);
        }
    }

    private int next(int u, int[] state) {
        for (int i = 0; i < n; i++) {
            if (G[u][i] == 1 && state[i] == WHITE)
                return i;
        }
        return NIL;
    }

    void print() {
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            out.append(i + 1).append(" ").append(d[i]).append(" ").append(f[i]).append("\n");
        }
        System.out.print(out);
    }
}

