class DFS {
    int n;
    int[][] graph;
    int[] d;
    int[] f;
    int timestamp;
    DFS (int n, int[][] graph) {
	this.n = n;
	this.graph = graph;
	d = new int[n+1];
	f = new int[n+1];
	timestamp = 1;
    }
    void dfs (int id) {
	if (d[id] > 0) {
	    return;
	}
	d[id] = timestamp++;
	for (int next = 1; next <=n; next++) {
	    if (graph[id][next] == 1) {
		dfs(next);
	    }
	}
	f[id] = timestamp++;
    }
    void printResult () {
	StringBuilder sb = new StringBuilder();
	for (int i = 1; i < n+1; i++) {
	    sb.append(i + " " + d[i] + " " + f[i] + "\n");
	}
	System.out.print(sb);
    }
}

