			}
		}

		int[] d = new int[n];
		int[] f = new int[n];
		int clock = 1;

		int[] used = new int[n];  // 0:White, 1:Gray, 2:Black
		for (int i = 0; i < n; i++) {
			if (used[i] != 0) {
				continue;
			}

			Deque<Integer> st = new ArrayDeque<>();
			st.push(i);
			while (!st.isEmpty()) {
				int e = st.peek();

				if (used[e] == 2) {
					st.pop();
				} else if (used[e] == 1) {
					used[e] = 2;
					f[e] = clock++;
					st.pop();
				} else {
					used[e] = 1;
					d[e] = clock++;
					for (int next : edges.get(e)) {
						if (used[next] == 2) {
							// 前進辺または横断辺
							continue;
						} else if (used[next] == 1) {
							// 後退辺
							continue;
						}

						st.push(next);
					}
				}
			}
		}

		for (int i = 0; i < n; i++) {
			pr.printf("%d %d %d\n", i + 1, d[i], f[i]);
		}
	}

