class Main{

    int time = 0;
    // 深さ優先探索
    void dfs(HashMap<Integer, List<Integer>> graph, int v, boolean[] seen, int[] d, int[] f){
        seen[v] = true;
        d[v] = ++time;
        if(!graph.containsKey(v)){
            f[v] = ++time;
            return;
        }
        List<Integer> todo = graph.get(v);

        for(int next : todo){
            if(seen[next]){
                continue;
            }
            dfs(graph, next, seen, d, f);
        }

        f[v] = ++time;

    }

    void solve(){
        int N = ni();

        HashMap<Integer, List<Integer>> graph = new HashMap<>();
        List<Integer> list;
        boolean[] seen = new boolean[N + 1];
        int[] d = new int[N + 1];
        int[] f = new int[N + 1];
        for(int i = 1; i <= N; i++){
            int n = ni();
            int k = ni();
            if(k == 0) continue;
            list = new ArrayList<>();
            for(int j = 0; j < k; j++){
                int v = ni();
                list.add(v);
            }
            graph.put(i, list);
        }

        for(int i = 1; i <= N; i++){
            if(seen[i]) continue;
            dfs(graph, i, seen, d, f);
        }      

        for(int i = 1; i <= N; i++){
            System.out.println(i + " " + d[i] + " " + f[i]);
        }
    }

