class Graph implements Iterable<Graph.Vertex> {

	private ArrayList<Vertex> vertexs;
	private int[] indexes;

	public Graph(int n) {
		vertexs = new ArrayList<Vertex>();
		indexes = new int[n + 1];
	}

	public void add(String info) {
		int id;
		int[] edge;
		String[] _edge;

		StringTokenizer st = new StringTokenizer(info);
		id = Integer.parseInt(st.nextToken());
		_edge = new String[Integer.parseInt(st.nextToken())];
		edge = new int[_edge.length];
		for (int i = 0; i < _edge.length; i++) {
			_edge[i] = st.nextToken();
		}
		//Arrays.sort(_edge);
		for (int i = 0; i < edge.length; i++) {
			edge[i] = Integer.parseInt(_edge[i]);
		}
		vertexs.add(new Vertex(id, edge));
		indexes[id] = vertexs.size() - 1;
	}

	public void sort() {
		Collections.sort(vertexs);
		for (int i = 0; i < vertexs.size(); i++) {
			indexes[vertexs.get(i).id] = i;
		}
	}

	public Vertex get(int id) {
		return vertexs.get(indexes[id]);
	}

	public void dfs(int t) {
		for (Vertex v : vertexs) {
			t = v.dfs(t);
		}
	}

	@Override
	public Iterator<Graph.Vertex> iterator() {
		return null;
	}

	public Integer[] dict() {
		Integer[] d = new Integer[indexes.length];
		for (int i = 0; i < d.length; i++) {
			d[i] = indexes[i];
		}
		Arrays.sort(d, new Comparator<Integer>() {

			@Override
			public int compare(Integer o1, Integer o2) {
				String s1, s2;
				s1 = o1.toString();
				s2 = o2.toString();
				return s1.compareTo(s2);
			}
		});
		return d;
	}

	class Vertex implements Comparable<Vertex> {
		private int id, d, f;
		private int[] edge;

		private Vertex(int id, int[] edge) {
			this.id = id;
			d = 0;
			f = 0;
			this.edge = edge;
		}

		private int dfs(int t) {
			if (d == 0) {
				d = ++t;
				for (int i = 0; i < edge.length; i++) {
					t = get(edge[i]).dfs(t);
				}
				f = ++t;
			}
			return t;
		}

		public String toString() {
			return String.format("%d %d %d\n", id, d, f);
		}

		@Override
		public int compareTo(Vertex o) {
			String s1, s2;
			s1 = Integer.valueOf(id).toString();
			s2 = Integer.valueOf(o.id).toString();
			return s1.compareTo(s2);
		}
	}
}

import java.util.*;
import java.io.*;

class Main{
  public static StringBuilder bl = new StringBuilder();
  public static final int WHITE = 0;
  public static final int BLACK = 2;
  public static final int GRAY = 1;
  static int color[];
  static int time;
  static int M[][];
  static int nt[];
  static  int d[]; // 行きの時間 discover;
  static  int f[]; // 帰りの時間 finishing;
  static int n;
  static Deque<Integer> stack = new ArrayDeque<Integer>();

  public static void main(String args[]){
    Scanner sc = new Scanner(System.in);
    n = sc.nextInt();
    M = new int[n][n];
    color = new int[n];
    d = new int[n];
    f = new int[n];
    nt = new int[n];
    int u, k, v;

    for(int i = 0; i<n; i++){
      for(int j = 0; j<n; j++){
        M[i][j] = 0;
      }
    }

    for(int i = 0; i<n; i++){
      u = sc.nextInt();
      k = sc.nextInt();
      for(int j = 0; j<k; j++){
        v =sc.nextInt();
        M[u-1][v-1] = 1;
      }
    }
    dfs_init();
    System.out.print(bl);
  }

  static void dfs_init(){
    for(int i =0; i<n; i++){
      color[i] = WHITE;
      nt[i] = 0;
    }
    time = 1;
    //  //dfs(0);

    for(int u = 0; u<n; u++){
      if(color[u] == WHITE)dfs(u);
    }

    for(int i = 0; i<n; i++){
      bl.append(i+1).append(" ").append(d[i]).append(" ").append(f[i]).append("\n");
      // System.out.println((i+1)+" "+d[i]+" "+f[i]);
    }

  }

  static void dfs(int r){

    for(int i =0; i<n; i++){
      nt[i] = 0;
    }
    stack.offerFirst(r);
    color[r] = GRAY;
    d[r] = time;

    while(stack.peek()!=null){
      int u = stack.getFirst();
      int v = next(u);
      if(v != -1){
        if(color[v] == WHITE){
          color[v] = GRAY;
          d[v] = ++time;
          stack.offerFirst(v);
        }
      }else{
        stack.removeFirst();
        color[u] = BLACK;
        f[u] = ++time;
      }
    }
  }

  //ノードuに隣接しているノードを返す 隣接行列で表現されているのでuの行を探索して1があればその列の添字を返す。
  static int next(int u){
    for(int v = nt[u]; v <n; v++){
      nt[u] = v+1;
      if(M[u][v] == 1) return v;
    }
    return -1;
  }

}

