	static class Edge implements Comparable<Edge>{
		int to;
		long v;
		public Edge(int to,long v) {
			this.to=to;
			this.v=v;
		}
		@Override
    	public boolean equals(Object obj) {
    		if(obj instanceof Edge) {
    			Edge other = (Edge) obj;
    			return other.to==this.to && other.v==this.v;
    		}
    		return false;
    	}//同値の定義
    	@Override
    	public int hashCode() {
    		return Objects.hash(this.to,this.v);
    	}
    	@Override
		  public int compareTo( Edge p2 ){
			 if (this.to>p2.to) {
				return 1;
			}
			 else if (this.to<p2.to) {
				return -1;
			}
			 else {
				return 0;
			}
		  }
	} 
	static class graph{
		ArrayList<Edge>[] list;
		int size;
		long INF=Long.MAX_VALUE/2;
		int[] color;
		@SuppressWarnings("unchecked")
		public graph(int n) {
			size = n;
			list = new ArrayList[n];
			color =new int[n];
			for(int i=0;i<n;i++){
				list[i] = new ArrayList<Edge>();
			}
		}
		void addEdge(int from,int to,long w) {
			list[from].add(new Edge(to,w));
		}
		void Treedfs(int v, int p ) {
			for (Edge nv : list[v]) {
				if (nv.to == p) continue;  
				//処理書く
				Treedfs(nv.to, v);
			}
		}
		void dfs(int v) {
			df[v][0]=time;
			for (Edge nv: list[v]) {
				if (df[nv.to][0]!=0) {
					continue;
				}
				time++;
				dfs(nv.to);
			}
			time++;
			df[v][1]=time;
		}
		boolean nibugraph(int s,int colors) {
			color[s]=colors;
			for (Edge nv: list[s]) {
				if (color[nv.to]==colors) {
					return false;
				}
				if (color[nv.to]==0&&!nibugraph(nv.to, -colors)) {
					return false;
				}
			}
			return true;
		}
		long[] bfs(int s) {
			long[] l=new long[size];
			for (int i = 0; i < l.length; i++) {
				l[i]=-1;
			}
			l[s]=0;
			ArrayDeque<Integer> qArrayDeque=new ArrayDeque<Integer>();
			qArrayDeque.add(s);
			while (!qArrayDeque.isEmpty()) {
				int v=qArrayDeque.poll();
				for (Edge nv: list[v]) {
					if (l[nv.to]==-1) {
						l[nv.to]=l[v]+nv.v;
						qArrayDeque.add(nv.to);
					}
				}
			}
			return l;
		}
		long[] bellman_ford(int sv,int gv) {
			long[] d=new long[size];
			Arrays.fill(d, INF);
			d[sv]=0;
			for (int i = 0; i < d.length; i++) {
				for (int j = 0; j < d.length; j++) {
					if (d[j]==INF) {
						continue;
					}
					for (Edge edge :list[j]) {
						if (d[edge.to]>d[j]+edge.v) {
							d[edge.to]=d[j]+edge.v;
						}
					}
				}
			}
			long ans=d[d.length-1];
			for (int i = 0; i < d.length; i++) {
				for (int j = 0; j < d.length; j++) {
					if (d[j]==INF) {
						continue;
					}
					for (Edge edge :list[j]) {
						if (d[edge.to]>d[j]+edge.v) {
							d[edge.to]=-INF;
						}
					}
				}
			}
			if (ans!=d[gv]) {
				return null;
			}//sv~gv間に負の閉路があれば検出
			return d;
		}
		long[] dijkstra(int s){
	        long[] L = new long[size];
	        for(int i=0;i<size;i++){
	            L[i] = -1;
	        }
	        int[] visited = new int[size];
	        L[s] = 0;
	        PriorityQueue<Edge> Q = new PriorityQueue<Edge>();
	        Q.add(new Edge(s,0L));//Edgeに最短距離候補を持たせる
	        while(!Q.isEmpty()){
	            Edge C = Q.poll();
	            if(visited[C.to]==0){
	                L[C.to] = C.v;
	                visited[C.to] = 1;
	                for(Edge D:list[C.to]){
	                    Q.add(new Edge(D.to,L[C.to]+D.v));
	                }
	            }
	        }
	        return L;
	    }
	    int[] topological(){
			int[] indegree = new int[size];//入次数
	        for (int i = 0; i < size; i++) {
	        	for (Edge edge: list[i]) {
					indegree[edge.to]++;
				}
	        }
	        ArrayDeque<Integer> q = new ArrayDeque<Integer>();
	        int[] count=new int[size];
	        for (int i = 0; i < size; i++) {
	            if (indegree[i] == 0) {
	                q.addLast(i);
	            }
	        }
	        int cnt = 0;
	        List<Integer> res = new ArrayList<Integer>();
	        while (!q.isEmpty()) {
	            // 接続先の頂点を探索開始
	            int u = q.removeLast();
	            res.add(u);
	            for (Edge edge : list[u]) {
	                indegree[edge.to]--;
	                count[edge.to]=Math.max(count[u]+1,count[edge.to]);
	                if (indegree[edge.to] == 0) {
	                    q.addFirst(edge.to);
	                }
	            }
	            cnt++;
	        }
	        if (cnt<size) {
				return null;
			}//閉路があればその頂点は一度もキューに入らない
	        return count;
	        //countはその頂点までの最大パス長
	        //resにcountの値が小さい順にソートされたものが入っている。
		}
	}
	static class InputReader { 
		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;
		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}
}

public class Main {

    static int[][] graph;
    static int time;
    static int[] d, f;
    static boolean[] visited;

    static void visit(int node) {
        if(!visited[node]) {
            visited[node] = true;
            d[node] = time++;
            for(int i = 1; i < d.length; i++) {
                if(graph[node][i] == 1) {
                    visit(i);
                }
            }
            f[node] = time++;
        }
    }

    public final static void main(String[] args) {
        try(Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();
            time = 1;
            graph = new int[n+1][n+1];
            d = new int[n+1];
            f = new int[n+1];
            visited = new boolean[n+1];
            for(int i = 0; i < n; i++) {
                int s = sc.nextInt();
                int k = sc.nextInt();
                for(int j = 0; j < k; j++) {
                    graph[s][sc.nextInt()] = 1;
                }
            }
            for(int i = 1; i <= n; i++) {
                visit(i);
            }
            for(int i = 1; i <= n; i++) {
                System.out.println(i + ” ” + d[i] + ” ” + f[i]);
            }
        }
    }
}

import java.util.Scanner;
public class Ex3_2 {

public class IntStack {
	private int max;
	private int ptr;
	private int[] stk;

	public class EmptyIntStackException extends RuntimeException{
		public EmptyIntStackException(){ }
	}
	public class OverflowIntStackException extends RuntimeException{
		public OverflowIntStackException(){ }
	}
	public IntStack(int capacity){
		ptr=0;
		max=capacity;
		try{
			stk=new int[max];

		}catch(OutOfMemoryError e){
			max=0;
		}
	}
	public int push(int x) throws OverflowIntStackException{
		if(ptr>=max){
			throw new OverflowIntStackException();
		}
		return stk[ptr++]=x;
	}

	public int pop() throws EmptyIntStackException{
		if(ptr<=0){
			throw new EmptyIntStackException();
		}
		return stk[--ptr];
	}

	public int peek() throws EmptyIntStackException{
		if(ptr<=0){
			throw new EmptyIntStackException();
		}
		return stk[ptr-1];
	}

	public int indexOf(int x){
		for(int i=ptr-1;i>=0;i--){
			if(stk[i]==x)
				return i;

		}
		return -1;
	}

	public void clear(){
		ptr=0;
	}

	public int capacity(){
		return max;
	}
	public int size(){
		return ptr;
	}

	public boolean isEmpty(){
		return ptr<=0;
	}

	public boolean isFull(){
		return ptr>=max;
	}

	public void dump(){
		if(ptr<=0)
			System.out.println("Stack is empty");
		else{
			for(int i=0;i<ptr;i++){
				System.out.print(stk[i]+" ");
			}
			System.out.println();
		}

	}





	public static void main(String args[]){

		Scanner stdin = new Scanner(System.in);

		int count=1;
		int[] fs,es,before;
		int[][] next;
		int n=stdin.nextInt();
		fs=new int[n+1];es=new int[n+1];before=new int[n+1];
		next=new int[n+1][];
		IntStack stack=new IntStack(n);


		fs[0]=es[0]=before[0]=-1;

		for(int i=1;i<=n;i++){
			stdin.nextInt();
			int size=stdin.nextInt();

			if(size==0) next[i]=null;
			else{
				next[i] =new int[size];
				for(int j=0;j<size;j++){
					next[i][j]=stdin.nextInt();
				}
			}
			fs[i]=es[i]=before[i]=0;
		}


		function(1,fs,es,next,count,stack);
		print(fs,es);



	}

	public static boolean isEmp(int id,int[] a,int[] es){
		if(a==null) return true;
		for(int i=0;i<a.length;i++){
			if(es[a[i]]==0) return false;
		}
		return true;
	}

	public static void function(int id,int[] fs,int[] es,int[][] next,int count,IntStack stack){


		if(id==1&&isEmp(1,next[1],es)){
			es[1]=++count;
		}else{
			if(fs[id]==0) fs[id]=count;
			if(isEmp(id,next[id],es)){
				count++;
				es[id]=count;
				function(stack.pop(),fs,es,next,count,stack);
			}else{
				int piv=0;
				for(int i=0;i<next[id].length;i++){
					if(es[next[id][i]]==0){
						piv=i; 
						break;
					}

				}

				stack.push(id);
				count++;
				function(next[id][piv],fs,es,next,count,stack);


			}
		}
	}

	public static void print(int[] fs,int[] es){
		for(int i=1;i<fs.length;i++){
			System.out.printf("%d %d %d\n",i,fs[i],es[i]);
		}
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Stack;
import java.util.StringTokenizer;

public class Main {

	class Vertex {
		int id;
		int[] vertices;
		int visited = -1;
		int completed = -1;
	}

	public static void main(String[] args) throws IOException {
		new Main().run();
	}

	private void run() throws IOException {
		BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(reader.readLine());
		Vertex[] vertices = new Vertex[n];
		for (int i = 0; i < n; i++) {
			vertices[i] = new Vertex();
			StringTokenizer st = new StringTokenizer(reader.readLine());
			int id = Integer.parseInt(st.nextToken());
			vertices[i].id = id;
			int cnt = Integer.parseInt(st.nextToken());
			vertices[i].vertices = new int[cnt];
			for (int j = 0; j < cnt; j++) {
				vertices[i].vertices[j] = Integer.parseInt(st.nextToken());
			}
		}
		reader.close();

		DFS(vertices, n);

		for (int i = 0; i < n; i++) {
			Vertex vertex = vertices[i];
			System.out.println(vertex.id + " " + vertex.visited + " " + vertex.completed);
		}
	}

	private void DFS(Vertex[] vertices, int n) {
		int time = 0;
		for (int i = 0; i < n; i++) {
			Vertex vertex = vertices[i];
			Stack<Integer> stack = new Stack<Integer>();
			if (vertex.visited == -1) {
				stack.push(vertex.id);
			}
			while (!stack.isEmpty()) {
				vertex = vertices[stack.peek()-1];
				if (vertex.visited == -1) {
					vertex.visited = ++time;
				}
				boolean allVisited = true;;
				for (int j = 0; j < vertex.vertices.length; j++) {
					int childId = vertex.vertices[j];
					if (vertices[childId-1].visited == -1) {
						vertices[childId-1].visited = ++time;
						allVisited = false;
						stack.push(childId);
					}
				}
				if (allVisited) {
					vertex.completed = ++time;
					stack.pop();
				}
			}
		}
	}	
}

