import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

	// a graph structure based on adjacent graph
	public static class graph{
		public int v_num; // the number of vertices
		public List<List<Integer>> adj_table;

		public graph(int _v_num) {
			v_num = _v_num;
			adj_table = new ArrayList<List<Integer>>();
			for(int i = 0; i < v_num; i++) {
				adj_table.add(new ArrayList<Integer>());
			}
		}


		//src and dst is always 1-kara
		public void insert_edge(int src, int dst) {
			adj_table.get(src-1).add(dst);
		}

		// 1-kara
		public List<Integer> get_adj_nodes(int i){
			return adj_table.get(i-1); 
		}
	}

	public static int clock = 0;


	public static void _dfs(graph g, int current, int[] b, int []f) {
		clock++;
		b[current] = clock;
		List<Integer> adj_list = g.get_adj_nodes(current);
		for(int i = 0; i < adj_list.size(); i++) {
			if(b[adj_list.get(i)] == 0)
				_dfs(g, adj_list.get(i), b, f);
		}
		clock++;
		f[current] = clock;

	}

	public static void dfs(graph g) {
		int [] b = new int[g.v_num+1];
		int [] f = new int[g.v_num+1];
		int component_count = 0;
		for(int i = 1; i <= g.v_num; i++) {
			if(b[i] == 0) {
				_dfs(g, i, b, f);
				component_count++;
			}
		}

		for(int i = 1; i <= g.v_num; i++) {
			System.out.println(i + " "+ b[i]+" "+f[i]);
		}
	}

	public static void main(String [] args) {
		Scanner cin = new Scanner(System.in);
		int n = cin.nextInt();
		graph g = new graph(n);

		int src_id,  list_len; 
		for(int i = 0; i< n; i++) {
			src_id = cin.nextInt();
			list_len = cin.nextInt();
			while(list_len > 0) {
				g.insert_edge(src_id, cin.nextInt());
				list_len--;
			}
		}

		dfs(g);


		cin.close();


	}
}

import java.io.File;
import java.io.IOException;
import java.util.Arrays;
import java.util.Scanner;

public class Main {

	static int count = 0;

	public static void main(String[] args) throws IOException {

		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();
		int[][] mat = new int[n+1][n+1];

		// 初回訪問リスト
		int[] d = new int[n+1];
		Arrays.fill(d, -1);

		// 訪問完了リスト
		int[] f = new int[n+1];
		Arrays.fill(f, -1);

		for (int i = 0; i < n; i++) {
			int u = sc.nextInt();			// 番号
			int k = sc.nextInt();			// uの出次数
			for (int j = 0; j < k; j++) {
				int v = sc.nextInt();
				mat[u][v] = 1;
			}
		}

		// 深さ優先探索（再帰）
		for (int index = 1; index <= n; index++) {
			dfs(mat, d, f, index);
		}

		for (int i = 1; i <= n; i++) {
			System.out.println(i + " " + d[i] + " " + f[i]);
		}
	}
	public static void dfs(int[][] mat, int[] d, int[] f, int index) {
		int from = index;
		if (d[from] != -1) {
			return;
		}
		d[from] = ++count;

		for (int to = 1; to < mat[from].length; to++) {
			if (mat[from][to] == 1 && d[to] == -1) {
				dfs(mat, d, f, to);
			}
		}
		f[from] = ++count;
	}

}

