			u = sc.nextInt();
			k = sc.nextInt();
			while(k > 0) {
				v = sc.nextInt();
				list[u-1][v-1] = 1;
				k--;
			}
		}
	}

	public void dfs() {
		for(int i=0; i<n; i++) { color[i] = 0; }
		time = 0;
		for(int i=0; i<n; i++) { if(color[i] == 0) visit(i); }
