public class ALDS1_11_B_DepthFirstSearch {

	static int[] first;
	static int [] end;
	static List[] arLs;

	static int dfs(int cur,int ts) {
		first[cur] = first[cur]==0 ? ts : first[cur];
		int now = ts+1;
		for(int i=0;i<arLs[cur].size();i++) {
			int a = (Integer)arLs[cur].get(i);
			if (first[a]==0){
				now = dfs(a, now);
			}
		}
		end[cur] = end[cur]==0 ? now : end[cur];
