using System;

public class Program
{
	const int MAX = 100;
	const int INFTY = (1<<21);
	const int WHITE = 0;
	const int GRAY = 1;
	const int BLACK= 2;

	static int n;
	static int[ , ] M = new int[MAX,MAX];

	public static void dijkstra()
	{
		int minv;
		int[] d = new int[MAX];
		int[] color = new int[MAX];

		for(int i = 0; i < n; i++){
			d[i] = INFTY;
			color[i] =WHITE;
		}

		d[0] = 0;
		color[0] = GRAY;
		while(true){
			minv = INFTY;
			int u = -1;
			for(int i = 0; i < n; i++){
				if(minv > d[i] && color[i] != BLACK){
					u = i;
					minv = d[i];
				}
			}
			if(u == -1) break;
			color[u] = BLACK;
			for(int v = 0; v < n; v++){
				if(color[v] != BLACK && M[u,v] != INFTY){
					if(d[v] > d[u] + M[u,v]){
						d[v] = d[u] + M[u,v];
						color[v] = GRAY;
					}
				}
			}
		}

		for(int i = 0; i < n; i++){
			Console.WriteLine("{0} {1}", i, d[i] == INFTY ? -1 : d[i]);
		}
	}

	public static void Main()
	{
		n = int.Parse(Console.ReadLine());
		for(int i = 0; i < n; i++){
			for(int j = 0; j < n; j++){
				M[i, j] = INFTY;
			}
		}

		int k, c, u, v;
		for(int i = 0; i < n; i++){
			string[] line = Console.ReadLine().Split(' ');
			u = int.Parse(line[0]);
			k = int.Parse(line[1]);
			for(int j = 0; j < k; j++){
				v = int.Parse(line[2+j*2]);
				c = int.Parse(line[3+j*2]);
				M[u, v] = c;
			} 
		}
		dijkstra();
	}
}

