public class hello
{
    public static void Main()
    {
        var nodes = new List<Node>();
        var n = int.Parse(Console.ReadLine().Trim());
        for (int i = 0; i < n; i++)
        {
            string[] s = Console.ReadLine().Trim().Split(' ');
            var u = int.Parse(s[0]);
            var k = int.Parse(s[1]);
            var a = new Node { child = new List<int>(), nno = u };
            for (int j = 0; j < k; j++) a.child.Add(int.Parse(s[j + 2]));
            nodes.Add(a);
        }
        var ts = new TimeStump { ts = 1 };
        var df0 = new int[n + 1];
        var df1 = new int[n + 1];
        var sno = 1;
        while (true)
        {
            VisitNode(nodes, df0, df1, sno, ts);
            df1[sno] = ts.ts; ts.ts++;
            var t3 = GetNum(df0);
            if (t3 == 0) break;
            else sno = t3;
        }
        DispAns(df0, df1);
    }
    public static void DispAns(int[] df0, int[] df1)
    {
        for (int i = 1; i < df0.Length; i++)
            Console.WriteLine("{0} {1} {2}", i, df0[i], df1[i]);
    }
    public static void VisitNode(List<Node> node, int[] df0, int[] df1, int n, TimeStump ts)
    {
        var r = node[n - 1];
        df0[n] = ts.ts; ts.ts++;
        if (r.child.Count() == 0) return;
        foreach (var x in r.child)
        {
            if (df0[x] == 0)
            {
                VisitNode(node, df0, df1, x, ts);
                { df1[x] = ts.ts; ts.ts++; }
            }
        }
    }
    public static int GetNum(int[] df0)
    {
        for (int i = 1; i < df0.Length; i++)
            if (df0[i] == 0) return i;
        return 0;
    }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
class Program
{
static long n = long.Parse(Console.ReadLine());
static long[,] nextMatrix = new long[n,n];//隣接行列
static long[] startTime = new long[n];//頂点に初めて着いた時刻
static long[] goalTime = new long[n];//頂点を調べ終わった時刻
static long[] colors = new long[n];//隣接頂点を調べ終わったら2
static long timeMemo = 0;
static long[] nextVertexes = new long[n];

	static void Main()
	{
    for(long i = 0; i < n; i++)
    {
		  long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
      for(long j = 0; j < nums[1]; j++)
      {
        nextMatrix[i,nums[j+2]-1] = 1;//隣接行列の作成
      }
    }
    DFS();
	}

  static void DFS()//深さ優先探索、O(V^2)
  {
    for(long i = 0; i < n; i++)
    {
      colors[i] = 0;//初期化
      nextVertexes[i] = 0;
    }
    timeMemo = 0;

    for(long i = 0; i < n; i++)
    {
      if(colors[i] == 0) DFSvisit(i);
    }

    for(long i = 0; i < n; i++)
    {
      Console.WriteLine((i+1) + " " + startTime[i] + " " + goalTime[i]);
    }
  }

  static void DFSvisit(long startVertex)//開始頂点から
  {
    for(long i = 0; i < n; i++)
    {
      nextVertexes[i] = 0;
    }

    var stack = new Stack<long>();//スタック
    stack.Push(startVertex);
    colors[startVertex] = 1;
    timeMemo++;
    startTime[startVertex] = timeMemo;

    while(stack.Count > 0)
    {
      long topMemo = stack.Peek();
      long v = NextVertex(topMemo);
      if(v != -1)
      {
        if(colors[v] == 0)
        {
          colors[v] = 1;
          timeMemo++;
          startTime[v] = timeMemo;
          stack.Push(v);
        }
      }else
      {
        stack.Pop();
        colors[topMemo] = 2;
        timeMemo++;
        goalTime[topMemo] = timeMemo;
      }
    }
  }

  static long NextVertex(long vertexMemo)
  {
    for(long i = nextVertexes[vertexMemo]; i < n; i++)
    {
      nextVertexes[vertexMemo] = i+1;
      if(nextMatrix[vertexMemo, i] == 1) return i;
    }
    return -1;
  }

}

