    class Depth_First_Search
    {
        static int n;
        static int[] times;

        static void Main(string[] args)
        {
            n = int.Parse(Console.ReadLine());
            var G = new bool[n][];
            times = new int[2 * n];
            for (int i = 0; i < n; i++)
            {
                var token = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
                var row = token[0] - 1;
                G[row] = new bool[n];
                for (int j = 0; j < token[1]; j++)
                    G[row][token[2 + j] - 1] = true;
            }

            DepthFirstSearch(G, 0, 0, 0);

            for (int i = 0; i < n; i++)
            {
                Console.WriteLine("{0} {1} {2}", i + 1, times[2 * i], times[2 * i + 1]);
            }
        }

        static int DepthFirstSearch(bool[][] graph, int row, int col, int time)
        {
            if (times[2 * row] == 0) times[2 * row] = ++time;
            for (int i = col + 1; i < n; i++)
                if (graph[row][i]) time = DepthFirstSearch(graph, i, i, time);
            if (times[2 * row + 1] == 0) times[2 * row + 1] = ++time;
            return time;
        }
    }
}

