using System;

class V {

	public int edge;
	public int[] adj;
	public int d;
	public int f;

	public V(int k) {
		edge = k;
		adj = new int[edge];
	}
}

class Depth_First_Search {
	public static void Main() {

		int n = int.Parse(Console.ReadLine());
		int time = 0;

		V[] ver = new V[n + 1];

		for(int i = 0; i < n; i++) {

			string[] num = Console.ReadLine().Split();
			int u = int.Parse(num[0]);
			int k = int.Parse(num[1]);
			ver[u] = new V(k);

			for(int j = 0; j < k; j++) {
				ver[u].adj[j] = int .Parse(num[2 + j]);
			}
		}

		for(int i = 1; i <= n; i++) {
			if(ver[i].d == 0) {
				DFS(ver, i, ref time);
			}
		}

		for(int i = 1; i <= n; i++) {
			Console.WriteLine(i + " " + ver[i].d + " " + ver[i].f);
		}

	}

	static void DFS(V[] ver, int u, ref int time) {

		if(ver[u].d == 0) {

			ver[u].d = ++time;

			if(ver[u].edge != 0) {

				for(int i = 0; i < ver[u].edge; i++) {
					if(ver[ver[u].adj[i]].d == 0) {
						DFS(ver, ver[u].adj[i], ref time);
					}
				}

			}
		}

		if(ver[u].f == 0) {
			ver[u].f = ++time;
		}

	}

}

