public class ALDS1_11_B
{
    public struct Node
    {
        public int Id;
        public List<int> Adj;
        public int Start;
        public int End;
        public Node(int id)
        {
            Id = id + 1;
            Adj = new List<int>();
            Start = -1;
            End = -1;
        }
    }

    public static void Main(string[] args)
    {
        //var exStdIn = new System.IO.StreamReader( "input.txt" );
        //System.Console.SetIn( exStdIn );

        int n = int.Parse(Console.ReadLine());
        var g = new Node[n];
        for (int i = 0; i < n; i++)
        {
            g[i] = new Node(i);
        }

        for (int i = 0; i < n; i++)
        {
            int[] val = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
            for (int j = 2; j < val[1] + 2; j++)
            {
                g[val[0] - 1].Adj.Add(val[j] - 1);
            }
        }

        int time = 0;
        for (int i = 0; i < n; i++)
        {
            if (g[i].Start != -1)
            {
                continue;
            }
            time = Dfs(i, time, g);
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++)
        {
            sb.Append(g[i].Id);
            sb.Append(" ");
            sb.Append(g[i].Start);
            sb.Append(" ");
            sb.Append(g[i].End);
            sb.AppendLine();
        }
        Console.Write(sb.ToString());
    }

    public static int Dfs(int index, int time, Node[] g)
    {
        if (g[index].Start != -1)
        {
            return time;
        }
        time++;
        g[index].Start = time;
        for (int i = 0; i < g[index].Adj.Count; i++)
        {
            time = Dfs(g[index].Adj[i], time, g);
        }
        time++;
        g[index].End = time;
        return time;
    }
}

