    public int Len { get; set; } = 0;
    public int Pos { get; set; } = 0;
    public int Ts1 { get; set; } = 0;
    public int Ts2 { get; set; } = 0;

    public int Next()
    {
      if (this.Pos >= this.Len) return -1;
      int next = this.Rels[this.Pos];
      this.Pos++;
      return next;
    }
  }

  class Program
  {
    static Node[] graph;
    static Stack<int> stack;
    static int time;
    static void Dfs(int idx)
    {
      stack.Push(idx);
      graph[idx].Ts1 = ++time;
      while (stack.Count > 0)
      {
        int u = stack.Peek();
        int v = graph[u].Next();
        if (v != -1)
        {
          if (graph[v].Ts1 == 0)
          {
            graph[v].Ts1 = ++time;
            stack.Push(v);
          }
        }
        else
        {
          graph[u].Ts2 = ++time;
          stack.Pop();
        }
      }
    }
