            for (int i = 0; i < n; i++)
            {
                int[] input = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);

                nodes[input[0]] = new Node();

                for (int j = 0; j < input[1]; j++)
                {
                    nodes[input[0]].adj.Enqueue(input[2 + j]);
                }
            }

