        static void DFS(Node[] nodes, Node node)
        {
            Stack<Node> stk = new Stack<Node>();

            node.color = Color.gray;
            node.d = ++cnt;
            stk.Push(node);

            while (stk.Count > 0)
            {
                Node u = stk.Peek();

                int v = -1;
                if (u.adj.Count > 0) v = u.adj.Dequeue();

                if (v != -1 && nodes[v].color == Color.white)
                {
