namespace Practice
{
    class Program
    {
        const int WHITE = 0;
        const int GRAY = 1;
        const int BLACK = 2;
        static void Main(string[] args)
        {
            SolveA(args);
            //SolveB(args);
            //SolveC(args);
            //SolveD(args);


        }
        static void SolveA(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            int[,] m = new int[n, n];
            for(int i=0;i<n;++i)
            {
                string[] szarr = Console.ReadLine().Split(' ');
                //int u = int.Parse(szarr[0]);
                int k = int.Parse(szarr[1]);
                for(int j=0;j<k;++j)
                {
                    int v =int.Parse( szarr[j+ 2]);
                    int idx = v - 1;
                    m[i, idx] = 1;
                }
            }
            int[] color = new int[n];
            int[] d = new int[n];
            int[] f = new int[n];
            DFS(0, color, d, f, m);
            for(int i=0;i<n;++i)
            {
                string sz = string.Format("{0} {1} {2}", i + 1, d[i], f[i]);
                Console.WriteLine(sz);
            }
        }
        static void DFS(int u, int[] color, int[] d, int [] f, int[,] m)
        {
            Stack<int> s = new Stack<int>();
            s.Push(u);
            color[u] = GRAY;
            int time = 0;
            d[u] = ++time;
            while(s.Count >= 1)
            {
                u = s.Peek();
                int v = Next(m, u, color);
                if( v != -1)
                {
                    if( color[v] == WHITE)
                    {
                        color[v] = GRAY;
                        d[v] = ++time;
                        s.Push(v);
                    }
                }
                else
                {
                    s.Pop();
                    color[u] = BLACK;
                    f[u] = ++time;
                }

                if( s .Count == 0)
                {
                    // 残ってる頂点検索
                    for(int i=0;i<color.Length;++i)
                    {
                        if( color[i] == WHITE)
                        {
                            s.Push(i);
                        }
                    }
                }
            }
         }
        static int Next(int[,] m , int u, int[] color)
        {
            for(int i=0;i<m.GetLength(0);++i)
            {
                if(m[u,i] == 1 && color[i] == WHITE)
                {
                    return i;
                }
            }
            return -1;
        }
    }

}

