class Program
{
    static List<Node> nodes = new List<Node>();
    static int time = 0;

    class Node
    {
        public bool visited = false;
        public int d_time = 0;
        public int f_time = 0;
        public List<int> adjacentIds;
    }

    static void Main(string[] args)
    {
    	// 行数を取得
        int n = int.Parse(Console.ReadLine().Split()[0]);

        // nodeを作成
        for (int i = 0; i < n; i++)
        {
            nodes.Add(new Node());
        }

        // nodeの中身設定
        for (int i = 0; i < n; i++)
        {
            List<int> nums = Console.ReadLine().Split().Select(str => int.Parse(str)).ToList();
            nodes[nums[0] - 1].adjacentIds = nums.GetRange(2, nums[1]).Select(id => id - 1).ToList();
        }

        // dfs
        while (nodes.Exists(node => node.d_time == 0))
        {
            dfs(nodes.Where(node => node.d_time == 0).ToList()[0]);
        }

        // 出力
        for (int i = 0; i < n; i++)
        {
            System.Console.WriteLine(string.Format("{0} {1} {2}", i + 1, nodes[i].d_time, nodes[i].f_time));
        }
    }

    static void dfs(Node node)
    {
        time++;
    	node.visited = true;
       	if (node.d_time == 0)
       	{
       		node.d_time = time;
       	}
        foreach (var adjacentId in node.adjacentIds)
        {
        	if (!nodes[adjacentId].visited)
        	{
	            dfs(nodes[adjacentId]);
	        }
        }
        time++;
        node.f_time = time;
    }
}

