namespace ConsoleApplication1
{
    enum Color { white, gray, black }

    class Node
    {
        internal int d, f;
        internal Color color;
        internal Queue<int> adj;

        public Node() { adj = new Queue<int>(); }
    }

    class Program
    {
        static int cnt;

        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());

            Node[] nodes = new Node[n + 1];

            for (int i = 0; i < n; i++)
            {
                int[] input = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);

                nodes[input[0]] = new Node();

                for (int j = 0; j < input[1]; j++)
                {
                    nodes[input[0]].adj.Enqueue(input[2 + j]);
                }
            }

            cnt = 0;

            for (int i = 1; i <= n; i++)
            {
                if (nodes[i].color == Color.white) DFS(nodes, nodes[i]);
            }

            StringBuilder sb = new StringBuilder();
            for (int i = 1; i <= n; i++)
            {
                sb.AppendLine(i + " " + nodes[i].d + " " + nodes[i].f);
            }
            Console.Write(sb);
        }

        static void DFS(Node[] nodes, Node node)
        {
            Stack<Node> stk = new Stack<Node>();

            node.color = Color.gray;
            node.d = ++cnt;
            stk.Push(node);

            while (stk.Count > 0)
            {
                Node u = stk.Peek();

                int v = -1;
                while (u.adj.Count > 0 && v == -1)
                {
                    if (nodes[u.adj.Peek()].color == Color.white) v = u.adj.Dequeue();
                    else u.adj.Dequeue();
                }

                if (v != -1)
                {
                    nodes[v].color = Color.gray;
                    nodes[v].d = ++cnt;
                    stk.Push(nodes[v]);
                }
                else
                {
                    u.color = Color.black;
                    u.f = ++cnt;
                    stk.Pop();
                }
            }
        }
    }
}

