        private static int Dfs(int id, Dictionary<int, int[]> vertices, int count, Dictionary<int, bool> isArrived, Dictionary<int, int[]> output)
        {
            count++;
            var startCount = count;
            isArrived[id] = true;

            for(var i = 0; i < vertices[id].Length; i++)
            {
                if (!isArrived[vertices[id][i]])
                {
                    count = Dfs(vertices[id][i], vertices, count, isArrived, output);
                }
            }

            count++;
            output.Add(id, new int[2] { startCount, count });
            return count;
        }
    }
}

