namespace ALDS1_11_B
{
    class Program
    {
        private static int n;
        private static int[,] neighborList;
        private static int[] arriveTime;
        private static int[] finishTime;
        private static bool[] isVisit;
        static void Main(string[] args)
        {
            Program.n = int.Parse(Console.ReadLine());
            Program.neighborList = new int[n,n];
            for (int i = 0; i < n; i++)
            {
                int[] tmpLine = Console.ReadLine()
                                       .Split(' ')
                                       .Select(s => int.Parse(s))
                                       .ToArray();
                for (int j = 2; j < tmpLine[1] + 2; j++)
                {
                    Program.neighborList[i, tmpLine[j] - 1] = 1;
                }
            }
            Program.arriveTime = new int[Program.n];
            Program.finishTime = new int[Program.n];
            Program.isVisit = new bool[Program.n];

            int tmpTime = 0;
            for (int i = 0; i < Program.n; i++)
            {
                if (!Program.isVisit[i])
                {
                    tmpTime = Program.DepthFirstSearch(i + 1, tmpTime);
                }
            }

            for (int i = 0; i < Program.n; i++)
            {
                Console.WriteLine(string.Format("{0} {1} {2}", i + 1, Program.arriveTime[i], Program.finishTime[i]));
            }
        }

        static int DepthFirstSearch(int targetIndex, int beforeArriveTime){
            //targetIndexは、配列上のインデックスではなく、実際のインデックス
            int tmpTime = beforeArriveTime;
            //遷移元から+1秒
            tmpTime++;
            Program.arriveTime[targetIndex - 1] = tmpTime;
            Program.isVisit[targetIndex - 1] = true;

            Stack<int> neighborStack = new Stack<int>(); 
            for (int i = Program.n - 1; i >= 0; i--)
            {
                if (Program.neighborList[targetIndex - 1, i] == 1)
                {
                    neighborStack.Push(i + 1);
                }
            }

            while (neighborStack.Count > 0)
            {
                int neighborIndex = neighborStack.Pop();
                if (!Program.isVisit[neighborIndex - 1])
                {
                    tmpTime = Program.DepthFirstSearch(neighborIndex, tmpTime);    
                }
            }
            //遷移元へ戻るのに、+1秒
            tmpTime++;
            Program.finishTime[targetIndex - 1] = tmpTime;

            return tmpTime;
        }
    }
}

