public class Solver
{
	private int N;
	private List<int>[] adj;
	private int T;
	private int[] d;
	private int[] f;

	public void Solve()
	{
		N = GetInt();
		adj = Enumerable.Range(0, N).Select(_ => new List<int>()).ToArray();
		for(int i = 0; i < N; i++)
		{
			int u = GetInt() - 1;
			int K = GetInt();
			for(int j = 0; j < K; j++)
				adj[u].Add(GetInt() - 1);
		}

		T = 0;
		d = new int[N];
		f = new int[N];

		for(int i = 0; i < N; i++)
		{
			if(d[i] == 0)
				dfs(i);
		}

		for(int i = 0; i < N; i++)
			WriteLine($"{i + 1} {d[i]} {f[i]}");
	}

	private void dfs(int v)
	{
		d[v] = ++T;
		foreach(int u in adj[v])
		{
			if(d[u] == 0)
				dfs(u);
		}
		f[v] = ++T;
	}
}

