	class Node<T> {
		public T Value { get; set; }
		public int Id { get; set; }
		public int Order{ get; set; }
		public bool visited { get; set; }
		public virtual List<Edge<T>> Outs { get; set; } = new List<Edge<T>>();
		public void Adopt(Edge<T> child) {
			Outs.Add(child);
		}

		public virtual List<Node<T>> Nexts() => Outs.Select(e => e.to).ToList();
	}
	struct Edge<T> {
		public Node<T> from { get; set; }
		public Node<T> to { get; set; }
		public T value { get; set; }
		public Edge(Node<T> _from, Node<T> _to, T _value) {
			from=_from; to=_to; value=_value;
		}
	}
	class Graph<T> {
		public Node<T>[] member { get; }
		public int N { get; }
		public Graph(int N) {
			member=new Node<T>[N];
			this.N=N;
			for(int i = 0; i<N; i++) {
				member[i]=new Node<T>() { Id=i };
			}
		}
		public void AddEdge(int i, int j, T value) {
			var e = new Edge<T>(member[i], member[j], value);
			member[i].Adopt(e);
		}
		public string EmitMatrix() {
			var rows = new string[N];
			for(int i = 0; i<N; i++) {
				var values = new T[N];
				foreach(var e in member[i].Outs)
					values[e.to.Id]=e.value;
				rows[i]=values.Join();
			}
			return rows.Join("\n");
		}
		public void DFS(int start, Action<Node<T>> onEnter, Action<Node<T>> onLeave) {
			var S = new Stack<Node<T>>();
			S.Push(member[start]);
			var entered = new bool[N];
			var leaved = new bool[N];
			member[start].visited=true;
			while(S.Any()) {
				var v = S.Peek();
				if(!entered[v.Id]) {
					onEnter(v);
					entered[v.Id]=true;
				}
				var next = v.Nexts().Where(w => !w.visited);
				if(next.Any()) {
					var w = next.First();
					S.Push(w);
					w.visited=true;
				} else {
					S.Pop();
					if(!leaved[v.Id]) {
						onLeave(v);
						leaved[v.Id]=true;
					}
				}
			}
		}

	}
}

