        }

    }
    class Program
    {
        static  int time = 0;

        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            Element [] arr = new Element[n];

            for (int i = 0; i < n; i++)
            {
                string [] input = (Console.ReadLine()).Split(' ');

                arr[int.Parse(input[0])-1] = new Element();
                arr[int.Parse(input[0])-1].id = int.Parse(input[0]);
                arr[int.Parse(input[0])-1].Setting(int.Parse(input[1]));
                arr[int.Parse(input[0])-1].degree = int.Parse(input[1]);

                for (int j = 0; j < int.Parse(input[1]); j++)
                {
                    arr[int.Parse(input[0])-1].next_list[j] = int.Parse(input[j + 2]);
                }

            }

            DFS(arr);

            for (int i= 0; i < n; i++)
            {
                Console.WriteLine(arr[i].id + " " + arr[i].d + " " + arr[i].f);
            }

            Console.ReadLine();
        }

        static void DFS(Element [] g)
        {
            for ( int i = 1; i <= g.Length; i++)
            {
                if (g[i-1].state == 0) {
                    Visit(g, i);
                }
            }

        }

        static void Visit(Element [] u , int i)
        {
            u[i-1].state = 1;
            time++;
            u[i-1].d = time;

            foreach (int j in  u[i-1].next_list)
            {
                if (u[j-1].state == 0)
                {
                    Visit(u, j);
                }
            }
            u[i-1].state += 1;
            time++;
            u[i-1].f = time;

         }
    }
}

