	class Graph
	{
		public Graph ( int size )
		{
			this.Map = new int[size, size];
			this.Timestamp = new int[size, 2];
			this.UsedIndex = new int[size];
			this.StateArray = new int[size];
		}

		private int[,] Map { set; get; }
		private	int[,] Timestamp { set; get; }
		private int[] UsedIndex { set; get; }
		private int[] StateArray { set; get; }
		private int Time = 1;

		public const int Exist = 1;
		private const int OutOfRange = -1;

		const int NotVisited = 0;
		const int Stay = 1;
		const int Visited = 2;

		public void GetPath ( int beginPoint, int adjacencyPoint )
		{
			Map[beginPoint - 1, adjacencyPoint - 1] = Exist;
		}

		public int[,] DepthFirstSearch ()
		{
			for (int lp = 0; lp < Map.GetLength(0); lp++)
			{
				if (StateArray[lp] == NotVisited)
				{
					Search (lp);
				}
			}

			return Timestamp;
		}

		private void Search ( int lp )
		{
			const int First = 0;
			const int Last = 1;

			UsedIndex.Initialize ();

			Stack<int> stack = new Stack<int> (Timestamp.Length / 2);
			stack.Push (lp);
			StateArray[lp] = Stay;
			Timestamp[lp, First] = Time;
			Time++;

			while (stack.Count != 0)
			{
				int point = stack.Peek ();
				int index = NextIndex (point);

				if (index != OutOfRange)
				{
					if (StateArray[index] == NotVisited)
					{
						StateArray[index] = Stay;
						Timestamp[index, First] = Time;
						Time++;
						stack.Push (index);
					}
				}
				else
				{
					stack.Pop ();
					StateArray[point] = Visited;
					Timestamp[point, Last] = Time;
					Time++;
				}
			}
		}

		private int NextIndex ( int index )
		{
			for (int lp = UsedIndex[index]; lp < UsedIndex.Length; lp++)
			{
				if (Map[index, lp] == Exist)
				{
					UsedIndex[index] = lp + 1;
					return lp;
				}
			}

			UsedIndex[index] = UsedIndex.Length + 1;

			return OutOfRange;
		}

		public override string ToString ()
		{
			int[,] result = DepthFirstSearch ();
			StringBuilder output = new StringBuilder (result.Length * 2);

			for (int row = 0; row < result.GetLength (0) - 1; row++)
			{
				output.Append (row + 1);
				output.Append (" ");
				output.Append (result[row, 0]);
				output.Append (" ");
				output.Append (result[row, 1]);
				output.AppendLine ();
			}

			return output.ToString ();
		}
	}
}

