public class Program
{
	static int time = 0;

	public static void Main()
	{
		int n = int.Parse(Console.ReadLine());

		int[,] G = new int[n,n];

		for(int i = 0; i < n; i++) {
			int[] u = Array.ConvertAll(Console.ReadLine().Split(" ".ToCharArray()), int.Parse);

			for(int j = 0; j < u[1];  j++) {
				G[u[0]-1, u[j+2]-1] = 1;
			}
		}

		Node[] nodes = new Node[n];
		for(int i = 1; i <= n; i++) {
			nodes[i - 1] = new Node(i);
		}

		for(int i = 0; i < n; i++) {
			for(int j = 0; j < n; j++) {
				if(G[i,j] != 0) { 
					nodes[i].Children.Add(nodes[j]);
				}
			}
		}

		for(int i = 0; i < n; i++) {
			if(nodes[i].StartTime == 0) DFS(nodes, nodes[i]);
		}

		for(int i = 0; i < n; i++) {
			Console.WriteLine(nodes[i]);
		}
	}

	static void DFS(Node[] nodes, Node node)
	{
		node.StartTime = ++time;

		for(int i = 0; i < node.Children.Count; i++) {
			if(nodes[node.Children[i].Id -1].StartTime == 0) DFS(nodes, nodes[node.Children[i].Id -1]);
		}

		node.EndTime = ++time;
	}

}

