public class DFS
{
public static void Main()
{
	var n = int.Parse(Console.ReadLine());
	var u = Enumerable.Range(0, n)
		.Select(_ => Console.ReadLine());

	var builtupNodes = Build(u);

	new Explorer().Explore(builtupNodes.First());

	builtupNodes.ToList().ForEach(x => Console.WriteLine(x.Id + " " + x.FoundTime + " " + x.FinishedTime));
}

public class Explorer
{
	private int time = 0;
	public void Explore(Node node)
	{
		node.FoundTime = ++time;
		foreach (var n in node.Children.Where(x => x.FoundTime == 0))
		{
			Explore(n);
		}
		node.FinishedTime = ++time;
	}
}
}
public class Node
{
	public int Id { get; set; }
	public IEnumerable<Node> Children { get; set; }
	public int FoundTime { get; set; }
	public int FinishedTime { get; set; }
}

public static IEnumerable<Node> Build(IEnumerable<string> u)
{
	var nodeAndInputs = u.Select(x => x.Split(' '))
		.Select(x => x.Select(int.Parse))
		.Select(x => new 
		{ 
			node = new Node
			{
				Id = x.First(),
				Children = new Node[0]
			},
			input = x
		})
		.ToList();

	return nodeAndInputs.Select(nodeinput => 
	{
		nodeinput.node.Children = nodeAndInputs
			.Select(x => x.node)
			.Where(x => nodeinput.input.Skip(2).Contains(x.Id));
		return nodeinput.node;
	})
	.OrderBy(x => x.Id);
}

