using System.Linq;

class Program
{
    static List<Node> nodes = new List<Node>();
    static int time = 0;

    class Node
    {
        public bool visited = false;
        public int d_time = 0;
        public int f_time = 0;
        public List<int> adjacentIds;
    }

    static void Main(string[] args)
    {
    	// 行数を取得
        int n = int.Parse(Console.ReadLine().Split()[0]);

        // nodeを作成
        for (int i = 0; i < n; i++)
        {
            nodes.Add(new Node());
        }

        // nodeの中身設定
        for (int i = 0; i < n; i++)
        {
            List<int> nums = Console.ReadLine().Split().Select(str => int.Parse(str)).ToList();
            nodes[nums[0] - 1].adjacentIds = nums.GetRange(2, nums[1]).Select(id => id - 1).ToList();
        }

        // dfs
        while (nodes.Exists(node => node.d_time == 0))
        {
            dfs(nodes.Where(node => node.d_time == 0).ToList()[0]);
            time++;
        }

        // 出力
        for (int i = 0; i < n; i++)
        {
            System.Console.WriteLine(string.Format("{0} {1} {2}", i + 1, nodes[i].d_time, nodes[i].f_time));
        }
    }

    static void dfs(Node node)
    {
        time++;
    	node.visited = true;
       	if (node.d_time == 0)
       	{
       		node.d_time = time;
       	}
        if (node.adjacentIds.Count() == 0)
        {
            node.f_time = time;
        }
        foreach (var adjacentId in node.adjacentIds)
        {
        	if (!nodes[adjacentId].visited)
        	{
	            dfs(nodes[adjacentId]);
	        }
        }
        time++;
        node.f_time = time;
    }
}

using System;

public class Program
{
	const int MAX = 100;
	const int INFTY = (1<<21);
	const int WHITE = 0;
	const int GRAY = 1;
	const int BLACK= 2;

	static int n;
	static int[ , ] M = new int[MAX,MAX];

	public static void dijkstra()
	{
		int minv;
		int[] d = new int[MAX];
		int[] color = new int[MAX];

		for(int i = 0; i < n; i++){
			d[i] = INFTY;
			color[i] =WHITE;
		}

		d[0] = 0;
		color[0] = GRAY;
		while(true){
			minv = INFTY;
			int u = -1;
			for(int i = 0; i < n; i++){
				if(minv > d[i] && color[i] != BLACK){
					u = i;
					minv = d[i];
				}
			}
			if(u == -1) break;
			color[u] = BLACK;
			for(int v = 0; v < n; v++){
				if(color[v] != BLACK && M[u,v] != INFTY){
					if(d[v] > d[u] + M[u,v]){
						d[v] = d[u] + M[u,v];
						color[v] = GRAY;
					}
				}
			}
		}

		for(int i = 0; i < n; i++){
			Console.Write("{0}???{1}", i, d[i] == INFTY ? -1 : d[i]);
		}
	}

	public static void Main()
	{
		n = int.Parse(Console.ReadLine());
		for(int i = 0; i < n; i++){
			for(int j = 0; j < n; j++){
				M[i, j] = INFTY;
			}
		}

		int k, c, u, v;
		for(int i = 0; i < n; i++){
			string[] line = Console.ReadLine().Split(' ');
			u = int.Parse(line[0]);
			k = int.Parse(line[1]);
			for(int j = 0; j < k; j++){
				v = int.Parse(line[2+j*2]);
				c = int.Parse(line[3+j*2]);
				M[u, v] = c;
			} 
		}
		dijkstra();
	}
}

