namespace ALDS1_11_B {
    class Problem {
        Node[] _nodes;
        private int _vol, _time;

        public void Run() {
            SetNodes();

            StringBuilder sb = new StringBuilder();
            for (int i = 1; i <= _vol; i++) {
                if (_nodes[i].First == 0) {
                    DFS(i);
                }
                sb.Append(i + " ");
                sb.AppendLine(_nodes[i].ToString());
            }
            Console.Write(sb);
        }

        private void SetNodes() {
            _vol = int.Parse(Console.ReadLine());
            _nodes = new Node[_vol + 1];
            for (int i = 0; i < _vol; i++) {
                string[] input = Console.ReadLine().Split(' ');
                int u = int.Parse(input[0]);
                int k = int.Parse(input[1]);
                _nodes[u] = new Node();
                for (int j = 0; j < k; j++) {
                    _nodes[u].Children.Add(int.Parse(input[2 + j]));
                }
            }
        }

        private void DFS(int id) {
            _nodes[id].First = ++_time;
            foreach (int next in _nodes[id].Children) {
                if (_nodes[next].First == 0) {
                    DFS(next);
                }
            }
            _nodes[id].last = ++_time;
        }
    }

    class Node {
        public List<int> Children { get; set; }
        public int First { get; set; }
        public int last { get; set; }

        public Node() {
            Children = new List<int>();
        }

        public override string ToString() {
            return First + " " + last;
        }
    }

    class Program {
        static void Main(string[] args) {
            Problem p = new Problem();
            p.Run();
        }
    }
}

