                ans[i] = new int[n];
                for (var j = 2; j < 2 + t[1]; j++)
                {
                    ans[t[0] - 1][t[j] - 1] = 1;
                }
            }

            Dfs();
        }

        static void DfsVisit(int u)
        {
            color[u] = Gray;
            d[u] = ++tt;
            for (var v = 0; v < n; v++)
            {
                if (ans[u][v] == 0) continue;
                if (color[v] == White)
                {
                    DfsVisit(v);
                }
            }
            color[u] = Black;
            f[u] = ++tt;
        }

        static void Dfs()
        {
            for (var u = 0; u < n; u++) color[u] = White;
            tt = 0;

            for (var u = 0; u < n; u++)
            {
                if (color[u] == White) DfsVisit(u);
            }
            for (var u = 0; u < n; u++)
            {
                Console.WriteLine($"{u+1} {d[u]} {f[u]}");
            }
        }
    }
