class Graph
{
    private int n;
    private List<int>[] adj;
    public int[] d;
    public int[] f;
    private bool[] v;
    int t = 1;
    public Graph(int n)
    {
        this.n = n;
        adj = new List<int>[n];
        d = new int[n];
        f = new int[n];
        v = new bool[n];
        for (int i = 0; i < n; i++)
        {
            adj[i] = new List<int>();
        }
    }
    public void SetEdge(int s, int g)
    {
        if (s > n || g > n)
            return;
        adj[s - 1].Add(g);
    }
    public List<int> GetEdge(int i)
    {
        return adj[i - 1];
    }
    public void DFS(int s)
    {
        if (!v[s - 1])
        {
            v[s - 1] = true;
            d[s - 1] = t;
            t++;
            foreach (var i in GetEdge(s))
                if (!v[i - 1])
                    DFS(i);
            f[s - 1] = t;
            t++;
        }
    }
}

