namespace Heaps {
    /// <summary>優先度付きキュー</summary>
    public class PriorityQueue<T> : IEnumerable<T>, IReadOnlyCollection<T> where T : IComparable<T> {
        public List<T> HeapArray { get; }
        public T NIL { get; }

        public int Count => HeapArray.Count;

        /// <param name="heapArray"></param>
        /// <param name="NIL"></param>
        public PriorityQueue(IEnumerable<T> heapArray, T NIL) {
            this.HeapArray = heapArray.ToList();
            this.NIL = NIL;
            BuildMaxHeap();
        }

        public PriorityQueue(T NIL) {
            this.HeapArray = new List<T>();
            this.NIL = NIL;
        }

        /// <summary>idのKeyを取得</summary>
        public T GetValue(int key) {
            if (key <= 0 || key > HeapArray.Count) {
                return NIL;
            }

            return HeapArray[key - 1];
        }

        /// <summary>parentKey [ id / 2 ]</summary>
        public int GetParentKey(int key) {
            return key / 2;
        }

        public int GetLeftKey(int key) {
            return 2 * key;
        }

        public int GetRightKey(int key) {
            return 2 * key + 1;
        }

        /// <summary>max Heap木とする O(N)</summary>
        public void BuildMaxHeap() {
            var n = HeapArray.Count() / 2;
            /// <summary>葉から順に処理を行う</summary>
            for (int i = n; i >= 1; i--) {
                MaxHeapify(i);
            }
        }

        /// <summary>idを根とする部分木について、maxHeap木を維持したまま、idを下降させる</summary>
        private void MaxHeapify(int key) {
            var leftKey = GetLeftKey(key);
            var rightKey = GetRightKey(key);

            var left = GetValue(leftKey);
            var right = GetValue(rightKey);
            var val = GetValue(key);

            int largestKey = key;
            T largestValue = val;

            if (left.CompareTo(NIL) != 0 && left.CompareTo(val) > 0) {
                largestKey = leftKey;
                largestValue = left;
            }

            if (right.CompareTo(NIL) != 0 && right.CompareTo(largestValue) > 0) {
                largestKey = rightKey;
            }

            if (largestKey != key) {
                HeapArray.Swap(key - 1, largestKey - 1);
                MaxHeapify(largestKey); // => 元idのノード
            }
        }

        /// <summary>keyの値を挿入する</summary>
        public void Enqueue(T value) {
            HeapArray.Add(value);

            var insertedKey = HeapArray.Count;
            var parentKey = GetParentKey(insertedKey);

            // 挿入Nodeが根になる or 親 > 子になるまで親とNodeを交換
            while (insertedKey > 1 && value.CompareTo(GetValue(parentKey)) > 0) {
                HeapArray.Swap(insertedKey - 1, parentKey - 1);
                insertedKey = parentKey;
                parentKey = GetParentKey(insertedKey);
            }
        }

        public T Dequeue() {
            if (HeapArray.Count == 0) {
                return NIL;
            }

            var popVal = HeapArray.First();
            var newRootVal = HeapArray.Last();  // 新しい根となる。

            HeapArray.RemoveAt(HeapArray.Count - 1);    // del last

            if (HeapArray.Count > 0) {
                HeapArray[0] = newRootVal;
                MaxHeapify(1);
            }

            return popVal;
        }

        public T Peek() {
            return HeapArray.First();
        }


        public IEnumerator<T> GetEnumerator() {
            while (HeapArray.Count > 0) {
                yield return Dequeue();
            }
        }

        IEnumerator IEnumerable.GetEnumerator() {
            return GetEnumerator();
        }

        public void Clear() {
            HeapArray.Clear();
        }

        public bool Contains(T val) {
            return HeapArray.Contains(val);
        }

        public PriorityQueue<T> Clone() {
            return new PriorityQueue<T>(HeapArray.DeepCopy(), NIL);
        }
    }
}

namespace Extention {
    /// <summary>拡張メソッドs</summary>
    static class MyExtention {
        /// <summary>iとjを入れ替える</summary>
        public static void Swap<T>(this T[] arr, int i, int j) {
            var buf = arr[i];
            arr[i] = arr[j];
            arr[j] = buf;
        }

        public static void Swap<T>(this List<T> list, int i, int j) {
            var buf = list[i];
            list[i] = list[j];
            list[j] = buf;
        }

        /// <summary>
        /// partition。末尾sArr[r]を基準として、左に基準より小さい数、右に基準より大きい数が存在するように配列を並び替える。
        /// </summary>
        /// <param name="sArr"></param>
        /// <param name="p">partitionの先頭の添字</param>
        /// <param name="r">partitionの末尾の添字</param>
        /// <returns>partitionの基準が存在する添字</returns>
        public static int Partition(this int[] sArr, int p, int r) {
            var x = sArr[r];
            var i = p - 1;
            for (int j = p; j < r; j++) {
                if (sArr[j] <= x) {
                    i++;
                    sArr.Swap(i, j);
                }
            }
            sArr.Swap(i + 1, r);
            return i + 1;
        }

        /// <summary>深いコピーをする</summary>
        public static T DeepCopy<T>(this T obj) {
            T result;
            var b = new BinaryFormatter();
            using (var mem = new MemoryStream()) {
                b.Serialize(mem, obj); //  binaryFormatterによりobjをmemにserial化して書き出す
                mem.Position = 0; // memのpotisionを先頭に戻す
                result = (T)b.Deserialize(mem); // memの内容を読み取る。
            }
            return result;
        }

        public static string Left(this string str, int length) {
            return str.Substring(0, length);
        }

        public static string Right(this string str, int length) {
            return str.Substring(str.Length - length, length);
        }

        public static int Find<T>(this T[] array, T obj) {
            return Array.IndexOf(array, obj);
        }

        public static int LastFind<T>(this T[] array, T obj) {
            return Array.LastIndexOf(array, obj);
        }
    }
}

static class MyMath {
    /// <summary>階乗</summary>
    public static long Factorial(int n) {
        if (n == 0) {
            return 1;
        }

        return Permutation(n, 0);
    }

    public static long Permutation(int n, int k) {
        return Enumerable.Range(0, n - k).Select(i => n - i).Aggregate(1, (b, i) => b * i);
    }

    #region FullPower
    /// <summary>総乗、π</summary>
    public static long FullPower(IEnumerable<long> vs) {
        return vs.Aggregate(1L, (a, b) => a * b);
    }

    public static long FullPower(IEnumerable<int> vs) {
        return vs.Aggregate(1L, (a, b) => a * b);
    }
    #endregion

    /// <summary>最大公約数</summary>
    public static long Gcd(long item1, long item2) {
        var a = Math.Max(item1, item2);
        var b = Math.Min(item1, item2);

        while (true) {
            long mod;
            Math.DivRem(a, b, out mod);
            if (mod == 0) {
                break;
            }

            a = b;
            b = mod;
        }
        return b;
    }

    /// <summary>約分。最大公約数で割ったものを返す。</summary>
    public static Tuple<long, long> DeviedByGcd(long item1, long item2) {
        var gcd = Gcd(item1, item2);
        return new Tuple<long, long>(item1 / gcd, item2 / gcd);
    }

    public static long Lcm(int item1, int item2) {
        return Math.BigMul(item1, item2) / Gcd(item1, item2);
    }

    public static ModCombination ModCombination(int maxN, int mod = 1000000007) {
        return new ModCombination(maxN, mod);
    }

    /// <summary>a^n mod</summary>
    public static int ModPow(long a, long n, int mod = 1000000007) {
        long res = 1;
        long pow = a;

        while (n > 0) {
            if ((n & 1) == 1) {
                res = (pow * res) % mod;    // resにaをかける
            }

            pow = (pow * pow) % mod;    // 次のaはa^2
            n >>= 1;
        }

        return (int)res;
    }
}

static class MyMethod {
