        {
            for (int v = 0; v < n; v++)
            {

                if (data[u, v] == 1 && color[v] == White)
                {
                    color[v] = Gray;
                    s.Push(v);
                    des[v] = ++time;
                    return v;
                }
            }

            return -1; 
        }

        static void DfsVisit(int n, int u)
        {

            Stack<int> s = new Stack<int>();


            s.Push(u);
            color[u] = Gray;
            des[u] = ++time;

            while (s.Count != 0)
            {
                u = s.Peek();
                int v = Next(u, n, data, s);


                if (v == -1)
                {
                    color[u] = Black;
                    fin[s.Pop()] = ++time;
                }

            }

        }


