        {


            for (int i = 0; i < n; i++)
            {
                color[i] = White;
            }

            time = 0;  

            for(int u = 0; u < n; u++)
            {
                if (color[u] == White)
                {
                    DfsVisit(n, u);
                }
            }
        }

