function dfs(stack, data, key, colors, time, stamps, way) {
    stack.push(key);
    colors[key] = 'gray';
    stamps[key][0] = time++;

    while (stack.length) {
        key = stack[stack.length - 1];
        const d = data.find(e => e[0] === key);
        const next = getNext(d, way);
        if (next) {
            if (colors[next] === 'white') {
                colors[next] = 'gray';
                stamps[next][0] = time++;
                stack.push(next);
            }
        } else {
            const last = stack.pop();
            colors[last] = 'black';
            stamps[last][1] = time++;
        }
    }
    const untouch = stamps.findIndex((e, i) => i > 0 && !e.length);
    if(untouch > 0){
        dfs(stack, data, untouch, colors, time, stamps, way);
    }
}

function getNext(data, way) {
    const children = data.slice(2);
    if (children.length) {
        for (let child of children) {
            if (way[data[0]][child] === 0) {
                way[data[0]][child] = 1;
                return child;
            }
        }
    } else {
        return null;
    }
}



