def depth_first_search(start)
  return if start.first != 0

  start.first = @count
  @count += 1
  stack = [start]

  until stack.empty? do
    now = stack.pop
    child = now.next_id.map{|x|x}
    child.each do |x|
      if @array[x].first == 0
        @array[x].first = @count
        @count += 1
        stack << now
        stack << @array[x]
        break
      else
        now.next_id.delete(x)
      end
    end

    if now.next_id.empty?
      now.finish = @count
      @count += 1
    end

  end

end


