var n int
var M [N][N]int
var color, d, f [N]int
var tt int

// 再帰関数によるDFS
func dfsVisit(u int) {
	color[u] = GRAY
	tt++
	d[u] = tt // 最初の訪問
	for v := 0; v < n; v++ {
		if M[u][v] == 0 {
			continue
		}
		if color[v] == WHITE {
			dfsVisit(v)
		}
	}
	color[u] = BLACK
	tt++
	f[u] = tt // 訪問の完了
}

func dfs() {
	// 初期化
	for u := 0; u < n; u++ {
		color[u] = WHITE
	}
	tt = 0

	for u := 0; u < n; u++ {
		// 未訪問のuを始点として深さ優先探索
		if color[u] == WHITE {
			dfsVisit(u)
		}
	}
	for u := 0; u < n; u++ {
		fmt.Printf("%d %d %d\n", u+1, d[u], f[u])
	}
}

