let dfs graph =
  let total_time = ref 0 in
  let rec search nd time =
    if nd.stime > 0 then time
    else if nd.nodes == [||] then
      begin
         nd.stime <- time+1;nd.etime <- time+2;time+2
       end
    else
      begin
        nd.stime <- time+1;
        let last_time = ref (time+1) in
        for i = 0 to (Array.length nd.nodes)-1 do
          last_time := search nd.nodes.(i) !last_time
        done;
        nd.etime <- !last_time+1;!last_time+1
      end
  in
  for i = 0 to (Array.length graph)-1 do
    if graph.(i).stime == 0 then total_time := search graph.(i) !total_time
  done
