let dfs vs n =
  let d = Array.make n 0 in
  let f = Array.make n 0 in
  let rec search i time =
    d.(i) <- time;
    let time =
      List.fold_left
        (fun time v ->
          if d.(v-1) = 0 then search (v-1) time
          else time)
        (time + 1) vs.(i) in
    f.(i) <- time;
    time + 1 in
  Array.fold_left (fun (i, time) e ->
    (i + 1, if e = 0 then search i time else time))
    (0, 1) d |> ignore;
  (d, f)

let split_on_char sep s =
  let open String in
  let r = ref [] in
  let j = ref (length s) in
  for i = length s - 1 downto 0 do
    if get s i = sep then begin
      r := sub s (i + 1) (!j - i - 1) :: !r;
      j := i
    end
  done;
  sub s 0 !j :: !r

