fn main() {
    let cin = stdin();
    let cin = cin.lock();
    let mut sc = Scanner::new(cin);
    let n: usize = sc.read();
    let mut g = vec![vec![false;n];n];
    for _ in 0..n {
        let u: usize = sc.read();
        let m: usize = sc.read();
        for _ in 0..m {
            let v: usize = sc.read();
            g[u-1][v-1] = true;
        }
    }

    let mut stack = Vec::new();
    let mut visit = vec![false;n];
    let mut dd = vec![0;n];
    let mut ff = vec![0;n];
