        if visit[p] { continue; }
        stack.push(p);
        t += 1;
        dd[p] = t;
        while let Some(&u) = stack.last() {
            t += 1;
            visit[u] = true;
            let v = g[u].iter().enumerate()
                        .find(|&(i,b)| *b && !visit[i]);
            if let Some((v,_)) = v {
                stack.push(v);
                dd[v] = t;
            } else {
                stack.pop();
                ff[u] = t;
            }
        }
    }

