use std::io;
use std::io::BufRead;

struct Graph {
    n: usize,
    adj: Vec<Vec<usize>>,
}

fn read_graph() -> Graph {
    let stdin = io::stdin();
    let lock = stdin.lock();
    let mut lines = lock.lines();
    let n = lines.next().unwrap().unwrap().parse().unwrap();
    let mut adj = Vec::new();

    for line in lines {
        let parsed: Vec<usize> = line
            .unwrap()
            .split_whitespace()
            .map(|s| s.parse().unwrap())
            .collect();

        adj.push(parsed[2..].iter().map(|x| x - 1).collect());
    }

    Graph { n, adj }
}

fn dfs(g: &Graph, d: &mut Vec<usize>, f: &mut Vec<usize>, t: &mut usize, i: usize) {
    *t += 1;
    d[i] = *t;
    for &next_i in g.adj[i].iter() {
        if d[next_i] == 0 {
            dfs(g, d, f, t, next_i);
        }
    }
    *t += 1;
    f[i] = *t;
}

fn main() {
    let graph = read_graph();

    let mut d = vec![0; graph.n];
    let mut f = vec![0; graph.n];
    let mut t = 0;

    for i in 0..(graph.n) {
        if d[i] == 0 {
            dfs(&graph, &mut d, &mut f, &mut t, i);
        }
    }

    for i in 0..(graph.n) {
        println!("{} {} {}", i + 1, d[i], f[i]);
    }
}

