fn dfs(graph: &Vec<Vec<usize>>, cur: usize, timestamp: &mut usize, visited: &mut Vec<bool>, log: &mut Vec<(usize, usize)>) {
    // dbg!(&timestamp);
    if !visited[cur] {
        visited[cur] = true;
        log[cur] = (timestamp.clone(), 0);
        *timestamp = *timestamp + 1;
        for v in graph[cur].iter() {
            dfs(graph, *v, timestamp, visited, log);
        }
        log[cur] = (log[cur].0, timestamp.clone());
        *timestamp = *timestamp + 1;
    }
}

