type Graph = Vec<Vec<usize>>;

struct Solver {
    visited: Vec<bool>,
    preord: Vec<Option<usize>>,
    postord: Vec<Option<usize>>,
    i_count: usize,
}

impl Solver {
    fn dfs(&mut self, g: &Graph, v: usize) {
        self.visited[v] = true;
        self.preord[v] = Some(self.i_count);
        self.i_count += 1;

        for &w in g[v].iter() {
            if self.visited[w] {
                continue;
            }
            self.dfs(g, w);
        }

        self.postord[v] = Some(self.i_count);
        self.i_count += 1;
    }

    fn dfs_wrapped(&mut self, g: &Graph) {
        for s in 0..g.len() {
            if self.visited[s] {
                continue;
            }
            self.dfs(g, s);
        }
    }
}

