/// d: 訪問時刻
/// f: 終了時刻
/// idx: 対象の添え字
/// time: 現在時刻
fn dfs(vec: &Vec<Vec<usize>>, d: &mut Vec<Option<u32>>, f: &mut Vec<Option<u32>>, idx: usize, time: u32) -> u32 {
    if d[idx].is_none() {
        let mut time = time + 1;
        d[idx] = Some(time);    // 現在時刻を1つ進め、訪問として記録
        for i in vec[idx].iter() {
            time = dfs(vec, d, f, *i, time);
        }
        time += 1;  // 現在時刻を1つ進め、終了時刻として記録
        f[idx] = Some(time);
        time
    } else {
        // 訪問済みなら何もしない
        time
    }
}

fn main() {
    let sin = io::stdin();
    let sin = sin.lock();
    let mut sc = Scanner::new(sin);

    let n: usize = sc.read();
    let vec: Vec<Vec<usize>> = (0..n).map(|_| {
            let _i: usize = sc.read();
            let k: usize = sc.read();
            (0..k).map(|_| sc.read::<usize>() - 1)  // index変換に1減らす
                .collect::<Vec<usize>>()
        }).collect();
    let mut stamp_start: Vec<Option<u32>> = vec![None; n];   // Noneの時未訪問とする
    let mut stamp_end: Vec<Option<u32>> = vec![None; n];   // Noneの時未訪問とする

    let mut time = 0;
    for i in 0..n {
        time = dfs(&vec, &mut stamp_start, &mut stamp_end, i, time);
    }

    for i in 0..n {
        println!("{} {} {}", i+1, stamp_start[i].unwrap(), stamp_end[i].unwrap());
    }
}

use std::io::Read;
use std::collections::VecDeque;

fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();

    let answer = solve(&buf);

    println!("{}", answer);
}

fn solve(input: &str) -> String {
    let mut iterator = input.split_whitespace();

    let n: usize = iterator.next().unwrap().parse().unwrap();
    let mut g: Vec<VecDeque<usize>> = vec![VecDeque::new(); n];
    for _ in 0..n {
        let u: usize = iterator.next().unwrap().parse().unwrap();
        let k: usize = iterator.next().unwrap().parse().unwrap();
        for _ in 0..k {
            let v: usize = iterator.next().unwrap().parse().unwrap();
            g[u - 1].push_back(v - 1);
        }
    }

    let mut t: usize = 1;
    let mut d: Vec<usize> = vec![0; n];
    let mut f: Vec<usize> = vec![0; n];
    let mut stack: Vec<usize> = Vec::new();
    while d.iter().any(|it| *it == 0) {
        let i = d.iter().enumerate().find(|&(_, &di)| di == 0).unwrap().0;
        stack.push(i);
        d[i] = t;
        t += 1;
        while !stack.is_empty() {
            if !g[*stack.last().unwrap()].is_empty() {
                let i2 = g[*stack.last().unwrap()].pop_front().unwrap();
                if d[i2] == 0 {
                    stack.push(i2);
                    d[i2] = t;
                    t += 1;
                }
            } else {
                let top = stack.pop().unwrap();
                f[top] = t;
                t += 1;
            }
        }
    }

    let mut result = String::new();
    for i in 0..n {
        result.push_str(&format!("{} {} {}\n", i + 1, d[i], f[i]));
    }
    return result.trim().to_string();
}

fn solver(
    pos: usize,
    g: &Vec<Vec<usize>>,
    dis: &mut Vec<usize>,
    fin: &mut Vec<usize>,
    time: &mut usize,
) {
    for j in &g[pos] {
        if dis[*j - 1] == 0 {
            *time += 1;
            dis[*j - 1] = *time;
            solver(*j - 1, &g, dis, fin, time);
        }
    }
    *time += 1;
    fin[pos] = *time;
}

fn main() {
    let mut buf = String::new();
    let _ = std::io::stdin().read_line(&mut buf).ok();
    let n: usize = buf.trim().parse().unwrap();
    let mut g = Vec::new();
    for _ in 0..n {
        let mut buf = String::new();
        let _ = std::io::stdin().read_line(&mut buf).ok();
        let mut buf = buf.split_whitespace();
        let _: usize = buf.next().unwrap().parse().unwrap();
        let k: usize = buf.next().unwrap().parse().unwrap();
        let mut e = Vec::new();
        for _ in 0..k {
            let p: usize = buf.next().unwrap().parse().unwrap();
            e.push(p);
        }
        g.push(e);
    }
    let mut dis = vec![0; n];
    let mut fin = vec![0; n];
    let mut time = 0;
    for i in 0..n {
        if dis[i] == 0 {
            time += 1;
            dis[i] = time;
            solver(i, &g, &mut dis, &mut fin, &mut time);
            //println!("{:?}", dis);
            //println!("{:?}", fin);
            //println!();
        }
    }
    //solver(0, &g, &mut dis, &mut fin, &mut time);
    //println!("{:?}", g);
    //println!("{:?}", dis);
    //println!("{:?}", fin);
    for i in 0..n {
        println!("{} {} {}", i + 1, dis[i], fin[i]);
    }
}
